window.JASTROW_CHUNKS[19]={"7600":{"h":"גִּיעֲגוּעַ","r":"C00784","html":"<div class=\"sense\">, v. <span dir=\"rtl\">גִּעֲ׳</span></div>","alt":[]},"7601":{"h":"גִּיעוּל I","r":"C00785","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּעַל\">גָּעַל</a>) <i>the cleaning of an impure vessel</i> by means of boiling water (<span class=\"citation\">Num. XXXI, 23</span>), v. <a href=\"#\" data-headword=\"הַגְעָלָה\">הַגְעָלָה</a>. <span class=\"citation\">Zeb. 97ᵃ</span>; <span class=\"citation\">Ab. Zar. 76ᵃ</span> <span dir=\"rtl\">כל יום … ג׳ לחבירו</span> every day the boiling done in the sacred vessel is the means of absorbing the soakings of the previous day.—Pl. <span dir=\"rtl\">גִּיעוּלִים</span>, constr. <span dir=\"rtl\">גִּיעוּלֵי</span>; (<span dir=\"rtl\">גוים</span>, <span dir=\"rtl\">עכו&quot;ם</span>) <span dir=\"rtl\">ג׳ גכרים</span> vessels of gentiles which require cleaning with boiling water before they may be used by Jews. Ib. 67ᵇ; 75ᵇ; a. fr.</div>","alt":[]},"7602":{"h":"גִּיעוּל II","r":"C00786","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּעַל\">גָּעַל</a>, v. <span class=\"citation\">Job XXI, 10</span>), pl. constr. <span dir=\"rtl\">גִּיעוּלֵי</span>, <span dir=\"rtl\">ג׳ בצים</span> <i>abortive eggs</i> driven off by striking the hen. <span class=\"citation\">Tosef. Ter. IX, 5</span>; Y. ib. X, 47ᵇ bot.; <span class=\"citation\">Ḥull. 64ᵇ</span> (Rashi: <i>eggs scalded in hot water</i> together with forbidden eggs, v. <a href=\"#\" data-headword=\"גִּיעוּל I\">preced.</a>).</div>","alt":[]},"7603":{"h":"גֵּיף","r":"C00787","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>side, shore.</i> <span class=\"citation\">Makhsh. I, 4</span> על ג׳ הנהר Ar. (ed. <a href=\"#\" data-headword=\"גַּב\">גַּב</a>, R. Hai Gaon <a href=\"#\" data-headword=\"גַּף I\">גַּף</a>, v. Koh. Ar. Compl. s. v. note 9).</div>","alt":[]},"7604":{"h":"גֵּיף ²","r":"C00788","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Ex. XIV, 9</span>. <span class=\"citation\">Ib. XV, 9</span> (Y. II some ed. <a href=\"#\" data-headword=\"גַּף I\">גַּף</a>). Ib. II, 5 (Y. II <a href=\"#\" data-headword=\"גַּב\">גַּב</a>, O. <a href=\"#\" data-headword=\"כֵּיף\">כֵּיף</a>); a. e.—Y. Kidd. I, 58ᵈ; <span class=\"citation\">Y. Keth. VI, end 31ᵃ</span> <span dir=\"rtl\">אייתיבוני על ג׳ נהרא וכ׳</span> place me at the shore of a river, and if I do not …, cast me into the river. Ib. XIII, 35ᵇ bot. (<a href=\"#\" data-headword=\"גּוּף\">גוף</a>, corr. acc.); <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> bot.; a. fr.</div>","alt":["גֵּיפָא"]},"7605":{"h":"*גִּיף","r":"C00789","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (גּוּף I) <i>adultery, sensuality</i>. <span class=\"citation\">Sabb. 104ᵃ</span>, v. <a href=\"#\" data-headword=\"אח\">אח&quot;ס</a>.</div>","alt":[]},"7606":{"h":"גַּיָּפָא","r":"C00790","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּיָּיפָא\">גַּיָּיפָא</a></div>","alt":[]},"7607":{"h":"גִּיפּוּף","r":"C00791","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גפף</span>) </div><div class=\"sense\"><b>1)</b> <i>embracing, hugging</i>. <span class=\"citation\">Snh. 56ᵇ</span> <span dir=\"rtl\">ג׳ ונישוק</span> embracing and kissing idols.</div><div class=\"sense\"><b>—2)</b> <i>closing up</i>. <span class=\"citation\">Y. Sabb. III, 5ᵈ</span> bot. <span dir=\"rtl\">אחר גִּיפּוּפוֹ</span> according as the stove is closed up.</div>","alt":[]},"7608":{"h":"גִּיפּוּף ²","r":"C00792","html":"<div class=\"sense\">(cmp. <a href=\"#\" data-headword=\"גִּיפּוּף\">preced.</a>) <i>railing, rim</i>. <span class=\"citation\">Targ. Y. Ex. XXV, 25</span>; <span class=\"citation\">27</span> (h. text <a href=\"#\" data-headword=\"מִסְגֶּרֶת\">מסגרת</a>; O. <a href=\"#\" data-headword=\"גְּדָנְפָא\">גדנפא</a>).—Pl. <span dir=\"rtl\">גִּיפוּפִין</span>, <span dir=\"rtl\">גִּיפוּפֵי</span>. <span class=\"citation\">Targ. Y. I Deut. XXII, 8</span> (<span class=\"citation\">II</span> <span dir=\"rtl\">גופוף</span>). <span class=\"citation\">Erub. 89ᵇ</span></div>","alt":["גֵּיפּוּפָא","גִּפּ׳","גֵּפ׳"]},"7609":{"h":"גִּיפְטִי","r":"C00793","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Αἰγύπτιος) <i>Epyptian, Coptic</i>.—Pl. <a href=\"#\" data-headword=\"גִּיפְטִי\">גִּיפְטִים</a>. <span class=\"citation\">Meg. 18ᵃ</span> <span dir=\"rtl\">גיפטית לג׳</span> (Ar. <span dir=\"rtl\">גפתית לגפתים</span>) to Egyptian Jews &amp;c.—Fem. <a href=\"#\" data-headword=\"גִּיפְטִי\">גִּיפְטִית</a> <i>in Egyptian or Coptic language</i>. Ib.—<span class=\"citation\">Sabb. 115ᵃ</span>. <span class=\"citation\">Ib. 115ᵇ</span> <span dir=\"rtl\">תנא דג׳</span> the author of the rule concerning sacred writings in Egyptian &amp;c. (<span class=\"citation\">ib.ᵃ</span>). Cmp. <a href=\"#\" data-headword=\"*גִּיוָוטָאֵי\">גִּיוָוטָאֵי</a>.</div>","alt":[]},"7610":{"h":"גיפן","r":"C00794","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גּוֹפֶן\">גּוֹפֶן</a></div>","alt":[]},"7611":{"h":"גִּיפְסוֹס","r":"C00795","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (γύψος) <i>gypsum</i>. <span class=\"citation\">Y. Sabb. II, 5ᵃ</span> top; v. <a href=\"#\" data-headword=\"גִּפְסִים\">גִּפְסִים</a>.</div>","alt":[]},"7612":{"h":"גִּיפְסִים","r":"C00796","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּפְסִים\">גִּפְסִים</a></div>","alt":["גיפסיס"]},"7613":{"h":"גִּיפֵּף","r":"C00797","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּפַף\">גָּפַף</a></div>","alt":[]},"7614":{"h":"גִּיפֵּר","r":"C00798","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּפַר\">גָּפַר</a></div>","alt":[]},"7615":{"h":"גִּיפְתָּא","r":"C00799","html":"<div class=\"sense\"> a sort of <i>peat</i> or <i>turf</i>. <span class=\"citation\">Y. Sabb. IV, 6ᵈ</span> [read:] <span dir=\"rtl\">כמראי גו ג׳</span> I kept it warm in <i>gifta</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">על ג׳</span> on top of <i>g</i></div>","alt":["(גּוּפְ׳)"]},"7616":{"h":"גיפתי","r":"C00800","html":"<div class=\"sense\">, <span class=\"citation\">Erub. 64ᵃ</span> (missing in Ms. M.), marginal version <a href=\"#\" data-headword=\"דִּיפְתִּי\">דִּיפְתִּי</a> q. v.</div>","alt":[]},"7617":{"h":"גֵּיפְתָן","r":"C00801","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גֵּיוְתָא\">גֵּיוְתָ׳</a></div>","alt":["גֵּיפְתָנָא","גֵּיפְתָנוּתָא"]},"7618":{"h":"גֵּיצָא","r":"C00802","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>spark</i>. <span class=\"citation\">Targ. Job XVIII, 5</span> Ms. Var. for <a href=\"#\" data-headword=\"גִּיהַּ\">גִּיהַּ</a>.—Pl. <span dir=\"rtl\">גֵּיצִין</span>, <span dir=\"rtl\">גִּיצִין</span>. <span class=\"citation\">Targ. Job V, 7</span> (Ms. <span dir=\"rtl\">גֵּי׳</span> (ed. <span dir=\"rtl\">גִּי׳</span>, ed. Vien. <span dir=\"rtl\">נצין</span>). <span class=\"citation\">Ib. XLI, 11</span> Ms. (ed. <a href=\"#\" data-headword=\"גּוּצִין\">גּוּצִין</a>). <span class=\"citation\">Targ. Ps. CXL, 11</span> (ed. Vien. <span dir=\"rtl\">ניצין</span>).</div>","alt":[]},"7619":{"h":"*גִּיר I","r":"C00803","html":"<div class=\"sense\"> (Syriac <a href=\"#\" data-headword=\"גִּיר\">גיר</a>, P. Sm. 709 sq., prob. fr. <a href=\"#\" data-headword=\"גָּרַר I\">גרר</a>, cmp. <a href=\"#\" data-headword=\"גְּרָרָא I\">גְּרָרָא</a>) <i>as a consequence, for</i> &amp;c. <span class=\"citation\">Targ. Prov. XXIX, 19</span> (agreeing with Peshito) <span dir=\"rtl\">ידע ג׳ דלא בליע</span> ed. Lag. (Var. <a href=\"#\" data-headword=\"וָלָא\">ולא</a>, ed. <span dir=\"rtl\">דידע ג׳ ולא וכ׳</span>, Peshito … <span dir=\"rtl\">בלע</span>) for he understands (from being spoken to) only that he will receive no blows. [<span class=\"citation\">Ib. XXIII, 14</span> אנת ביר וכ׳ Ms. (missing in ed.), read: <a href=\"#\" data-headword=\"גִּיר\">גיר</a></div>","alt":[]},"7620":{"h":"גִּיר II","r":"C00804","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> or <a href=\"#\" data-headword=\"גּוּר\">גור</a> <i>to boil, effervesce</i>, v. H., v. H. Dict. s. v.) </div><div class=\"sense\"><b>1)</b> <i>lime</i>. <span class=\"citation\">Sabb. 80ᵇ</span> ביצת הג׳ Ar. (ed. <span dir=\"rtl\">הסיד</span>), v. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a>.—Denom. <a href=\"#\" data-headword=\"גִּיֵּיר\">גִּיֵּיר</a> <i>to plaster</i>. <span class=\"citation\">Lam. R. to IV, 11</span> Ar. (ed. <span dir=\"rtl\">סייד</span>).—<span class=\"citation\">Ḥull. 88ᵇ</span> bot. <span dir=\"rtl\">הג׳ והזרניך</span> quot. in Rashi to <span class=\"citation\">Ex. XVI, 14</span> (ed. only <span dir=\"rtl\">הז׳</span>) powdered lime and orpiment.</div><div class=\"sense\"><b>—2)</b> <i>ink-stone</i>, or <i>sulphate of iron</i> (<i>sory</i>). <span class=\"citation\">Bets. 15ᵃ</span> <span dir=\"rtl\">ביצת הג׳</span> a lump of ink-stone (for blackening leather).—In gen. <i>powder</i>, in compounds <a href=\"#\" data-headword=\"גִּירְגִּבְסִין\">גִּירְגִּבְסִין</a> <i>powder of gypsum;</i> גִּירְקְרָרִין <i>wax dust</i>, v. <a href=\"#\" data-headword=\"*אַגֵּין\">אַגֵּין</a></div><div class=\"sense\"><b>—3)</b> <i>froth</i>. <span class=\"citation\">Men. VIII, 7</span> (<span class=\"citation\">87ᵃ</span>) <span dir=\"rtl\">זרק הג׳</span> (Mish. <span dir=\"rtl\">ז׳ את הגיד</span>, corr. acc.) if the froth (of the fermenting wine) burst forth; Tosef. ib. IX, 11 <span dir=\"rtl\">ג׳ של שמרים</span>.</div>","alt":[]},"7621":{"h":"גִּיר","r":"C00805","html":"<div class=\"sense\">, <i>lime, plaster.</i> <span class=\"citation\">Dan. V, 5</span>.—<span class=\"citation\">Targ. O. Ex. XVI, 14</span> <span dir=\"rtl\">דעדק כג׳</span> thin and brittle like a coat of lime (h. text <span dir=\"rtl\">מחספס</span>). <span class=\"citation\">Targ. Y. Deut. XXVII, 2</span> (h. text <a href=\"#\" data-headword=\"סִיד I\">סיד</a>); a. e.—2) <i>froth, foam. </i> Pl. <span dir=\"rtl\">גִּירִין</span> <span class=\"citation\">Targ. Y. Ex. XV, 10</span> <span dir=\"rtl\">ג׳ דימא</span> the foaming billows. [<span class=\"citation\">Targ. Jer. IX, 14</span>, read <span dir=\"rtl\">כגידין</span>, v. <a href=\"#\" data-headword=\"גִּידָּא II\"><span dir=\"rtl\">גִּידָּא</span> II</a>.]—3) name of <i>a disease, a sort of fever</i> (<i>?</i>). <span class=\"citation\">Gitt. 69ᵇ</span>, v. <a href=\"#\" data-headword=\"גִּיר III\">next w.</a></div>","alt":["גִּירָא I"]},"7622":{"h":"גִּיר III","r":"C00806","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גרי\">גרי</a>, <a href=\"#\" data-headword=\"גָּרַר I\">גרר</a>; cmp. b. h. <a href=\"#\" data-headword=\"שֶׁלַח\">שֶׁלַח</a>) </div><div class=\"sense\"><b>1)</b> <i>projectile, arrow</i>. <span class=\"citation\">Targ. Is. XXXVII, 33</span>. <span class=\"citation\">Targ. Job XLI, 20</span>; a. fr.—<span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">שדא ג׳ וכ׳</span> he shot an arrow eastward. <span class=\"citation\">B. Kam. 26ᵇ</span> <span dir=\"rtl\">בעידנא דשדייה פסוקי מפסקי גִירֵיה</span> (v. Rabb. D. S. a. l. note) at the time he let his arrow off, its force was broken, i.e. when he threw the vessel down, polsters were there to prevent its breaking. <span class=\"citation\">Succ. 38ᵃ</span> <span dir=\"rtl\">דין ג׳ בעיניה וכ׳</span> this is an arrow in the tempter’s eyes, i.e. this enables us to defy him. <span class=\"citation\">Kidd. 30ᵃ I</span> should say to Satan <span dir=\"rtl\">ג׳ בעיניך</span> I defy thee; <span class=\"citation\">ib. 81ᵃ</span>.—<span class=\"citation\">Taan. 25ᵃ</span> אגרי בך גִירַי I shall let my arrow loose against thee (v. Rabb. D. S. a. l. note; oth. vers. v. <a href=\"#\" data-headword=\"גּוּר\">גּוּר</a> I ch.). <span class=\"citation\">Pes. 28ᵃ</span>, v. <a href=\"#\" data-headword=\"גִּירָאָה\">גִּירָאָה</a>; a. fr.—<span dir=\"rtl\">ג׳ דלילתא</span> (Ar. <span dir=\"rtl\">דלוליתא</span>) the arrow of Lilith, supposed to be a wedge-shaped meteoric stone. <span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">לגירא ליתי ג׳ דל׳</span> as a remedy for <i>gira</i> (v. <a href=\"#\" data-headword=\"גִּיר\">preced.</a>) let one get a <i>gira</i> of &amp;c.—Pl. <span dir=\"rtl\">גִּירִין</span>, <a href=\"#\" data-headword=\"גֵּירִי\">גִּירֵי</a>, <span dir=\"rtl\">גִּירַיָּא</span>; <span dir=\"rtl\">גִּירְרִין</span>, <span dir=\"rtl\">גִּירְרַיָּא</span>. <span class=\"citation\">Targ. II Sam. I, 22</span>. <span class=\"citation\">Targ. Y. I Gen. XLIX, 23</span>, <span class=\"citation\">Targ. Y. II, Gen. XLIX, 23</span> (not <span dir=\"rtl\">גיד׳</span>). <span class=\"citation\">Targ. Ps. CXX, 4</span>; a. fr.—<span class=\"citation\">Snh. 108ᵇ</span> <span dir=\"rtl\">גילי והוו ג׳</span> he threw chaff and it turned into arrows. <span class=\"citation\">B. Bath. 73ᵃ</span>; v. <span dir=\"rtl\">בְּזַק</span>. Y. ib. II, 13ᵇ bot. <span dir=\"rtl\">מן קל גורי וכ׳</span> (corr. acc.) from the hissing sound of the arrows; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>shoot</i> of a plant. Pl. <a href=\"#\" data-headword=\"גֵּירִי\">גִּירֵי</a>. <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">ג׳ דרוביא</span> shoots of fenugreek; (oth. opin. in Ar. <i>flax-seeds</i>, Ms. O. <a href=\"#\" data-headword=\"גִּידָּא I\">גידא</a>, v. <a href=\"#\" data-headword=\"גִּידָּא I\"><span dir=\"rtl\">גִּידָּא</span> I</a>).</div>","alt":["גִּירָא II","גִּירְרָא"]},"7623":{"h":"גִּירָא III","r":"C00807","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּרַר I\">גרר</a>; cmp. <a href=\"#\" data-headword=\"גְּרָרָא I\">גְּרָרָא</a>) <i>direct consequence</i> of an act. . <span class=\"citation\">B. Bath. 22ᵇ</span> <span dir=\"rtl\">בגירי דידיה</span> (Rashi <span dir=\"rtl\">דיליה</span>); <span class=\"citation\">ib. 25ᵇ</span> sq. <span dir=\"rtl\">בגִירֵיה דיליה</span> (Ms. M. only <span dir=\"rtl\">בגיריה</span>, v. Rabb. D. S. a. l. note); <span class=\"citation\">B. Mets. 117ᵃ</span> <span dir=\"rtl\">בגירי דיליה</span> when the damage is a direct result of his act. <span class=\"citation\">Ib. 44ᵃ</span> <span dir=\"rtl\">גירי דידיה וכ׳</span> it is his act that helped it (to get sour). [Rashi: <i>his arrows</i> in a metaphorical sense, v. preced.]</div>","alt":[]},"7624":{"h":"גִּירָא IV","r":"C00808","html":"<div class=\"sense\"> pr. n. f., v. <a href=\"#\" data-headword=\"גִּילָא I\">גִּילָא</a></div>","alt":[]},"7625":{"h":"גֵּירָא","r":"C00809","html":"<div class=\"sense\"> . <span class=\"citation\">Taan. 25ᵃ</span>, v. <a href=\"#\" data-headword=\"גּוּר\">גּוּר</a> I ch.</div>","alt":[]},"7626":{"h":"גִּירָאָה","r":"C00810","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"גִּיר III\"><span dir=\"rtl\">גִּירָא</span> II</a>) <i>shooter</i>, (Rashi:) <i>arrow-maker</i>. <span class=\"citation\">Pes. 28ᵃ</span> (prov.) <span dir=\"rtl\">ג׳ בגִירֵיה מקטיל וכ׳</span> (ed. <a href=\"#\" data-headword=\"גֵּירָא\">גירא</a>, corr. acc., v. Rabb. D. S. a. l. note) when the shooter (arrow-maker) is killed by his own arrow, he is paid from the spinnings of his own hand.</div>","alt":[]},"7627":{"h":"גִּירְגִּבְסִין","r":"C00811","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּיר II\"><span dir=\"rtl\">גֵּיר</span> II</a>, 2).</div>","alt":[]},"7628":{"h":"גִּירְגֵּר","r":"C00812","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּרַר I\">גָּרַר</a></div>","alt":[]},"7629":{"h":"גִּירְדָּא I","r":"C00813","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּרַד\">גְּרַד</a>) <i>scraping, rind</i>. <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">גי׳ דאסניתא</span> (ed. <span dir=\"rtl\">גו׳ דאסינתא</span>) the paring of &amp;c., v. <a href=\"#\" data-headword=\"אַסְנִיתָא\">אַסְנִיתָא</a>. <span class=\"citation\">Keth. 77ᵇ</span>, v. <a href=\"#\" data-headword=\"*אַשְׁפָּא\">אַשְׁפָּא</a>. <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">גְּרָדָא דיבלא וגי׳ דאסנא</span> (Ms. M. <span dir=\"rtl\">גררא … וגוררא</span>, early ed. <span dir=\"rtl\">וגורדא</span>) scraped root of cynodon and the paring of the bramble. <span class=\"citation\">Sot. 10ᵇ</span>; <span class=\"citation\">Num. R. s. 9</span> (prov.) <span dir=\"rtl\">קמי דשתי חמרא חמרא קמי רפוקא גי׳ דיבלא</span> before wine drinkers, place wine; before a ploughman—a dish of scraped roots &amp;c. V. <a href=\"#\" data-headword=\"גַּרְדָּא\">גַּרְדָּא</a>.</div>","alt":[]},"7630":{"h":"גִּירְדָּא II","r":"C00814","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּדַד I\">גדד</a>, with <a href=\"#\" data-headword=\"ר\">ר</a> inserted) <i>stump, stem</i>. <span class=\"citation\">Pes. 111ᵇ</span> top <span dir=\"rtl\">גי׳ דדיקלא</span> (Var. <a href=\"#\" data-headword=\"גִּידָּא I\">גידא</a>, <a href=\"#\" data-headword=\"גּוּדָּא I\">גודא</a>, v. Rabb. D. S. a. l. note 30) the stem of a palm tree (Ar.: <i>rind</i>, v. <a href=\"#\" data-headword=\"גִּירְדָּא I\">preced.</a>). <span class=\"citation\">B. Mets. 86ᵃ</span> (Ms. M. <span dir=\"rtl\">גידרא</span>, Ms. R. 2 <span dir=\"rtl\">גיררא</span>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"7631":{"h":"גִּירְדָּא","r":"C00815","html":"<div class=\"sense\">, v. <span dir=\"rtl\">גַּרְדּ׳</span></div>","alt":["גִירְדַּאי"]},"7632":{"h":"גִּירְדּוֹנָא","r":"C00816","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"*גַּיְידּוֹר\">גַּיְידּוֹר</a>) <i>a young ass.</i> <span class=\"citation\">Ned. 41ᵃ</span></div>","alt":["(גִּידְרוֹנָא)"]},"7633":{"h":"גִּירְדַּי","r":"C00817","html":"<div class=\"sense\">, v. <span dir=\"rtl\">גַּרְדּ׳</span></div>","alt":["גִּירְדָּנָא"]},"7634":{"h":"גֵּירָה","r":"C00818","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גרי\">גֵּרָה</a></div>","alt":[]},"7635":{"h":"גִּירָה","r":"C00819","html":"<div class=\"sense\">, Pi. of <a href=\"#\" data-headword=\"גרי\">גרי</a>.</div>","alt":[]},"7636":{"h":"גֵּירוּי","r":"C00820","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גרי\">גרי</a>) <i>instigation, provocation, stirring up</i>. <span class=\"citation\">Sifré Deut. 87</span>, v. <a href=\"#\" data-headword=\"הַסָּתָה\">הַסָּתָה</a>; <span class=\"citation\">Yalk. ib. 886</span>. Tanḥ. Balak. 2 (ref. to <span class=\"citation\">Deut. II, 19</span>) <span dir=\"rtl\">כל מיני ג׳</span> any sort of provocation (is forbidden); <span class=\"citation\">Num. R. s. 20</span>, beg. <a href=\"#\" data-headword=\"גירור\">גירור</a> (corr. acc.); <span class=\"citation\">Yalk. ib. 765</span>.</div>","alt":[]},"7637":{"h":"גֵּירוּמִים","r":"C00821","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּרַם I\">גרם</a>) <i>that which goes along, customary addition to weight</i> or <i>measure</i> at sales. <span class=\"citation\">B. Bath. VI, 11</span> <span dir=\"rtl\">נותן לו גֵּירוּמָיו</span> (Bab. ed. 88ᵇ <span dir=\"rtl\">מין …</span>, Y. ed. … <a href=\"#\" data-headword=\"מַיִם\">מים</a>) he must give him the due surplus. Sifra K’doshim Par. 9, ch. VIII.</div>","alt":["גֵּירוּמִין"]},"7638":{"h":"גירומסין","r":"C00822","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גרמסין\">גרמסין</a></div>","alt":[]},"7639":{"h":"גירונין","r":"C00823","html":"<div class=\"sense\">, <span class=\"citation\">Targ. II Chr. XX, 25</span>, some ed., read <span dir=\"rtl\">ריגונין</span>.</div>","alt":[]},"7640":{"h":"גֵּירוּעַ I","r":"C00824","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּרַע I\">גָּרַע</a>) I) <i>deduction</i> from the price of redemption according to the years of possession (<span class=\"citation\">Lev. XXVII, 18</span>). <span class=\"citation\">Arakh. 24ᵃ</span> <span dir=\"rtl\">ליגאל בג׳</span> to be redeemed with due deduction. <span class=\"citation\">B. Mets. 106ᵃ</span> the Sabbath year <span dir=\"rtl\">לא תעלה לו בג׳</span> Ar. (ed. <span dir=\"rtl\">מן הג׳</span>, v. Rabb. D. S. s. l. note 90) ought not to be counted in for deduction.—Pl. <a href=\"#\" data-headword=\"גֵּרוּעַ\">גֵּירוּעִין</a>. <span class=\"citation\">Y. Shebu. VI, beg. 36ᵈ</span> <span dir=\"rtl\">סוף גֵּירוּעֶיהָ</span> the final redemption of the Hebrew hand-maid.</div>","alt":[]},"7641":{"h":"גֵּירוּעַ II","r":"C00825","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (גָּרַע II) <i>the formation of globules</i> or <i>kernels</i> in the grape. <span class=\"citation\">Ber. 36ᵇ</span>; <span class=\"citation\">Pes. 53ᵃ</span> <span dir=\"rtl\">הוא בוסר הוא ג׳</span>, v. <a href=\"#\" data-headword=\"בֹּוסֶר\">בּוֹסֶר</a>.</div>","alt":["גֵּרוּעַ"]},"7642":{"h":"גירור","r":"C00826","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גֵּירוּי\">גֵּירוּי</a></div>","alt":[]},"7643":{"h":"גֵּירוּשִׁין","r":"C00827","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גֵּרוּשִׁין\">גֵּרוּשִין</a></div>","alt":[]},"7644":{"h":"גֵּירוּת","r":"C00828","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גֵּרוּת\">גֵּרוּת</a></div>","alt":[]},"7645":{"h":"גִּירוּתָא","r":"C00829","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>girutha</i>, name of an unclean bird, supposed to be <i>moor-hen</i>. <span class=\"citation\">Ḥull. 62ᵇ</span>; <span class=\"citation\">Nidd. 50ᵇ</span> expl. <i>the hen of the marshes</i>. <span class=\"citation\">Ḥull. 109ᵇ</span> we are forbidden <a href=\"#\" data-headword=\"ג׳\">ג׳</a> to eat <i>girutha</i>. [Ar. <a href=\"#\" data-headword=\"גּוּרְיְתָא\">גּוּרִיתָא</a>, v. Koh. Ar. Compl. II, 378ᵃ.]</div>","alt":[]},"7646":{"h":"גֵּירִי","r":"C00830","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"גֵּר\">גֵּר</a>) <i>belonging to a convert family, descendant of proselytes</i>. <span class=\"citation\">Kidd. IV, 1</span> (collectively); v. Tos’foth Yom Tob a. l. s. v. <a href=\"#\" data-headword=\"כֹּהֲנִי\">כהני</a>.</div>","alt":[]},"7647":{"h":"גִּירְמָא","r":"C00831","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּרְמָא\">גַּרְמָא</a></div>","alt":[]},"7648":{"h":"גִּירְמַנְיָא","r":"C00832","html":"<div class=\"sense\">, v. <span dir=\"rtl\">גִּרְמַ׳</span></div>","alt":["גִּירְמַנִיקִי"]},"7649":{"h":"גִּירְסָא I","r":"C00833","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (גְּרַס II) <i>acquired learning, tradition, study by heart</i>. <span class=\"citation\">Targ. Cant. I, 2</span> <span dir=\"rtl\">בג׳</span> for study by heart (oral tradition).—<span class=\"citation\">Meg. 6ᵇ</span> <span dir=\"rtl\">לאוקומי ג׳ וכ׳</span> to preserve (remember) what one has learned, requires divine assistance. <span class=\"citation\">Sabb. 21ᵇ</span> <span dir=\"rtl\">ג׳ דינקותא</span> acquired in early youth (which is better remembered). <span class=\"citation\">Ib. 30ᵇ</span> <span dir=\"rtl\">לא … פומיה מג׳</span> did not cease studying by heart; <span class=\"citation\">B. Mets. 86ᵃ</span> <span dir=\"rtl\">מגִּרְסֵיה</span>.—Pl. <span dir=\"rtl\">גִּירְסַיָּיא</span>. <span class=\"citation\">B. Bath. 22ᵃ</span> they may be disturbed. <span dir=\"rtl\">מגִּירְסַייְהוּ</span> in their studies. [In later literature <a href=\"#\" data-headword=\"גִּירְסָא I\">גִּירְסָא</a> <i>version</i>.]</div>","alt":["גִּרְסָא"]},"7650":{"h":"גִּירְסָא II","r":"C00834","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"גִּירְצָא\">גִּירְצָא</a></div>","alt":[]},"7651":{"h":"גִּירְסָנָא","r":"C00835","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (גְּרַס II; b. h.  <span class=\"citation\">Ezek. XLV, 9</span>) <i>acquisition, saving</i>. <span class=\"citation\">Yeb. 117ᵃ</span>. <span class=\"citation\">Ib.</span> <a href=\"#\" data-headword=\"גִּירְסָנָא\">גִּירְסָנִי</a> (Rashi <span dir=\"rtl\">גִּירְסְנָאִי</span>) what is accumulated for me.</div>","alt":["(גּוּרְסִינָא)"]},"7652":{"h":"גֵּירָעוֹן","r":"C00836","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"גֵּירוּעַ I\"><span dir=\"rtl\">גֵּירוּעַ</span> I</a>) <i>deduction</i>. <span class=\"citation\">Arakh. 25ᵇ</span> <span dir=\"rtl\">בת ג׳</span> subject to the law of deduction. <span class=\"citation\">Ib. IX, 7</span> (<span class=\"citation\">33ᵃ</span>) <span dir=\"rtl\">ובג׳ כסף … יוצאים</span> go back to their owners in the year of Jubilee or with a deduction from the purchasing price (<span class=\"citation\">Lev. XXV, 27</span>). <span class=\"citation\">Kidd. I, 2</span> (of the Hebrew slave); a. e.</div>","alt":["גֵּרָ׳"]},"7653":{"h":"גִּירְצָא","r":"C00837","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גרץ</span>, v. <a href=\"#\" data-headword=\"גְּרִיצָה\">גְּרִיצָה</a>) <i>putting layers of dough on each other</i>. <span class=\"citation\">Pes. 37ᵃ</span> נפישא בג׳ Ar. (ed. Koh. <span dir=\"rtl\">בלישא בגירסא</span>, ed. <span dir=\"rtl\">בלִישָׁה</span>) because it grows thick by combination.</div>","alt":[]},"7654":{"h":"גִּירְקְרָרִין","r":"C00838","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּיר II\"><span dir=\"rtl\">גִּיר</span> II</a>, 2).</div>","alt":[]},"7655":{"h":"גִּירְרָא","r":"C00839","html":"<div class=\"sense\"><i>arrow</i>, v. <a href=\"#\" data-headword=\"גִּיר III\"><span dir=\"rtl\">גִּיר</span> III</a>.</div>","alt":[]},"7656":{"h":"גיררתו","r":"C00840","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to IV, 14</span> <span dir=\"rtl\">מבית ג׳ של פרעה</span>, read: <span dir=\"rtl\">גְּדֵירָתוֹ</span> (v. <a href=\"#\" data-headword=\"גְּדֵירָה\">גְּדֵירָה</a>) from Pharaoh’s <i>fortress</i> (where he was in prison).</div>","alt":[]},"7657":{"h":"*גִּישׁ","r":"C00841","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גִּיס II\"><span dir=\"rtl\">גִּיס</span> I</a>) <i>familiar</i>. <span class=\"citation\">Yeb. 117ᵇ</span> דג׳ לה וכ׳ Ar. (ed. <span dir=\"rtl\">דרגיש</span>) annoyance of family quarrels is familiar to her.</div>","alt":[]},"7658":{"h":"גִּישָׁה","r":"C00842","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">נגש</span>) <i>drawing near</i> the altar (<span class=\"citation\">Ex. XXX, 20</span>). <span class=\"citation\">Yoma 32ᵇ</span>. <span class=\"citation\">Zeb. 19ᵇ</span>; a. fr.</div>","alt":[]},"7659":{"h":"גִּישְׁרָא","r":"C00843","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּשְׁרָא\">גִּשְׁרָא</a></div>","alt":[]},"7660":{"h":"גִּישְׁתָּא","r":"C00844","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּשְׁתָּא\">גִּשְׁתָּא</a></div>","alt":[]},"7661":{"h":"גִּישְׁתְּמָא","r":"C00845","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (reduplic. of <a href=\"#\" data-headword=\"גָּשַׁם\">גשם</a>) <i>door-sill, door-stop;</i> v. <a href=\"#\" data-headword=\"גְּשָׁמָה\">גַּשְׁמָה</a>.</div>","alt":[]},"7662":{"h":"גֵּיתָא","r":"C00846","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גאה</span>, cmp. <a href=\"#\" data-headword=\"גֵּו\">גֵּו</a>, <a href=\"#\" data-headword=\"גּוֹי\">גֹּוי</a>) [<i>growth, accrued property,</i>]<i> herd, flock</i> (corresp. to h. <a href=\"#\" data-headword=\"מִקְנֶה\">מִקְנֶה</a>). <span class=\"citation\">Targ. I Chr. XXVIII, 1</span>.—Pl. <span dir=\"rtl\">גֵּיתִין</span>, <a href=\"#\" data-headword=\"גֵּיתֵי\">גֵּיתֵי</a>. <span class=\"citation\">Targ. Am. I, 1</span>. <span class=\"citation\">Targ. Gen. XLVI, 34</span>; a. fr.—<span class=\"citation\">Ned. 38ᵃ</span> (quot. fr. Targ. Am. l. c.).</div>","alt":[]},"7663":{"h":"גֵּיתֵי","r":"C00847","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גֵּיתָא\">preced.</a>, cmp. <a href=\"#\" data-headword=\"גֵּאִים\">גֵּאִים</a>) <i>haughtiness, tyranny</i>. <span class=\"citation\">B. Kam. 114ᵃ</span> <span dir=\"rtl\">דדייני בג׳</span> (Rashi <span dir=\"rtl\">בגֵיוְתָא</span>, Ms. H. <span dir=\"rtl\">בגֵּיוְתָה</span>, Ms. R. <span dir=\"rtl\">בגֵוְתֵי</span>, v. Rabb. D. S. a. l. note 2 for Var. lect.) whom they (the gentile judges) convict tyrannically (not listening to arguments), opp. to Jewish judges who go by argument, points of law &amp;c. [Rashi a. v. <a href=\"#\" data-headword=\"מְגִיזְתָּא I\">מגיזתא</a>, <span class=\"citation\">B. Mets. 30ᵇ</span>, quotes our w. <a href=\"#\" data-headword=\"גִּיזְתַּיָּא\">גִּיזְתַּיָּא</a>; Ms. F. has <span dir=\"rtl\">גִּיזְתֵּי</span>, fr. <span dir=\"rtl\">גזז</span> with, anomalous pl. <i>arbitrary decisions</i>, v. <a href=\"#\" data-headword=\"מְגִיזְתָּא I\">מְגִיזְתָּא</a>.]</div>","alt":[]},"7664":{"h":"הַכָּיָיה","r":"E00507","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַכָּאָה\">הַכָּאָה</a></div>","alt":[]},"7665":{"h":"הָכֵין  I, II","r":"E00508","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הָכֵן\"><span dir=\"rtl\">הָכֵן</span> I</a>, II.</div>","alt":[]},"7666":{"h":"*הֲכִינָה","r":"E00509","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"כֵּן\">כֵּן</a>; cmp. <span dir=\"rtl\">כנה</span> <i>Pi</i>.) <i>by-name</i>. <span class=\"citation\">Taan. 20ᵇ</span> <span dir=\"rtl\">בַּהֲכִינָתוֹ</span> (v. Rabb. D. S. a. l. note 8); <span class=\"citation\">Meg. 28ᵃ</span> <span dir=\"rtl\">בח׳</span> ed. (v. Rabb. D. S. a. l. note 300), v. <a href=\"#\" data-headword=\"חֲנִיכָה\">חֲנִיכָה</a>.</div>","alt":[]},"7667":{"h":"הָכֵינִי","r":"E00510","html":"<div class=\"sense\"> (= <span dir=\"rtl\">הָכֵין הִי</span>) <i>it is thus</i>. <span class=\"citation\">Y. Yoma II, 39ᶜ</span> bot. <a href=\"#\" data-headword=\"ה׳\">ה׳</a> it is thus (R. Ḥ. said).</div>","alt":[]},"7668":{"h":"הָכֵיצַד","r":"E00511","html":"<div class=\"sense\"> = <span dir=\"rtl\">הָא כֵיצַד</span>, v. <a href=\"#\" data-headword=\"כֵּיצַד\">כֵּיצַד</a></div>","alt":[]},"7669":{"h":"הֶכֵּירָא","r":"E00512","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶיכֵּר\">הֶיכֵּ׳</a></div>","alt":[]},"7670":{"h":"הַכֹּל","r":"E00513","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֹּל\">כֹּל</a>. [<span class=\"citation\">B. Kam. 116ᵃ</span> <span dir=\"rtl\">תשפך הכל</span>, v. <a href=\"#\" data-headword=\"חֲבַל I\">חֲבָל</a>.]</div>","alt":[]},"7671":{"h":"הַכְמָנָה","r":"E00514","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּמַן\">כָּמַן</a>) <i>hiding, the appointment of witnesses to lie in wait</i> in order to overhear the seducer to idolatry. <span class=\"citation\">Snh. 67ᵃ</span></div>","alt":[]},"7672":{"h":"הָכֵן","r":"E00515","html":"<div class=\"sense\"> (= <span dir=\"rtl\">הָא כֵן</span>) <i>thus</i>. <span class=\"citation\">Targ. Prov. XXIII, 7</span>. <span class=\"citation\">Targ. Is. LI, 6</span>; a. e.</div>","alt":["הָכֵין I"]},"7673":{"h":"הָכֵן ²","r":"E00516","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (inf. Hif. of <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>, used as a technical term with ref. to <span dir=\"rtl\">הכינו</span>, <span class=\"citation\">Ex. XVI, 5</span>) <i>preparing, designation for use on the Sabbath or Holy Day</i>. <span class=\"citation\">Y. Sabb. III, 6ᵇ</span> there is nothing that exists in the shape in which it is used, <span dir=\"rtl\">ואינו בהָכֵנוֹ</span> which may not be considered as designated for use (on the Sabbath &amp;c.). Y. Bets. 62ᵃ top <span dir=\"rtl\">ספק ה׳</span> where there is a doubt as to whether a thing has been ready for use when the festive day began. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הגוי צריך ה׳</span> that which a gentile offers on a Holy Day requires designation in due time. Ib. I, beg. 60ᵃ <span dir=\"rtl\">בהָכֵינָהּ של אמה</span> because its mother (the hen) was designated for slaughter on the Holy Day; a. fr. [In Babli <a href=\"#\" data-headword=\"הֲכָנָה\">הֲכָנָה</a>.]</div>","alt":["הָכֵין II"]},"7674":{"h":"הֲכָנָה","r":"E00517","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הָכֵן ²\">preced.</a>) </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"הָכֵן ²\">same</a>. <span class=\"citation\">Bets. 2ᵇ</span> <span dir=\"rtl\">משום ה׳</span> on account of the law requiring readiness for use on the preceding day. <span class=\"citation\">Ib. 4ᵃ</span> <span dir=\"rtl\">ה׳ דרבה</span> the law about readiness as interpreted by Rabbah (<span class=\"citation\">ib. 2ᵇ</span>); a. fr.</div><div class=\"sense\"><b>—2)</b>  (ref. to <span dir=\"rtl\">תכין</span> <span class=\"citation\">Deut. XIX, 3</span>) <i>marking out the road</i> to the city of refuge for the involuntary manslayer. <span class=\"citation\">Macc. 10ᵇ</span></div>","alt":[]},"7675":{"h":"הַכְנָסָה","r":"E00518","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>) </div><div class=\"sense\"><b>1)</b> <i>carrying in, putting in</i>. <span class=\"citation\">Sabb. 2ᵇ</span>, v. <a href=\"#\" data-headword=\"הוֹצָאָה\">הוֹצָאָה</a>; Y. ib. I, beg. 2ᵇ. <span class=\"citation\">Y. Hor. I, 46ᵃ</span>; a. fr.—<span class=\"citation\">Yeb. 55ᵇ</span> <span dir=\"rtl\">הַכְנָסַת עטרה</span> insertion of the corona of the membrum virile; <span class=\"citation\">B. Mets. 91ᵃ</span> <a href=\"#\" data-headword=\"ה׳\">ה׳</a> the coupling.—<span class=\"citation\">Y. Yeb. XII, 12ᶜ</span>; <span class=\"citation\">Y. B. Bath. III, 14ᵃ</span> top <span dir=\"rtl\">הַכְנָסַת פירות</span> the bringing home of the crop.—<span class=\"citation\">Num. R. s. 17</span> <span dir=\"rtl\">ה׳ ישראל לארץ</span> the leading of Israel into the promised land.—<span dir=\"rtl\">ה׳ כלה</span> the leading of the bride into the chamber, in gen. <i>wedding ceremonies</i>. <span class=\"citation\">Succ. 49ᵇ</span>.—<span class=\"citation\">Meg. 3ᵇ</span>; <span class=\"citation\">Keth. 17ᵃ</span>; a. e.—ה׳ אורחים <i>hospitality</i>. <span class=\"citation\">Sabb. 127ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>entering, coming home</i>. <span class=\"citation\">Y. Yoma V, 42ᵇ</span> bot. <span dir=\"rtl\">ה׳ יתירה</span> an unnecessary entrance into the Holy of Holies.—<span class=\"citation\">Gen. R. s. 72</span> <a href=\"#\" data-headword=\"ה׳\">ה׳</a> the time required by the laborer for going home from the field, v. <a href=\"#\" data-headword=\"הוֹצָאָה\">הוֹצָאָה</a> 4).</div>","alt":[]},"7676":{"h":"הַכֶּר","r":"E00519","html":"<div class=\"sense\"> (imper. Hif. of <span dir=\"rtl\">נכר</span>) <i>recognize!, the word hakker</i>. <span class=\"citation\">Sot. 10ᵇ</span> <span dir=\"rtl\">בה׳ בישר וכ׳</span> with the word <i>hakker</i> (<span class=\"citation\">Gen. XXXVII, 32</span>) he brought the news to his father, with <i>hakker</i> did they &amp;c. (<span class=\"citation\">Gen. XXXVIII, 25</span>). <span class=\"citation\">Gen. R. s. 85</span> (the account of Tamar follows that of the sale of Joseph) <span dir=\"rtl\">כדי לסמוך ה׳ לה׳</span> in order to let one <i>hakker</i> follow the other <i>hakker</i>.—ה׳ פנים <i>partiality</i>. <span class=\"citation\">Ex. R. s. 30</span> (ref. to <span class=\"citation\">Prov. XXIII, 23</span>).</div>","alt":[]},"7677":{"h":"הכרא","r":"E00520","html":"<div class=\"sense\">, <span class=\"citation\">Pes. 112ᵇ</span>, v. <a href=\"#\" data-headword=\"הַבְרָא\">הַבְרָא</a></div>","alt":[]},"7678":{"h":"הַכָּרָה","r":"E00521","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> נָכַר <i>Hif.</i>) <i>recognition</i>.—<span dir=\"rtl\">הכָּרַת העובר</span> recognition of the embryo, <i>certainty of pregnancy</i>. <span class=\"citation\">Nidd. 8ᵇ</span>; Y. Yeb. IV, 6ᵃ; a. e.—הכרת פנים <i>that by which a face is recognized, means of identification; nose, features</i>. Y. Sot. IX, 23ᶜ bot. from the nose, <span dir=\"rtl\">מקום ה׳ פ׳</span> the place of identification. Y. Yeb. XVI, 15ᶜ; <span class=\"citation\">Gen. R. s. 65</span>, a. e. <span dir=\"rtl\">העביר ה׳ פניהם של ישראל</span> he (Abijah) mutilated the features of Israelites (slain in battle). <span class=\"citation\">Y. Nidd. III, 50ᶜ</span> <span dir=\"rtl\">עד שתצא ה׳ פניו</span> until that portion of the fetus comes to light by which its nature can be ascertained. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הַכָּרוּת פניו</span>; a. fr.</div>","alt":[]},"7679":{"h":"הַכְרָזָה","r":"E00522","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּרַז\">כָּרַז</a>) <i>public announcement</i>. <span class=\"citation\">Snh. 26ᵇ</span> <span dir=\"rtl\">ה׳ בב&quot;ד</span> announcement in court proclaiming a person disqualified as a witness. <span class=\"citation\">Ib. 89ᵃ</span> <span dir=\"rtl\">צריכין ה׳</span> must be published, as to the nature of the crime for which they are to be executed. <span class=\"citation\">Deut. R. s. 11</span> <span dir=\"rtl\">ממונה על הה׳</span> appointed to announce the divine decrees.</div>","alt":[]},"7680":{"h":"הֶכְרֵיעַ","r":"E00523","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶכְרַע\">next w.</a></div>","alt":["הֶכְרֵיעִים"]},"7681":{"h":"הֶכְרַע","r":"E00524","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (כָּרַע <i>Hif.</i>) </div><div class=\"sense\"><b>1)</b> <i>customary additional weight in retailing, boot</i>, v. <a href=\"#\" data-headword=\"גֵּירוּמִים\">גֵּירוּמִים</a>. <span class=\"citation\">B. Bath. 89ᵃ</span>. <span class=\"citation\">Ker. 5ᵃ</span> <span dir=\"rtl\">בה׳ הוא שוקל וכ׳</span> must he weigh (the frank incense) with boot or exactly (v. <a href=\"#\" data-headword=\"עַיִן\">עַיִן</a>)? <span class=\"citation\">Snh. 102ᵃ</span> <span dir=\"rtl\">אחד מכ&quot;ד בה׳ ליטרא</span> one twenty fourth of the overweight of a litra (a minute portion).</div><div class=\"sense\"><b>—2)</b>  (Gramm.) <i>decision as to the junction of a word with the preceding or the following word</i> (v. <a href=\"#\" data-headword=\"הַכְרָעָה\">next w.</a>), <i>construction, syntax</i>. <span class=\"citation\">Yoma 52ᵃ</span> in five verses <span dir=\"rtl\">אין להם ה׳</span> the grammatical construction is undecided; <span class=\"citation\">Gen. R. s. 80</span>; Tanḥ. <span class=\"citation\">B’shall. 26</span>; Mekh. B’shall., Amalek 1; a. e.—Pl. <a href=\"#\" data-headword=\"הֶכְרֵיעַ\">הֶכְרֵיעִים</a>. Y. Meg. IV, 74ᵈ bot. (ref. to <span class=\"citation\">Neh. VIII, 8</span> <span dir=\"rtl\">ויבינו</span>) <span dir=\"rtl\">אלו הה׳</span> that means the grammatical constructions.</div>","alt":[]},"7682":{"h":"הַכְרָעָה","r":"E00525","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הֶכְרַע\">same</a>, </div><div class=\"sense\"><b>1)</b> <i>overweight</i>.—Pl. <span dir=\"rtl\">הַכְרָעוֹת</span>. <span class=\"citation\">Kerith. 5ᵃ</span> <span dir=\"rtl\">הקב&quot;ה יודע</span> (<a href=\"#\" data-headword=\"ב\">ב</a>)<a href=\"#\" data-headword=\"ה׳\">ה׳</a> the Lord takes notice of overweights (liberality) in offerings.</div><div class=\"sense\"><b>—2)</b> <i>grammatical construction.</i> Pl. as above. <span class=\"citation\">Cant. R. to I, 2</span> he might have diverted his mind <span dir=\"rtl\">מחמשה ה׳ וכ׳</span> by referring him to one of the five disputed constructions of Bible verses, v. <a href=\"#\" data-headword=\"הֶכְרַע\">preced.</a>; (<span class=\"citation\">Y. Ab. Zar. II, 41ᶜ</span> bot. <span dir=\"rtl\">השיאות</span>). <span class=\"citation\">Gen. R. s. 36</span>, end (ref. to <span class=\"citation\">Neh. VIII, 8</span>, v. <a href=\"#\" data-headword=\"הֶכְרַע\">preced.</a>) <span dir=\"rtl\">אלו הה׳ והראיות</span> that means the disputed constructions and the arguments for and against; <span class=\"citation\">Yalk. Gen. 61</span>.</div><div class=\"sense\"><b>—3)</b> <i>casting vote, verdict by a majority of one</i>. <span class=\"citation\">Y. Snh. I, 18ᵇ</span> even arbitration in court requires <span dir=\"rtl\">הַכְרָעַת הדעת</span> a majority of one. <span class=\"citation\">Ḥull. 137ᵃ</span> <span dir=\"rtl\">אין הכרעת שלישית מכרעת</span> (sub. <a href=\"#\" data-headword=\"דַּעַת\">דעת</a>) a casting vote consisting of a third divergent opinion is not binding; <span class=\"citation\">B. Kam. 116ᵃ</span>; <span class=\"citation\">Pes. 21ᵃ</span>; <span class=\"citation\">Naz. 53ᵃ</span></div>","alt":[]},"7683":{"h":"הֶכְשֵׁיר","r":"E00526","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּשֵׁר I\">כָּשֵׁר</a>) <i>preparation; fitness</i>, esp. </div><div class=\"sense\"><b>1)</b> <i>direct cause, responsibility</i>. <span class=\"citation\">B. Kam. I, 2</span> חבתי … כה׳ כל נזקו I am bound to pay such compensation as though I had been the entire cause of the damage. Y. ib. 2ᵃ <span dir=\"rtl\">לה׳ נזקין</span> it refers to responsibility for damage, opp. <span dir=\"rtl\">נזקי גופו</span> infliction of bodily injuries; <span class=\"citation\">Y. Gitt. V, beg. 46ᶜ</span></div><div class=\"sense\"><b>—2)</b> <i>finishing</i>. <span class=\"citation\">Gen. R. s. 14</span> <span dir=\"rtl\">הֶכְשֵׁירוֹ באור</span> (an earthen or glass vessel) is finished in fire.</div><div class=\"sense\"><b>—3)</b> <i>that which makes a thing legal, that which is ritually fit</i> (v. <a href=\"#\" data-headword=\"כָּשֵׁר I\">כָּשֵׁר</a>). <span class=\"citation\">Y. Gitt. III, 44ᵈ</span> <span dir=\"rtl\">מפסולו את למד הכשירו</span> from what makes a letter of divorce invalid you can learn what makes it valid. <span class=\"citation\">Y. Pes. V, 32ᵇ</span> top <span dir=\"rtl\">לבור פסולו מתיך הכשירו</span> to distinguish the unfit element of it from the fit element.</div><div class=\"sense\"><b>—4)</b>  (levitical law) <i>fitness to become unclean</i> (which arises from contact with certain liquids), <i>cause of fitness</i> (<span dir=\"rtl\">הוכשר לקבל טומאה</span>, v. <a href=\"#\" data-headword=\"כָּשֵׁר I\">כָּשֵׁר</a>). <span class=\"citation\">Ḥull. 36ᵇ</span> <span dir=\"rtl\">עשאוהו כה׳ מים</span> they declared it (slaughtering, pressing grapes) to be equal in its effect to the fitness for uncleanness which arises from contact with liquids. <span class=\"citation\">Ib. 121ᵃ</span> <span dir=\"rtl\">ה׳ מים ממקום אחר</span> the liquids which produce the fitness to become unclean must come from without. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ה׳ למה לי</span> why should contact with liquids be necessary at all? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">צריך ה׳</span> requires contact with liquids in order to become fit &amp;c. <span class=\"citation\">Y. Kil. VII, end, 31ᵃ</span>; <span class=\"citation\">Sabb. 95ᵇ</span> <span dir=\"rtl\">ה׳ זרעים</span> (v. Rabb. D. S. a. l.) the requirement that the plants (in the pot) must come in contact with liquids in order to be fit for uncleanness; a. fr.</div>","alt":["הֶכְשֵׁר"]},"7684":{"h":"הֶכְשֵׁירָא","r":"E00527","html":"<div class=\"sense\">, <i>proper ritual act</i>. <span class=\"citation\">Ḥull. 19ᵇ</span></div>","alt":[]},"7685":{"h":"הַכְשָׁרָה","r":"E00528","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הֶכְשֵׁירָא\">same</a>, <i>making fit</i> for use. <span class=\"citation\">Taan. 10ᵃ</span> (play on <span dir=\"rtl\">חשר̇ת</span>, <span class=\"citation\">II Sam. XXII, 12</span>, a. <span dir=\"rtl\">חשב̇ת</span>, <span class=\"citation\">Ps. XVIII, 12</span>) [read as Ms. M. 2:] <span dir=\"rtl\">שקול … וקרי ביה הַכְשָׁרַת מים</span> take the <i>Kaf</i> and add it to the <i>Resh</i> and read <i>hakhsharath mayim</i>, sweetening of the waters. [Ed. only <span dir=\"rtl\">הכשר׳</span>, Ms. M. 1 <a href=\"#\" data-headword=\"ח׳\">ח׳</a>, v. Rabb. D. S. a. l. note. As to the interchange for homiletical purposes between <a href=\"#\" data-headword=\"ח\">ח</a> a. <a href=\"#\" data-headword=\"ה\">ה</a>, v. <a href=\"#\" data-headword=\"ה\">ה&quot;א</a>.]</div>","alt":[]},"7686":{"h":"הֶכְשֵׁרוּת","r":"E00529","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"הַכְשָׁרָה\">preced.</a> wds.) <i>fitness; virtue, charity</i>. Mekh. Bo s. 16; <span class=\"citation\">Yalk. Ex. 220</span> (play on <span dir=\"rtl\">בכושרות</span>, <span class=\"citation\">Ps. LXVIII, 7</span>) <span dir=\"rtl\">נהג עמהם בה׳</span> He dealt with them charitably; Tanḥ. Bo 11 <span dir=\"rtl\">בכַשְׁרוּת</span>; <span class=\"citation\">Yalk. Ps. 795</span>.</div>","alt":[]},"7687":{"h":"הַלּ־","r":"E00530","html":"<div class=\"sense\">, definite art., v. <a href=\"#\" data-headword=\"הַלָּז\">הַלָּז</a>, <a href=\"#\" data-headword=\"הַלֵּזוּ\"><a href=\"#\" data-headword=\"הַלֵּזוּ\">הַלֵּזוּ</a>.</a></div>","alt":[]},"7688":{"h":"הל","r":"E00531","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. I, 4ᵃ</span> <span dir=\"rtl\">אתקין להל</span>, a corrupt.; read: <span dir=\"rtl\">מותרין לקבל</span>, v. <span class=\"citation\">Bets. 24ᵇ</span>; Y. ib. III, 62ᵃ top.—Y. R. Hash. II, 58ᵇ top, v. <a href=\"#\" data-headword=\"הָלָא\">next w.</a></div>","alt":[]},"7689":{"h":"הָלָא","r":"E00532","html":"<div class=\"sense\"><i>further on</i>, with prefix <a href=\"#\" data-headword=\"ל\">ל</a>. <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">מן הכא ולה׳ נחל וכ׳</span> (ed. Wil. <span dir=\"rtl\">מן הכא נחל</span>) from now and onward we shall begin a new account. <span class=\"citation\">Y. R. Hash. II, 58ᵇ</span> top <span dir=\"rtl\">מן ההוא תרעא דלהל</span> (read <span dir=\"rtl\">ולהלא</span>) from this court session and for all future ones.</div>","alt":[]},"7690":{"h":"הֲלָא","r":"E00533","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲלִי\">הֲלִי</a></div>","alt":[]},"7691":{"h":"הֶלְבּוֹן","r":"E00534","html":"<div class=\"sense\">, dial. for <a href=\"#\" data-headword=\"חֶלְבּוֹן\">חֶלְבּוֹן</a>.</div>","alt":[]},"7692":{"h":"הלבשוש","r":"E00535","html":"<div class=\"sense\">, v. <span dir=\"rtl\">הַלְכְּ׳</span></div>","alt":["הלבשיש"]},"7693":{"h":"הָלָה","r":"E00536","html":"<div class=\"sense\"> (tradit. pronunc. <a href=\"#\" data-headword=\"הָלָה\">הֲלָה</a>) m. (cmp. <a href=\"#\" data-headword=\"הָלָא\">הָלָא</a>) <i>that one there, this one;</i> (mostly in legal proceedings) <i>the person concerned</i>. <span class=\"citation\">B. Mets. III, 2</span>. <span class=\"citation\">Shebu. VI, 6</span>, sq. <span dir=\"rtl\">וה׳ אומר וכ׳</span> and the defendant says &amp;c. <span class=\"citation\">B. Mets. 113ᵇ</span>; a. v. fr. [<span class=\"citation\">Eduy. IV, 9</span> <span dir=\"rtl\">ה׳ תצא</span> fem., v. <a href=\"#\" data-headword=\"הַלָּז\">הַלָּז</a>.]—Pl. <span dir=\"rtl\">הֲלָלוּ</span>. <span class=\"citation\">Erub. 54ᵃ</span> <span dir=\"rtl\">ה׳ נוצצין וה׳ וכ׳</span> these blossom and those fade. <span class=\"citation\">Hor. 14ᵃ</span> <span dir=\"rtl\">מי הם ה׳ שמימיהם וכ׳</span> who are those whose waters we drink &amp;c.?—<span class=\"citation\">Bets. 15ᵇ</span> <span dir=\"rtl\">ה׳ בעלי וכ׳</span> these here (now leaving the assembly) are &amp;c.; a. fr.</div>","alt":[]},"7694":{"h":"הַלְהוּלְתָּא","r":"E00537","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּלְחוּלְתָּא\">חוּלְחוּלְתָּא</a></div>","alt":[]},"7695":{"h":"הַלְוָאָה","r":"E00538","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">לוה</span>) <i>loan</i>. <span class=\"citation\">B. Mets. 81ᵇ</span> <span dir=\"rtl\">בשעת הַלְוָאָתוֹ</span> at the time the loan was transacted. <span class=\"citation\">Ib. 14ᵃ</span>, a. fr. <span dir=\"rtl\">שטר ה׳</span> note of indebtedness, promissory note; a. fr.</div>","alt":[]},"7696":{"h":"הַלְוַאי","r":"E00539","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַלְוַאי\">אַלְוַאי</a></div>","alt":["הַלְוַואי","הַלְוַוי"]},"7697":{"h":"הַלְוָיָה","r":"E00540","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">לוה</span>) <i>escort on parting, attendance to a departing friend’s needs; following a funeral procession</i>. <span class=\"citation\">Sot. 46ᵇ</span>, v. <a href=\"#\" data-headword=\"לְוָיָה\">לְוָיָה</a>.—Y. ib. IX, 23ᵈ bot.</div>","alt":["הַלְוָיָיה"]},"7698":{"h":"הִלּוּךְ","r":"E00541","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִלֵּל\">הִילּ׳</a></div>","alt":["הִלּוּל","הִלּוּלָא"]},"7699":{"h":"הָלוּם","r":"E00542","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָלוּם\">אָלוּם</a></div>","alt":[]},"7700":{"h":"הֲלוֹם","r":"E00543","html":"<div class=\"sense\"><i>here, hither; thus far</i>. <span class=\"citation\">Zeb. 102ᵃ</span> (play on <a href=\"#\" data-headword=\"הָלַם\">הָלַם</a>, q. v.) <span dir=\"rtl\">אין ה׳ אלא מלכות</span> <i>hălom</i> alludes to royalty, as we read (<span class=\"citation\">II Sam. VII, 18</span>) &amp;c. <span dir=\"rtl\">עד ה׳</span> thus far (to be king). Ib. <span dir=\"rtl\">וכל היכא דכתיב ה׳ וכ׳</span> does <i>hălom</i> in the Bible always intimate royalty for all time to come?</div>","alt":[]},"7701":{"h":"הַלָּז","r":"E00544","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"הַלּ־\">הַלּ־</a> a. <i>this here, that there</i>. <span class=\"citation\">Snh. 11ᵇ</span> <span dir=\"rtl\">סופר ה׳</span> ed. (missing in Ms. M.; <span class=\"citation\">Tosef. ib. II, 6</span> <a href=\"#\" data-headword=\"הָלָה\">הלה</a>, Var. <span dir=\"rtl\">הלך</span>); Y. ib. I, 18ᵈ top; <span class=\"citation\">Y. Maas. Sh. V, 56ᶜ</span> top <span dir=\"rtl\">הסופר ה׳</span> the, then, scribe; v. <span dir=\"rtl\">נָזוּף</span>.—<span class=\"citation\">Keth. 36ᵇ</span>. <span class=\"citation\">Y. Erub. I, 18ᶜ</span> bot. <span dir=\"rtl\">פירצה של ה׳</span> the breach on the other side.—<i>Fem</i>. <a href=\"#\" data-headword=\"הַלֵּזוּ\">הַלֵּזוּ</a>. <span class=\"citation\">Yeb. XIII, 7</span> (<span class=\"citation\">109ᵃ</span>) <span dir=\"rtl\">ה׳ תצא</span> (missing in Mish. ed.) the other sister is free. Ib. <span dir=\"rtl\">ותצא ה׳</span>. Ib. 51ᵇ; (<span class=\"citation\">Eduy. IV, 9</span> <a href=\"#\" data-headword=\"הָלָה\">הלה</a>).</div>","alt":[]},"7702":{"h":"הֲלָזָה","r":"E00545","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (לוּז III) <i>talk, sneer</i>. <span class=\"citation\">Tosef. Keth. II, 3</span> <span dir=\"rtl\">נפלה ה׳ וכ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">חלזה</span>, <a href=\"#\" data-headword=\"חִלָּזוֹן\">חלזון</a>, corr. acc.) talk (against the court’s action) spread in town, opp. <a href=\"#\" data-headword=\"עַרְעֵר I\">ערער</a> legal protest.</div>","alt":[]},"7703":{"h":"הַלֵּזוּ","r":"E00546","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַלָּז\">הַלָּז</a></div>","alt":[]},"7704":{"h":"גַּל","r":"C00848","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>heap of stones, bones</i> &amp;c., esp. <i>rubbish, ruins</i>. <span class=\"citation\">Sot. IX, 2</span> if the body of a murdered person was found <span dir=\"rtl\">טמון בג׳</span> buried in a heap. <span class=\"citation\">Keth. 15ᵇ</span> <span dir=\"rtl\">לפקח עליו את הג׳</span> as to removing debris for saving one’s life (on the Sabbath). <span class=\"citation\">Sabb. 34ᵃ</span> <span dir=\"rtl\">עשהו ג׳ של עצמות</span> changed him into a heap of bones; a. fr.—Pl. <a href=\"#\" data-headword=\"גְּלִים\">גַּלִּים</a>, <a href=\"#\" data-headword=\"*גַּלִּי\">גַּלִּין</a>. <span class=\"citation\">Nidd. IX, 5</span>. <span class=\"citation\">Kil. I, 2</span>, v. <a href=\"#\" data-headword=\"חֲזֶרֶת\">חֲזֶרֶת</a>. Cmp. <a href=\"#\" data-headword=\"גִּילָא II\">גִּילָּא</a>.</div><div class=\"sense\"><b>—2)</b> <i>wave, billow.</i> <span class=\"citation\">Mikv. V, 6</span> <span dir=\"rtl\">ג׳ שנתלש</span> a wave thrown on shore. <span class=\"citation\">Yeb. 121ᵃ</span>; a. fr.—Pl. as above. <span class=\"citation\">Ex. R. s. 19</span> <span dir=\"rtl\">הגיעוה ג׳</span> waves overcame her, i.e. she encountered storms; a. e.</div><div class=\"sense\"><b>—3)</b> <i>revolving door, turning on hinges or pivots</i>. <span class=\"citation\">Sabb. 81ᵃ</span> <span dir=\"rtl\">של ג׳</span> the pivot of a revolving door. V. <a href=\"#\" data-headword=\"גִּלָּה\">גִּלָּה</a>.</div><div class=\"sense\"><b>—4)</b> (v. LXX <span class=\"citation\">Hos. XII, 12</span>) <i>turtoise.</i> <i> Pl.</i> as above. Sifra Sh’mini, ch. IV, Par. 3.</div>","alt":[]},"7705":{"h":"גַּלָּא","r":"C00849","html":"<div class=\"sense\"><b>1)</b> <i>heap.</i> Pl. <a href=\"#\" data-headword=\"*גַּלִּי\">גַּלִּין</a>. <span class=\"citation\">Targ. Is. XXV, 2</span>.</div><div class=\"sense\"><b>—2)</b>  also <a href=\"#\" data-headword=\"גְּלָל\">גְּלָלָא</a> <i>wave</i>. <span class=\"citation\">Koh. R. to XI, 1</span>.—Pl. <a href=\"#\" data-headword=\"*גַּלִּי\">גַּלִּין</a>, <a href=\"#\" data-headword=\"גַּלַּיָּא\">גַּלַּיָּא</a>, <a href=\"#\" data-headword=\"גְּלֵי\">גַּלֵּי</a>, <a href=\"#\" data-headword=\"גְּלִילָא\">גְּלָלַיָּא</a>, <span dir=\"rtl\">גַּלְלַ׳</span>. <span class=\"citation\">Targ. Zech. X, 11</span>. <span class=\"citation\">Targ. Ps. XLII, 8</span> (some ed. <a href=\"#\" data-headword=\"גְּלִילָא\">גְּלִילַ׳</a>); a. e. <span class=\"citation\">Targ. Y. I Ex. XV, 18</span> [read:] <span dir=\"rtl\">בֵּנֵי גְּלָלַיָּיא</span> between the waves.—<span class=\"citation\">Yeb. 121ᵃ</span> <span dir=\"rtl\">גלי אשפלו</span> the waves may have cast him out (alive).</div><div class=\"sense\"><b>—3)</b> <i>revolving door</i>. <span class=\"citation\">B. Kam. 112ᵃ</span>. <span class=\"citation\">Snh. 113ᵃ</span> bot. <span dir=\"rtl\">דטרקיה לגַלֵּיה וכ׳</span> who locked his door and lost the key.—Pl. <a href=\"#\" data-headword=\"גְּלֵי\">גַּלֵּי</a>. <span class=\"citation\">Ber. 28ᵃ</span> <span dir=\"rtl\">טרוקו ג׳</span> close ye the (college doors); <span class=\"citation\">Ab. Zar. 58ᵃ</span>. <span class=\"citation\">B. Mets. 108ᵃ</span>, v. <a href=\"#\" data-headword=\"אִגְלָא\">אִגְלָא</a>.</div><div class=\"sense\"><b>—4)</b>  pl. <a href=\"#\" data-headword=\"גַּלַּיָּא\">גַּלַּיָּא</a>, <a href=\"#\" data-headword=\"גְּלֵי\">גַּלֵּי</a> <i>excrements, ordure</i>. <span class=\"citation\">Targ. Ezek. IV, 12</span>; <span class=\"citation\">15</span> (incorr. <a href=\"#\" data-headword=\"גְּלֵי\">גְּלֵי</a>).</div><div class=\"sense\"><b>—5)</b>  (v. <a href=\"#\" data-headword=\"גִּלּוּל\">גִּלּוּל</a>) <i>Gallaya</i>, cacophemism for similarly sounding idolatrous names. <span class=\"citation\">Y. Ab. Zar. III, 43ᵃ</span> bot.; <span class=\"citation\">Tosef. ib. VI</span> (<span class=\"citation\">VII), 4</span>, v. <a href=\"#\" data-headword=\"גָּד ³\">גַּדָּא</a> (<span class=\"citation\">Ab. Zar. 46ᵃ</span>; <span class=\"citation\">Tem. 28ᵇ</span>; v. <a href=\"#\" data-headword=\"*גַּלְיָא II\"><span dir=\"rtl\">גַּלְיָא</span> II</a>). <span class=\"citation\">Meg. 6ᵃ</span> <span dir=\"rtl\">בית גליא שלהן</span> their house of idolatry. [<span dir=\"rtl\">גלין</span>, <span class=\"citation\">Sabb. 138ᵃ</span>, v. <a href=\"#\" data-headword=\"גִּלָּה\">גִּלָּה</a>.] [<span class=\"citation\">Targ. II Kings XXIII, 6</span>; <span class=\"citation\">Jer. XXVI, 23</span>, v. <a href=\"#\" data-headword=\"גְּלֵי\">גְּלֵי</a>.]</div>","alt":[]},"7706":{"h":"גְּלָא","r":"C00850","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלֵי\">גְּלֵי</a></div>","alt":[]},"7707":{"h":"גלא","r":"C00851","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּלְאַקְסִינוֹן\">גַּלְאַקְסִינוֹן</a></div>","alt":["ג׳ קסינון"]},"7708":{"h":"גְּלָאי","r":"C00852","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלַי\">גְּלַי</a></div>","alt":[]},"7709":{"h":"גְּלָאלָא","r":"C00853","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Zech. 578</span>, v. <a href=\"#\" data-headword=\"גְּלָל\">גְּלָלָא</a></div>","alt":[]},"7710":{"h":"גַּלְאַקְסִינוֹן","r":"C00854","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(ed. <span dir=\"rtl\">גלא ק׳</span>) (γαλῆ Ἀξεινῶν) [<i>fur of</i>] <i>the weasel imported by the Axeinoi</i> (living around the Pontus Axenus or Euxenus); <i>ermine</i> (v. Sm. Ant. s. v. Pellis). <span class=\"citation\">Gen. R. s. 20</span>, end <span dir=\"rtl\">(<a href=\"#\" data-headword=\"גלא\">גלא</a>) <span dir=\"rtl\">גלי ק׳</span></span>. Y. Sabb. II, 4ᵈ bot. (rendition of <a href=\"#\" data-headword=\"תַּחַשׁ\">תַּחַשׁ</a>) <a href=\"#\" data-headword=\"גלקטינון\">גלקטינון</a>; <span class=\"citation\">Koh. R. to I, 9</span> <a href=\"#\" data-headword=\"גלטינון\">גלטינון</a> (corr. acc.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">והכלב גלבטינון</span> (read <span dir=\"rtl\">גלכסינון</span>) and the dog shall wear ermine fur.</div>","alt":[]},"7711":{"h":"גְּלַב","r":"C00855","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">גלח</span>, <span dir=\"rtl\">גלש</span>) <i>to scrape, shave</i>. <span class=\"citation\">Targ. Y. Lev. XIX, 27</span>.—V. <a href=\"#\" data-headword=\"*גְּלִיבָא\">גְּלִיבָא</a>.</div>","alt":[]},"7712":{"h":"גְּלָב","r":"C00856","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּלַב\">preced.</a>) <i>razor, knife</i>. <span class=\"citation\">Targ. Y. Num. VI, 5</span>; <span class=\"citation\">VIII, 7</span> <a href=\"#\" data-headword=\"גְּלַב\">(גְּלַב</a>).—Pl. <a href=\"#\" data-headword=\"*גַּלְבִּין\">גְּלָבִין</a>. <span class=\"citation\">Gen. R. s. 31</span> (transl. <span dir=\"rtl\">חרבת צרים</span> <span class=\"citation\">Josh. V, 2</span>) <span dir=\"rtl\">ג׳ דטינרי</span> flint knives.—[<span class=\"citation\">Targ. Ezek. XXVII, 24</span>, v. <a href=\"#\" data-headword=\"גְּלַף I\">גְּלַף</a>.]</div>","alt":[]},"7713":{"h":"גַּלָּב","r":"C00857","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"גְּלָב\">preced.</a>) <i>barber</i>.—Pl. <span dir=\"rtl\">גַּלָּבַיָּא</span>. <span class=\"citation\">Targ. Ezek. V, 1</span>.</div>","alt":["גַּלָּבָא"]},"7714":{"h":"גלבטא","r":"C00858","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַנְטְבִילָא\">אַנְטְבִילָא</a></div>","alt":[]},"7715":{"h":"*גַּלְבִּין","r":"C00859","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">גלב</span>) = <span dir=\"rtl\">קַלְפִין</span>, <i>scales</i>. <span class=\"citation\">Targ. I Sam. XVII, 5</span> <span dir=\"rtl\">שריין ג׳</span> (Var. <a href=\"#\" data-headword=\"גלכין\">גלכין</a>; h. text <span dir=\"rtl\">קשקשים</span>). V., however, <a href=\"#\" data-headword=\"גִּלְדָּא\">גִּלְדָּא</a>.</div>","alt":[]},"7716":{"h":"*גְּלַבְקְיָא","r":"C00860","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (γλαύκιον, glaucion) <i>juice of glaucion</i>, a plant like the horned poppy. Sifra Vayikra, Ḥoba, Par. 12, ch. XXII המערב … ג׳ בשמן Ar. (ed. <a href=\"#\" data-headword=\"גלוביא\">גלוביא</a>, Var. <a href=\"#\" data-headword=\"בלבקיא\">בלבקיא</a> &amp;c., v. ed. Weiss p. 28ᵃ note) he who adulterates oil with the juice of glaucium (selling it for poppy-oil); <span class=\"citation\">Koh. R. to IX, 13</span> <a href=\"#\" data-headword=\"בלבקיא\">בלבקי</a>; <span class=\"citation\">ib. to VI, 1</span> <a href=\"#\" data-headword=\"בלקיא\">בלקיא</a>; <span class=\"citation\">Tosef. B. Bath. V, 6</span> <span dir=\"rtl\">מי כגלקיא</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"בלקיא\">בלקיא</a>); <span class=\"citation\">Yalk. Lev. 479</span> <span dir=\"rtl\">בלנקי</span> (corruptions of <span dir=\"rtl\">כְּלַוְקְיָא</span> or <span dir=\"rtl\">כְּלַבְקְיָא</span>; cmp. Löw Pfl. p. 205 a. 257). [Ar. a. Mus. seem to think of <i>Lycium</i>.]</div>","alt":[]},"7717":{"h":"גְּלַג","r":"C00861","html":"<div class=\"sense\">, <i>Pa.</i> <span dir=\"rtl\">גַּלֵּיג</span> (reduplic. of <a href=\"#\" data-headword=\"גַּל\">גל</a>, v. <span dir=\"rtl\">גלה</span>) <i>to reveal</i> (v. P. Sm. 723), <i>to announce</i>. <span class=\"citation\">Gen. R. s. 36</span> זיל גַּלֵּיג וכ׳ Ar. (ed. <span dir=\"rtl\">זיל גְּלוֹג</span>, not <a href=\"#\" data-headword=\"זִילָא\">זילא</a>) go, tell thy mother the good news; <span class=\"citation\">Lev. R. s. 5</span>.—<span class=\"citation\">Lev. R. s. 25</span>; <span class=\"citation\">Koh. R. to II, 20</span> <span dir=\"rtl\">איזילי גליג לאימיך</span> (not <span dir=\"rtl\">גליגי</span>) I will go and tell thy mother. Pesik. Aniya, p. 137ᵃ [read:] <span dir=\"rtl\">כל מה דאת יכיל למיגלג גלג למישבח שבח</span> as much as thou canst tell, tell; as much as thou canst praise, praise; <span class=\"citation\">Yalk. Is. 339</span> (corr. acc.); (<span class=\"citation\">Pesik. R. s. 32</span> <span dir=\"rtl\">דרוש וכ׳</span>).</div><div class=\"sense\"><b>Ithpe. אִיגַּלִּיג</b> <div class=\"sense\"><i>to boast</i>. <span class=\"citation\">Lev. R. s. 10</span> is it these <span dir=\"rtl\">דאת מִגַּלֵּיג עליהון</span> of whom thou art so boastful?</div></div>","alt":[]},"7718":{"h":"גַּלְגָּא","r":"C00862","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּלַג\">preced.</a>) <i>revelation, preaching</i>. <span class=\"citation\">Y. Sot. I, 17ᵇ</span>; <span class=\"citation\">Lev. R. s. 26</span> [read:] <span dir=\"rtl\">מאי את בעי מן גַּלְגּוֹי דהדין</span> do not mind this man’s boastful talk.</div>","alt":["גַּלְגִּין"]},"7719":{"h":"גלגוטיקא","r":"C00863","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\">גלוגדקא</a></div>","alt":[]},"7720":{"h":"גִּלְגּוּל","r":"C00864","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גלגל</span>) </div><div class=\"sense\"><b>1)</b> <i>rolling, turning</i>. <span class=\"citation\">Y. Sot. I, 16ᶜ</span> bot. <span dir=\"rtl\">כדי ג׳ ביצה</span> as much time as is required for roasting an egg in the ashes; <span class=\"citation\">Num. R. s. 9</span>.—<span class=\"citation\">Y. Pes. III, 30ᵃ</span> <span dir=\"rtl\">לאחר גִּילְגּוּלָהּ</span> after the dough has been rolled (formed).—<span class=\"citation\">Keth. 111ᵃ</span> <span dir=\"rtl\">ע&quot;י ג׳</span> by rolling under the ground (for resurrection in the Holy Land).</div><div class=\"sense\"><b>—2)</b>  (with or without <a href=\"#\" data-headword=\"שְׁבוּעָה\">שבועה</a>) <i>the rule permitting the court to insert in an oath an affirmation to which the person concerned could not have been compelled directly; an oath by implication</i>. <span class=\"citation\">Kidd. 27ᵇ</span>. Y. ib. I, 60ᵈ. <span class=\"citation\">Yeb. 58ᵇ</span>; Kidd. l. c. <span dir=\"rtl\">ע&quot;י ג׳</span> by implication (the woman including in her oath the time of her betrothal); a. fr.—4) (cmp. <a href=\"#\" data-headword=\"גַּל\">גַּל</a>) <span dir=\"rtl\">בית ג׳</span> <i>a field full of hills and depressions</i>. <span class=\"citation\">Toh. VI, 6</span>; <span class=\"citation\">Erub. 22ᵇ</span> (Var. in Ar. <a href=\"#\" data-headword=\"גדגד\">גדגד</a>, ref. to <a href=\"#\" data-headword=\"גִּידּוּד\">גִּידּוּד</a>). [<span class=\"citation\">Tosef. B. Bath. II, 16</span> <span dir=\"rtl\">בית גילגל</span>, v. <a href=\"#\" data-headword=\"גַּלְגַּל\">גַּלְגַּל</a>.]</div>","alt":["גִּילְ׳"]},"7721":{"h":"גִּלְגּוּל ²","r":"C00865","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"גַּלְגַּל ²\">גַּלְגַּלָּא</a></div>","alt":["גִּילְ׳"]},"7722":{"h":"גַּלְגֵּיל","r":"C00866","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּלְגֵּל\">גַּלְגֵּל</a></div>","alt":[]},"7723":{"h":"גַּלְגִּילָא","r":"C00867","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּרְגִּירָא\">גַּרְגִּירָא</a></div>","alt":[]},"7724":{"h":"גלגילון","r":"C00868","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּלְגְּלִין\">גִלְגְּלִין</a></div>","alt":[]},"7725":{"h":"גִּלְגֵּל","r":"C00869","html":"<div class=\"sense\"><b>1)</b> <i>to roll, turn</i>. Pirké́ d’R. El. ch. XXXVI <span dir=\"rtl\">לגַלְגֵּל וכ׳</span> to roll (move) the stone.—<span class=\"citation\">Y. Sabb. III, 6ᵃ</span> top <span dir=\"rtl\">מְגַלְגְּלִין ביצה וכ׳</span> you may roll an egg (for roasting) on &amp;c. <span class=\"citation\">Ḥall. III, 1</span> <a href=\"#\" data-headword=\"גַּלְגַּל ²\">גִּלְגְּלָה</a> (<span dir=\"rtl\">בחטים</span>) when she has formed the dough (of wheat) by rolling; a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">מְגוּלְגָּל</span>, f. <span dir=\"rtl\">מְגוּלְגֶּלֶת</span>; pl. <span dir=\"rtl\">מְגוּלְגָּלִים</span>, <span dir=\"rtl\">מְגוּלְגָּלִין</span>; <span dir=\"rtl\">מְגוּלְגָּלוֹת</span>. 1) <i>rolled</i>. <span class=\"citation\">Pes. 7ᵃ</span> <span dir=\"rtl\">עיסה מג׳</span> a formed dough. <span class=\"citation\">Y. Sot. I, 16ᶜ</span> bot. <span dir=\"rtl\">ביצים מג׳</span> roasted eggs; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>rounded</i>. <span class=\"citation\">B. Bath. 16ᵇ</span> <span dir=\"rtl\">מה עדשה זו מְגוּלְגֶּלֶת אף אבילות מִגַּלְגֶּלֶת וכ׳</span> as the lentil is rounded, so does mourning roll and go around (different version in Ms., v. Rabb. D. S. a. l. note, a. in <span class=\"citation\">Yalk. Gen. 110</span>, v. <a href=\"#\" data-headword=\"גַּלְגַּל\">גַּלְגַּל</a>). [<span class=\"citation\">Men. 86ᵃ</span>, v. <a href=\"#\" data-headword=\"גִּרְגֵּר\">גִּרְגֵּר</a>.].—2) (with <span dir=\"rtl\">על</span>) <i>to roll upon, to put on one’s shoulders, to burden, tax, assess</i>. <span class=\"citation\">Keth. VIII, 1</span> (<span class=\"citation\">78ᵃ</span>) <span dir=\"rtl\">אתם מגלגלים עלינו וכ׳</span> you burden us with old restrictive laws. Y. Shebi. IV, 35ᵇ <span dir=\"rtl\">אתם מג׳ וכ׳</span> ye impose upon us taxes &amp;c. <span class=\"citation\">Y. B. Bath. I, beg. 12ᵈ</span> <span dir=\"rtl\">מג׳ עליו וכ׳</span></div><div class=\"sense\"><b>—3)</b> <i>to bring about, cause</i>. <span class=\"citation\">Sabb. 32ᵃ</span>; Tosef. Yoma V (IV), 12 <span dir=\"rtl\">מגלגלין זכות ע&quot;י וכ׳</span> good things are brought about through the agency of good men &amp;c.; a. fr.</div><div class=\"sense\"><b>—4)</b>  (v. <a href=\"#\" data-headword=\"גָּלַל\">גָּלַל</a> Nif.) <i>to overcome</i> (one’s own feelings), <i>to put up with, bear with</i>. <span class=\"citation\">Keth. 67ᵇ</span> <span dir=\"rtl\">רצונך שתְּגַלְגֵּל עמי בעדשים</span> will you bear with me when I offer you only lentils? <span dir=\"rtl\">ג׳ עמו וכ׳</span> he tried to live with him on lentils, and died. <span class=\"citation\">Ib. 111ᵃ</span> <span dir=\"rtl\">ג׳ בעצמו</span> he conquered his love and remained single. Y. ib. VII, beg. 31ᵇ <span dir=\"rtl\">מגלגלת עמו וכ׳</span> she has to bear with him thirty days longer. <span class=\"citation\">Y. Yeb. VIII, 8ᵈ</span> top <span dir=\"rtl\">גַּלְגֵּל עמהן וכ׳</span> bear with them twelve months (give them time for reconsideration).</div><div class=\"sense\"><b>Hithpalp. הִתְגַּלְגֵּל  הִגַּ׳</b> <div class=\"sense\">, <i>Nithpalp</i>. <span dir=\"rtl\">נִתְגַּלְגֵּל</span> </div><div class=\"sense\"><b>1)</b> <i>to be rolled</i>. <span class=\"citation\">Erub. X, 3</span> <span dir=\"rtl\">נ׳ הספר מידו</span> the scroll rolled out of his hands (down the roof). <span class=\"citation\">Ḥall. III, 1</span> <span dir=\"rtl\">עד שתִּתְגַּלְגֵּל בחטים</span> in the case of wheat flour, until it (the dough) is rolled, v. supra. Y. Kil. IX, 32ᶜ top; Y. Keth. XII, 35ᵇ top <span dir=\"rtl\">מִתְגַּלְגְּלִין</span> their bodies are rolled underground, v. <a href=\"#\" data-headword=\"גִּלְגּוּל\">גִּלְגּוּל</a>. <span class=\"citation\">B. Kam. 17ᵇ</span> <span dir=\"rtl\">ונתג׳ למקום אחר</span> but the barrel rolled to another place. <span class=\"citation\">Pesik. R. s. 6</span> <span dir=\"rtl\">מא&quot;י נִתְגַּלְגְלָה וכ׳</span> from Palestine it (the stone) rolled and arrived just for this momentary use; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be turned, changed, transferred, caused</i>. <span class=\"citation\">Pirké d’R. El. ch. XLIX</span> <span dir=\"rtl\">נתגלגלה המלכות על וכ׳</span> the royal dignity was transferred on Esther. <span class=\"citation\">Shebu. VII, 8</span> <span dir=\"rtl\">נ׳ לו שבועה וכ׳</span> if by chance an oath is imposed upon him in another law-suit (with the same persons), the court makes him swear by implication &amp;c.; v. <a href=\"#\" data-headword=\"גִּלְגּוּל\">גִּלְגּוּל</a>.</div><div class=\"sense\"><b>—3)</b>  (of waters) <i>to tower, gather</i>. <span class=\"citation\">Pirké d’R. El. ch. V</span>; ch. XXIII.</div><div class=\"sense\"><b>—4)</b>  (with <a href=\"#\" data-headword=\"רַחֲמִים\">רחמים</a>) <i>to prevail</i> (over hatred &amp;c.), <i>be moved</i>. <span class=\"citation\">Pesik. R. s. 20</span> <span dir=\"rtl\">נִתְגַּלְגְּלוּ רחמיו וכ׳</span> the Lord’s compassion was moved. Tanḥ. Vayigg. 4; a. e.</div><div class=\"sense\"><b>—5)</b> <i>to throw one’s self upon, to attack</i>. <span class=\"citation\">Yalk. Is. 350</span> (<span class=\"citation\">ib. 288</span> <span dir=\"rtl\">נתגאה</span>).</div></div>","alt":[]},"7726":{"h":"גַּלְגֵּל","r":"C00870","html":"<div class=\"sense\">, <i>to roll</i>. <span class=\"citation\">Targ. Y. I Gen. XXVIII, 10</span> (<span class=\"citation\">II</span> <span dir=\"rtl\">גלל</span>). Ib. XXIX, 8 (O. <a href=\"#\" data-headword=\"גַּנְדַּר I\">גנדר</a>); a. e.—Y. Shebu. VI, 37ᵃ wait <span dir=\"rtl\">עד דִּיגַלְגֵּל עלן וכ׳</span> until he heaps upon thee all his claims, and then swear concerning all of them. Ib. VII, end, 38ᵃ <span dir=\"rtl\">או אישתבע ליה כל דמְגַלְגֵּל עלך</span> or thou must swear to him concerning all that he asks thee to swear to by implication.—<i>Part. pass</i>. <span class=\"citation\">Ber. 44ᵇ</span> <span dir=\"rtl\">ביעתא מְגוּלְגַּלְתָּא</span> an egg roasted in ashes, v. <a href=\"#\" data-headword=\"גִּלְגֵּל\">preced.</a></div><div class=\"sense\"><b>Ithpalp. אִיתְגַּלְגַּל  אִיגַּלְגַּל</b> <div class=\"sense\">; <a href=\"#\" data-headword=\"גְּלַל\">אִתְגְּלַל</a> (fr. <a href=\"#\" data-headword=\"גְּלַל\">גְּלַל</a>), <a href=\"#\" data-headword=\"גּוּל\">אִתְגּוֹלַל</a> (Ithpolel of <a href=\"#\" data-headword=\"גּוּל\">גּוּל</a>) </div><div class=\"sense\"><b>1)</b>  as <a href=\"#\" data-headword=\"גִּלְגֵּל\">preced.</a> Hithpalp. 3. <span class=\"citation\">Targ. Job XXX, 14</span>.—2) (with <a href=\"#\" data-headword=\"רַחֲמִין\">רחמין</a>) as <a href=\"#\" data-headword=\"גִּלְגֵּל\">preced.</a> Hithpalp. 4. <span class=\"citation\">Targ. I Kings III, 26</span> <span dir=\"rtl\">איתגלגלו</span> ed. Lag. (ed. <span dir=\"rtl\">אִיתְגְּלָלוּ</span>). <span class=\"citation\">Targ. O. Gen. XLIII, 30</span> <span dir=\"rtl\">אִתְגּוֹלָלוּ</span>). <span class=\"citation\">Targ. Hos. XI, 8</span> <span dir=\"rtl\">מתגללא</span> ed. Lag. ed. <span dir=\"rtl\">אִתְגּוֹלָלוּ</span>). <span class=\"citation\">Targ. Jer. XXXI, 20</span> <span dir=\"rtl\">אִתְגּוֹ׳</span>. <span class=\"citation\">Targ. II Chr. XXXIII, 13</span>. <span class=\"citation\">Targ. Y. Num. XXVI, 1</span>; a. e.—3) <i>to come about, to happen</i>. <span class=\"citation\">B. Mets. 40ᵃ</span>, a. e. <span dir=\"rtl\">איגלגל מילתא</span> it so happened in the course of time.—4) (denom. of <a href=\"#\" data-headword=\"גּוּלְגַּלְתָּא\">גולגלתא</a>) <i>to crown, adorn one’s self</i>. <span class=\"citation\">Esth. R. to I, 4</span> whether with its own or with strange (feathers) <span dir=\"rtl\">מִתְגַּלְגְּלַת בת קבריא</span> the raven will adorn itself; <span class=\"citation\">ib. 9</span>.</div></div>","alt":["גַּלְגֵּיל"]},"7727":{"h":"גַּלְגַּל","r":"C00871","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"גַּלְגֵּל\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>wheel</i>, esp. <i>the wheel-work at wells, crane</i> &amp;c. <span class=\"citation\">Midd. V, 4</span>. <span class=\"citation\">Tosef. B. Bath. II, 16</span> <span dir=\"rtl\">בית גולגל לרבים</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"גִּילְגּוּל\">גילגל</a>) a public well. <span class=\"citation\">B. Bath. IV, 5</span> <span dir=\"rtl\">את הג׳</span> the crane of the wine or oil press, v. <a href=\"#\" data-headword=\"חוּמַרְתָּא\">חוּמַרְתָּא</a>. <span class=\"citation\">Erub. X, 14</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>globe, celestial sphere</i>, esp. <i>the sphere of the zodiac</i>. <span class=\"citation\">Yoma 20ᵇ</span>, a. e. <span dir=\"rtl\">ג׳ חמה</span> the revolution of the Sun. <span class=\"citation\">Pes. 94ᵇ</span> <span dir=\"rtl\">ג׳ קבוע ומזלות וכ׳</span> the sphere of the zodiac is stationary, and the planets make the circuit; <span dir=\"rtl\">ג׳ חוזר וכ׳</span> the sphere (wheel) turns around and the planets are stationary; a. fr.—<span class=\"citation\">B. Bath. 16ᵇ</span> Ms. M. <span dir=\"rtl\">מה עדש זה דומה לג׳ וכ׳</span> as the lentil resembles a sphere, so is mourning a sphere making a circuit in the world; (diff. in ed., v. <a href=\"#\" data-headword=\"גִּלְגֵּל\">גִּלְגֵּל</a>); <span class=\"citation\">Yalk. Gen. 110</span> <span dir=\"rtl\">מה עדשים האלו ג׳ וכ׳</span>.</div><div class=\"sense\"><b>—3)</b> <i>the eye-ball</i>. <span class=\"citation\">Gen. R. s. 42</span>; <span class=\"citation\">Lev. R. s. 11</span>; Ruth R. introd. 6 (ref. to <span dir=\"rtl\">עין משפט</span> <span class=\"citation\">Gen. XIV, 7</span>) <span dir=\"rtl\">ג׳ עינו של עולם</span> the eye-ball of the world (Abraham). <span class=\"citation\">Snh. 108ᵃ</span> <span dir=\"rtl\">בשביל ג׳ העין וכ׳</span> on account of (the covetousness of) the eye-ball (v. <a href=\"#\" data-headword=\"גַּלְגַּל ²\">next w.</a>); a. e.—Pl. <span dir=\"rtl\">גַּלְגִּלִּים</span>. <span class=\"citation\">Makhsh. III, 8</span> wheel works. <span class=\"citation\">B. Bath. 58ᵃ</span> <span dir=\"rtl\">שני גַּלְגִּלִּי חמה</span> two Sun-globes.—<span class=\"citation\">Y. Nidd. III, 50ᶜ</span> bot. <span dir=\"rtl\">ג׳ אדם וכ׳</span> the apples of man’s eyes are round.—Trnsf. <i>the rotation of fortune, changes</i> (v. <span class=\"citation\">B. Bath. 16ᵇ</span> quot. above). <span class=\"citation\">Sabb. 151ᵇ</span> (ref. to <span dir=\"rtl\">בִּגְלַל</span> <span class=\"citation\">Deut. XV, 10</span>) <span dir=\"rtl\">ג׳ הוא וכ׳</span> a wheel rotates in this world, i.e. changes of fortune take place constantly; <span class=\"citation\">Ex. R. s. 31</span>, a. e.—3) (= <a href=\"#\" data-headword=\"גַּרְגַּר\">גַּרְגַּר</a>) <i>globule, grain</i>. <span class=\"citation\">Sabb. 64ᵇ</span>; <span class=\"citation\">65ᵃ</span>, v. <a href=\"#\" data-headword=\"גַּרְגַּר\">גַּרְגַּר</a>.—<i>Pl.</i> as above. Y. Maasr. V, end, 52ᵃ; <span class=\"citation\">Tosef. ib. III, 14</span> Egyptian beans are those <span dir=\"rtl\">שגַּלְגִּלֵּיהֶן חדין</span> (ed. Zuck. <span dir=\"rtl\">גלוגל׳</span>, Var. <span dir=\"rtl\">גלגל הן</span>, corr. acc.) whose globules are pointed.</div>","alt":[]},"7728":{"h":"גַּלְגַּל ²","r":"C00872","html":"<div class=\"sense\"><b>1)</b> <i>wheel</i>. <span class=\"citation\">Targ. Ezek. I, 15</span> sq. <a href=\"#\" data-headword=\"גִּלְגּוּל\">גִּילְ׳</a> ed. Lag. <span class=\"citation\">Targ. Ps. LXXXIII, 14</span>; a. e.—<span class=\"citation\">Erub. 104ᵃ</span> <span dir=\"rtl\">למימלא בגי׳</span> to fill (draw water) with the wheel. <span class=\"citation\">Lev. R. s. 34</span>, v. <a href=\"#\" data-headword=\"אַנְטְלַיָּא\">אַנְטְלַיָּא</a>.</div><div class=\"sense\"><b>—2)</b> <i>globe, celestial sphere</i>. <span class=\"citation\">Targ. Ps. LXXVII, 19</span>. <span class=\"citation\">Targ. Job XXXVIII, 33</span>.—<span class=\"citation\">B. Bath. 74ᵃ</span> <span dir=\"rtl\">ג׳ דרקיע וכ׳</span> the sphere of the zodiac which turns around.</div><div class=\"sense\"><b>—3)</b> <i>eye-ball</i>. <span class=\"citation\">Targ. Ps. XVII, 8</span> <a href=\"#\" data-headword=\"גִּילְגּוּל\">גִּילְגוּל</a> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"גִּלְגּוּל\">גִּלְגּוּל</a>; Ms. <a href=\"#\" data-headword=\"גִּיגַּל\">גִּיגַּל</a>).—<span class=\"citation\">Tam. 32ᵇ</span> they handed him <span dir=\"rtl\">ג׳ דעינא</span> Ar. (ed. <a href=\"#\" data-headword=\"גּוּלְגַּלְתָּא\">גולגלתא</a> incorr.) an eye-ball. Ib. <span dir=\"rtl\">גולגלתא דעינא וכ׳</span> (read <a href=\"#\" data-headword=\"גִּילְגּוּל\">גילגלא</a>) the eye-ball of a mortal which is never satisfied. <span class=\"citation\">B. Bath. 73ᵇ</span></div><div class=\"sense\"><b>—4)</b> <i>stubble</i>. <span class=\"citation\">Targ. Is. XVII, 13</span>.—Pl. <span dir=\"rtl\">גִּלְגְּלַיָּא</span>, <a href=\"#\" data-headword=\"גִּלְגּוּל\">גִּילְ׳</a>. <span class=\"citation\">Targ. Ezek. I, 16</span> sq.—<span class=\"citation\">Targ. Ex. XIV, 25</span> <a href=\"#\" data-headword=\"גַּלְגַּל ²\">גִּלְגְּלֵי</a> ed. Berl. (ed. a. Y. <a href=\"#\" data-headword=\"גַּלְגַּל\">גַּלְגַּלֵי</a>). Targ. Y. II ib. <span dir=\"rtl\">גֶּלְגְּלַיָּא</span>; a. e.—<span class=\"citation\">Koh. R. to XII, 6</span>; <span class=\"citation\">Lev. R. s. 18</span>; a. e.—4) (v. <a href=\"#\" data-headword=\"גַּלְגִּלּוֹן\">next w.</a>) <i>a sort of girdle. </i> Pl. <span dir=\"rtl\">גַּלְגְּלַיָּיה</span>. Y. Sabb. VI, 8ᵇ bot. (transl. of <span dir=\"rtl\">גליונים</span>, <span class=\"citation\">Is. III, 22</span>), v. <a href=\"#\" data-headword=\"גִּלָּיוֹן\">גִּלְיוֹן</a> 3.</div>","alt":["גִּלְגְּלָא","גִּילְ׳"]},"7729":{"h":"גַּלְגִּלּוֹן","r":"C00873","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"גִּלְגְּלִין\">next w.</a></div>","alt":[]},"7730":{"h":"גִּלְגְּלִין","r":"C00874","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (used as sing.; <span dir=\"rtl\">גלל</span>) <i>girdle of net-work, bandage, wrap.</i> <span class=\"citation\">Eduy. III, 4</span> (Ms. M. <a href=\"#\" data-headword=\"גִּנְגִּילוֹן\">גנגלון</a>, v. infra). <span class=\"citation\">Neg. XI, 11</span> <a href=\"#\" data-headword=\"גַּלְגִּלּוֹן\">גלגלון</a>.—<span class=\"citation\">Y. Naz. VII, 56ᵇ</span> bot. <span dir=\"rtl\">נקבר אפי׳ ג׳ קטן וכ׳</span> if there is buried with the corpse even a small wrap (or belt), the law concerning decayed corpses (v. <a href=\"#\" data-headword=\"רָקָב\">רָקָב</a>) finds no application. Ib. if two corpses are buried beside each other <span dir=\"rtl\">נעשה ג׳ לזה וכ׳</span> each acts as <i>gilg’lin</i> to the other (suspending the law of <i>rakab</i>); Bab. <span class=\"citation\">Naz. 51ᵃ</span>; <span class=\"citation\">Nidd. 27ᵇ</span> <a href=\"#\" data-headword=\"גִּנְגִּילוֹן\">גנגילון</a>. <span class=\"citation\">Tosef. Kel. B. Bath. V, 9</span> <span dir=\"rtl\">גנגלין</span>. Sifra Sh’mini ch. XI, Par. 10 <span dir=\"rtl\">גנגלים וגנגיליון</span> (a fusion of two versions); ib. Aḥăré Par. 8, ch. XII <span dir=\"rtl\">גינגליון</span>; a. e. [Var. lect.: <a href=\"#\" data-headword=\"גִּנְגִּילוֹן\">גנגילון</a>, <a href=\"#\" data-headword=\"גִּנְגִּילוֹן\">גנגלון</a>, <a href=\"#\" data-headword=\"גנגלים\">גנגלים</a>, influenced by the Latin <i>cingulum</i> to which our w. nearly corresponds.]</div>","alt":["גִּילְגְּלִין"]},"7731":{"h":"גּלְגֹּלֶת","r":"C00875","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גּוּלְגּוֹלֶת\">גּוּלְגּוֹלֶת</a></div>","alt":[]},"7732":{"h":"גַּלְגַּלְתָּא","r":"C00876","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">גלל</span>) <i>ball, round stone</i>. <span class=\"citation\">Gitt. 47ᵃ</span> <span dir=\"rtl\">חייתא וג׳</span> a bag and a stone (in it).</div>","alt":[]},"7733":{"h":"גָּלַד","r":"C00877","html":"<div class=\"sense\"><i>to form a coating; to congeal, become solid</i>. <span class=\"citation\">Y. Ber. I, 2ᶜ</span> bot. <span dir=\"rtl\">יִגְלֹד הרקיע</span> let the (liquid mass of the) firmament solidify; <span class=\"citation\">Gen. R. s. 4</span>, beg. <span dir=\"rtl\">גָּלְדָה טיפה וכ׳</span> the intermediate layer of water solidified.—<i>Part. pass.</i> <a href=\"#\" data-headword=\"גָּמוּד\">גָּלוּד</a>, f. <span dir=\"rtl\">גְּלוּדָה</span> (denom. of <a href=\"#\" data-headword=\"גֶּלֶד\">גֶּלֶד</a>) <i>skinned, flayed</i> in consequence of bruises, scabs &amp;c. Ḥull. III, 2; Tosef. ib. III, 7; a. e.</div><div class=\"sense\"><b>Hif. הִגְלִיד</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"גַּלְגַּלְתָּא\">same</a>. <span class=\"citation\">Tosef. Par. IX</span> (<span class=\"citation\">VIII), 8</span> <span dir=\"rtl\">הִגְלִידוּ</span> froze. <span class=\"citation\">Nidd. 56ᵇ</span>; <span class=\"citation\">Tosef. ib. VI, 13</span> <span dir=\"rtl\">מַגְלִיד</span> forms a clodded surface, opp. <span dir=\"rtl\">מקדיר</span> penetrates.</div><div class=\"sense\"><b>—2)</b> <i>to form a rind, scab;</i> v. infra.</div></div><div class=\"sense\"><b>Hof. הוּגְלָד</b> <div class=\"sense\"><i>to be covered with a scab</i> (of a wound). Ḥull. 51ᵃ הו׳ פי המכה Rashi a. Ar. (ed. <a href=\"#\" data-headword=\"גָּלַד\">הִגְלִיד</a>) if the top of the wound is covered with a crust; <span class=\"citation\">Keth. 76ᵇ</span>; <span class=\"citation\">Tosef. Ḥull. III, 11</span> <a href=\"#\" data-headword=\"גָּלַד\">הגליד</a>.</div></div>","alt":[]},"7734":{"h":"גְּלַד","r":"C00878","html":"<div class=\"sense\">—<i>Part. pass</i>. <a href=\"#\" data-headword=\"גְּלִיד\">גְּלִיד</a> <i>hoar-covered</i>. <span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">טור תלג סחרנוהי גְלִידִין</span> (v. Rabb. D. S. a. l. note) the mountain (my head) is snow-covered, its sides (beard) hoary. [<span class=\"citation\">Lev. R. s. 7</span>, v. next w.]</div><div class=\"sense\"><b>Ithpe. אִיגְּלִיד</b> <div class=\"sense\"><i>to be flayed</i>. <span class=\"citation\">Ḥull. 46ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲהִינָא\">אֲהִינָא</a>; <span class=\"citation\">Succ. 35ᵇ</span></div></div>","alt":[]},"7735":{"h":"גֶּלֶד","r":"C00879","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>coating, skin; thickness</i>. Y. B. Bath. III, 13ᶜ top <span dir=\"rtl\">עד מקום שעושה ג׳</span> the fifty cubits of legal distance from the inhabited place are counted from the end of the town to the place where he flays the carcass. <span class=\"citation\">Yoma 44ᵇ</span> [read:] <span dir=\"rtl\">בכל יום היה גִּלְדָּהּ עב והיום דק</span> (v. Rabb. D. S. a. l.) all the year around the pan was of a thick size, and this day (Day of Atonem.) it was thin. <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">קערה גִּילְדָּהּ … גִּילְדּוֹ דק</span> the charger was of a heavy size, the bowl &amp;c. <span class=\"citation\">R. Hash. 27ᵇ</span> if he scraped the Shofar <span dir=\"rtl\">והעמידו על גִּלְדּוֹ</span> and reduced it to its due size. <span class=\"citation\">Lev. R. s. 7</span> <span dir=\"rtl\">וא&quot;ת דהוה ג׳</span> (Ar. <a href=\"#\" data-headword=\"גָּלִיד\">גָּלִיד</a>) but you may think the bronze on top of the altar was a solid mass, v. <a href=\"#\" data-headword=\"גּוֹרְדְּיָינִי\">גּוֹרְדְּיָינִי</a>.</div><div class=\"sense\"><b>—2)</b> <i>scab</i> of a wound, <i>crust.</i> <span class=\"citation\">Mikv. IX, 2</span> <span dir=\"rtl\">ג׳ שחוץ למכה</span> (Maim. <span dir=\"rtl\">גָּלִיד שעל גבי וכ׳</span>) the scab surrounding the wound (Maim.: on the wound).—Pl. <span dir=\"rtl\">גְּלָדִים</span>, constr. <span dir=\"rtl\">גִּלְדֵּי</span>, <span dir=\"rtl\">גִּילְדֵּי</span>. Ib. <span dir=\"rtl\">ג׳ צואה וכ׳</span> the scabby, dirty spots on one’s body.</div>","alt":[]},"7736":{"h":"גִּלְדָּא","r":"C00880","html":"<div class=\"sense\"><b>1)</b> <i>plate, covering</i>. <span class=\"citation\">Targ. Y. I Num. VII, 13</span> <span dir=\"rtl\">גי׳ סמיך</span> (= <span dir=\"rtl\">גֶּלֶד עב</span>, v. <a href=\"#\" data-headword=\"גֶּלֶד\">preced.</a>).—Pl. <span dir=\"rtl\">גִּי׳ גִּלְדִּין</span> <span class=\"citation\">Targ. Ezek. XXVII, 24</span> <span dir=\"rtl\">חפן ג׳</span> (gold, or silver) plated.</div><div class=\"sense\"><b>—2)</b> <i>scab, scurf.</i> Pl. <span dir=\"rtl\">גִּלְדֵּי</span>, <span dir=\"rtl\">גִּי׳</span>. Ḥull. 46ᵇ lungs full <span dir=\"rtl\">ג׳ ג׳</span> of scabs.—8) <i>skin, leather</i>. <span class=\"citation\">Targ. I Sam. XVII, 5</span> (v. Lag. I, p. XVI) <span dir=\"rtl\">שריין דגלד נוני ימא</span> (ed. <span dir=\"rtl\">שרין גלבין</span>) a coat of mail made of the skin of sea-fishes (h. text <span dir=\"rtl\">קשקשים</span>).—<span class=\"citation\">Snh. 110ᵃ</span>; <span class=\"citation\">Pes. 119ᵃ</span> <span dir=\"rtl\">אקלידי וקלפי דג׳</span> (Ms. M. <span dir=\"rtl\">קופלי</span>, v. Rabb. D. S. a. l. note) the keys and the locks (the stiff rims of the bags usually of metal) were of leather (so as to be of light weight). <span class=\"citation\">Ber. 43ᵇ</span> <span dir=\"rtl\">בגי׳</span> on the leather of the shoe, opp. <span dir=\"rtl\">פנתא</span>, v. <a href=\"#\" data-headword=\"אַפַּנְתָּא\">אַפַּנְתָּא</a> (Rashi: <i>heel</i>).</div>","alt":["גִּילְ׳"]},"7737":{"h":"גִּלְדָּאָה","r":"C00881","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גִּלְדָּא\">preced.</a>) <i>worker</i> or <i>dealer in leather, harness-maker</i> &amp;c.—Pl. <a href=\"#\" data-headword=\"גִּלְדָּא\">גִּלְדָּאֵי</a>, <a href=\"#\" data-headword=\"גִּלְגּוּל\">גִּילְ׳</a>. <span class=\"citation\">B. Mets. 24ᵇ</span>; <span class=\"citation\">Ḥull. 48ᵃ</span> sq. <span dir=\"rtl\">שוקא דג׳</span> harness-makers’ place.</div>","alt":["גִּילְ׳"]},"7738":{"h":"גִּלְדָּנָא","r":"C00882","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גלד</span>) <i>gildana</i>, name of a certain fish with a <i>thick fatty skin</i>. <span class=\"citation\">Snh. 100ᵇ</span> <span dir=\"rtl\">לא תנטוש גיל׳ וכ׳</span> (Ms. M. <span dir=\"rtl\">תפשוט</span>) do not begin to strip the <i>gildana</i> from its gill, lest its skin go to ruin (a citation from Ben Sira). <span class=\"citation\">B. Bath. 73ᵇ</span> <span dir=\"rtl\">ההוא ג׳ וכ׳</span> that was a sea <i>gildana</i> (a small fish among the sea monsters). <span class=\"citation\">Hor. 12ᵃ</span>; <span class=\"citation\">Ker. 6ᵃ</span>.—Pl. <a href=\"#\" data-headword=\"גִּלְדָּנָא\">גִּלְדָּנֵי</a>, <a href=\"#\" data-headword=\"גִּלְגּוּל\">גִּילְ׳</a>. <span class=\"citation\">Tam. 32ᵇ</span> ג׳ דמלחא Rashi (ed. <a href=\"#\" data-headword=\"גּוּלְדָּנָא\">גולדנא</a>) salted g. <span class=\"citation\">Ber. 44ᵇ</span>; <span class=\"citation\">Keth. 105ᵇ</span>, v. <a href=\"#\" data-headword=\"גִּילָא II\"><span dir=\"rtl\">גִּילָא</span> II</a>.</div>","alt":["גִּילְ׳"]},"7739":{"h":"גִּלָּה","r":"C00883","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">גלל</span>, cmp. <a href=\"#\" data-headword=\"גַּל\">גַּל</a> 3) <i>a valve, folding</i>. <span class=\"citation\">Y. Sabb. XII, beg. 13ᶜ</span> <span dir=\"rtl\">מטה של ג׳</span> folding couch.—Pl. <span dir=\"rtl\">גִּלִּין</span>. Bab. <span class=\"citation\">Sabb. 138ᵃ</span> <span dir=\"rtl\">כסא ג׳</span> camp chair.</div>","alt":["גִּילָּה"]},"7740":{"h":"גֻּלָּה","r":"C00884","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גּוּלָּה\">גּוּלָּה</a></div>","alt":[]},"7741":{"h":"גָּלָה","r":"C00885","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גלי\">גלי</a></div>","alt":[]},"7742":{"h":"גָּלוּ","r":"C00886","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּלוּתָא\">גָּלוּתָא</a></div>","alt":[]},"7743":{"h":"גלובדק","r":"C00887","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\">גְּלוּגְדְּקָא</a></div>","alt":[]},"7744":{"h":"גלוביא","r":"C00888","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גְּלַבְקְיָא\">גְּלַבְקְיָא</a></div>","alt":[]},"7745":{"h":"גְּלוּגְדְּקָא","r":"C00889","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (popular corruption of <i>lectica;</i> for the prefixed guttural cmp. laena and χλαῖνα, lectum and κλίνη; v. Liddell &amp; Scott’s Greek Dict. s. lit. Γ) </div><div class=\"sense\"><b>1)</b> <i>litter, sedan-chair</i>. <span class=\"citation\">Bets. 25ᵇ</span> Ar. (ed. <a href=\"#\" data-headword=\"גלודקי\">גלודקי</a>, Ms. M. <span dir=\"rtl\">גלנדקי</span>). <span class=\"citation\">Cant. R. to V, 5</span>; <span class=\"citation\">Koh. R. to IX, 11</span> <span dir=\"rtl\">אפי׳ בגלק׳ לא וכ׳</span> could not even be carried in a <i>lectica</i>. <span class=\"citation\">Cant. R. to IV, 8</span> <span dir=\"rtl\">בכל קדיקה</span>; <span class=\"citation\">Yalk. Ps. 838</span> <span dir=\"rtl\">כל קרקיא</span> (read <span dir=\"rtl\">בִּכְלֶקְדִּיקָא</span>). Ib. Lev. 666 <span dir=\"rtl\">שלא יטייל אחריך בגלטק׳</span>; Sifra B’har Par. 5, ch. VII … <span dir=\"rtl\">יטול … בלנטיא</span>) he (the Hebrew servant) shall not walk behind thee when thou art carried in the lectica, v. <a href=\"#\" data-headword=\"לֶקְטִיקָא\">לֶקְטִיקָא</a>. <span class=\"citation\">Sifré Deut. 37</span> <a href=\"#\" data-headword=\"גלגוטיקא\">גלגוטיקא</a>; <span class=\"citation\">Yalk. Kings 238</span> <a href=\"#\" data-headword=\"גלוגיקא\">גלוגיקא</a>.—</div><div class=\"sense\"><b>*2)</b>  (= lecticula) <i>bier</i>. <span class=\"citation\">Targ. Job XV, 24</span> איטימוס לגלוגדיקא Ar. ed. Koh. (ed. <span dir=\"rtl\">לגלוגדק</span>) ready for the bier (for death, cmp. LXX).</div><div class=\"sense\"><b>—3)</b>  *<i>foot-stool</i> to the throne. <span class=\"citation\">Targ. Y. Ex. XXIV, 10</span> <span dir=\"rtl\">אתקניה גְּלוּגְדַּק וכ׳</span> (<a href=\"#\" data-headword=\"גִּלָּיוֹן\">גִּיל׳</a> some ed.) made the sapphire brick a foot-stool in place of the <i>hypopodion</i> &amp;c.—<span class=\"citation\">Targ. Lam. II, 1</span> <span dir=\"rtl\">גלוגדקא דרגלוהי</span> (h. text <span dir=\"rtl\">הדום רגליו</span>).</div>","alt":["(גלוגדק)","גְּלֶקְטִיקָא"]},"7746":{"h":"גלוגות","r":"C00890","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲלַגְלוֹג\">חֲלַגְלוֹג׳</a></div>","alt":[]},"7747":{"h":"גלוגיקא","r":"C00891","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גלוגות\">preced. art.</a></div>","alt":[]},"7748":{"h":"גלוגלין","r":"C00892","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Maasr. III, 14</span>, v. <a href=\"#\" data-headword=\"גַּלְגַּל\">גַּלְגַּל</a></div>","alt":[]},"7749":{"h":"גלודקי","r":"C00893","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\">גְּלוּגְדְּקָא</a></div>","alt":[]},"7750":{"h":"גלוהי","r":"C00894","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּילְהֵי\">גִּילְהֵי</a></div>","alt":[]},"7751":{"h":"גלוואי","r":"C00895","html":"<div class=\"sense\">, Lam. R. introd., beg., v. <a href=\"#\" data-headword=\"גָּלוֹיָא\">גָּלוֹיָא</a></div>","alt":[]},"7752":{"h":"גלווקי","r":"C00896","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גּוּאַלְקָא\">גּוּאַלְקָא</a></div>","alt":[]},"7753":{"h":"גָּלוּי","r":"C00897","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (part. pass. of <a href=\"#\" data-headword=\"גָּלָה\">גָּלָה</a>) <i>appearance, outside</i>. <span class=\"citation\">Gen. R. s. 45</span> <span dir=\"rtl\">אין סיתרה כגְלוּיָהּ</span> her private conduct is not like her public appearance (she is insincere); ib. s. 71.—בַּגָּ׳ <i>in public, visible to all</i>, opp. <span dir=\"rtl\">בסתר</span>. <span class=\"citation\">Ab. IV, 4</span> he will be punished <span dir=\"rtl\">בג׳</span> in an ostensible way. <span class=\"citation\">Sot. 3ᵃ</span>; a. fr.</div>","alt":[]},"7754":{"h":"גִּלּוּי","r":"C00898","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּילּוּי\">גִּילּוּי</a>, <a href=\"#\" data-headword=\"גִּילּוּיָיא\"><a href=\"#\" data-headword=\"גִּילּוּיָיא\">גִילּוּיָא</a>.</a></div>","alt":[]},"7755":{"h":"גָּלוֹיָא","r":"C00899","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גלי\">גלי</a>) <i>exile, stranger.</i> Pl. <a href=\"#\" data-headword=\"גַּלּוּיֵי\">גָּלוֹיֵי</a>. <span class=\"citation\">Lev. R. s. 5</span> גלויא בר גלויי Ar. (ed. <span dir=\"rtl\">גלויי בר ג׳</span>, corr. acc.) thou stranger, son of strangers. Lam. R. introd. beg. <a href=\"#\" data-headword=\"גלוואי\">גלוואי</a>, read <span dir=\"rtl\">גְּלוֹיָיאֵי</span> (Ar. <span dir=\"rtl\">גְּלוֹלָאֵי</span>).</div>","alt":[]},"7756":{"h":"גַּלּוּיֵי","r":"C00900","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גלי\">גלי</a> ch.</div>","alt":[]},"7757":{"h":"גִּלּוּל","r":"C00901","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">גִּלּוּלִים</span>, <span dir=\"rtl\">גִּי׳</span> (b. h.; <i>filth</i> (v. <a href=\"#\" data-headword=\"גָּלָל\">גָּלָל</a>), <i>idols</i>. <span class=\"citation\">Meg. 13ᵃ</span> to clean herself <span dir=\"rtl\">מִגִּלּוּלֵי בית אביה</span> from the contamination of her paternal idolatry. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מרדה בגילולי וכ׳</span> she rejected &amp;c.—<span dir=\"rtl\">עובד ג׳</span>, <span dir=\"rtl\">עבודת ג׳</span> (abbr. <span dir=\"rtl\">ע&quot;ג</span>) <i>idolator, idolatry</i>. In some ed. for <a href=\"#\" data-headword=\"עכ\">עכ&quot;ום</a>, <span dir=\"rtl\">ע&quot;ז</span> &amp;c.; v. <a href=\"#\" data-headword=\"זָר\">זָר</a> a. <a href=\"#\" data-headword=\"כּוֹכָב\">כּוֹכָב</a>.</div>","alt":["גִּילּוּל"]},"7758":{"h":"גָּלוֹלָא","r":"C00902","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גלל</span>) <i>cast about, homeless.</i> Pl. <span dir=\"rtl\">גְּלוֹלָאֵי</span>, <a href=\"#\" data-headword=\"גְּלִילָא\">גְּלוֹלַיָּא</a>. Lam. R. introd., beg. Ar., v. <a href=\"#\" data-headword=\"גָּלוֹיָא\">גָּלוֹיָא</a>; Pesik. Dibré, p. 110ᵇ <a href=\"#\" data-headword=\"גְּלִילָא\">גליליא</a> (Var. <span dir=\"rtl\">גְּלוֹ׳</span>, v. Bub. note a. l.). V. <a href=\"#\" data-headword=\"גְּלִילָה\">גְּלִילָה</a>.</div>","alt":[]},"7759":{"h":"גָּלוּם","r":"C00903","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גּוֹלֶם\">גּוֹלֶם</a></div>","alt":[]},"7760":{"h":"גלוסא","r":"C00904","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּרִיסָא\">גְּרִיסָא</a></div>","alt":[]},"7761":{"h":"גְּלוֹסְטְרָא","r":"C00905","html":"<div class=\"sense\"> (claustra, clostra, pl.) <i>fastening, lock, bar</i>. <span class=\"citation\">Erub. X, 10</span> <span dir=\"rtl\">נגר שיש בראשו ג׳</span> a door bolt which has on its top a (movable) fastening contrivance (which may occasionally be used as a pestle). <span class=\"citation\">Sabb. 123ᵇ</span> <a href=\"#\" data-headword=\"ג׳\">ג׳</a> (Ar. <a href=\"#\" data-headword=\"ק׳\">ק׳</a>, Ms. M. repeatedly <span dir=\"rtl\">גלוסקר׳</span>) the law about claustra, ref. to <span class=\"citation\">Kel. XI, 4</span> <a href=\"#\" data-headword=\"ק׳\">ק׳</a>. <span class=\"citation\">Sabb. 124ᵃ</span> <a href=\"#\" data-headword=\"ג׳\">ג׳</a>.</div>","alt":["קְלוֹסְטְרָא"]},"7762":{"h":"גְּלוּסְטְרָאָה","r":"C00906","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּלוֹסְטְרָא\">preced.</a>) <i>locksmith</i> (claustrarius). <span class=\"citation\">Ber. 22ᵃ</span> R. Yehudah <a href=\"#\" data-headword=\"גְּלוֹסְטְרָא\">גלוסטרא</a> (corr. acc., Ms. M. <span dir=\"rtl\">קלסתראה</span>, Yoḥăsin Completum p. 148ᵇ <span dir=\"rtl\">קְלוּסְטְרָאָה</span>).</div>","alt":[]},"7763":{"h":"גְּלוּסְקָא","r":"C00907","html":"<div class=\"sense\"> c. (a contraction of <span dir=\"rtl\">גלוסביקא</span> or <span dir=\"rtl\">גלופסיקא</span>, Lesbiacus, Lesbiaca, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a>, <a href=\"#\" data-headword=\"כְּלוּפְסִין\">לִבְסִים</a>, <a href=\"#\" data-headword=\"כְּלוּפְסִין\">קְלוּפְ׳</a>, <a href=\"#\" data-headword=\"כְּלוּפְסִין\">גְּלוּפְ׳</a>; as to guttural before <a href=\"#\" data-headword=\"ל\">ל</a>, v. <a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\">גְּלוּגְדְּקָא</a>) <i>relating to Lesbos</i> (an island of the Aegean Sea, noted for its fertility and luxuries), <i>Lesbian</i>, whence </div><div class=\"sense\"><b>1)</b>  [in Syriac] name of <i>a brand of white flour</i> (P. Sm. 726), <i>a white and delicate bread</i> (cmp. Athenæus Deipnosophistæ III, 111). <span class=\"citation\">Tosef. Ber. IV, 15</span> <span dir=\"rtl\">שלמה של גלוסקין</span> an unbroken loaf of <i>g’luskin</i>, opp. <span dir=\"rtl\">של בע&quot;הב</span> home-made. <span class=\"citation\">Dem. VI, 12</span> buy for me <span dir=\"rtl\">גְּלוּסְקָן אחד</span> ed. (accus.; Ms. M. <span dir=\"rtl\">גלוסקא אחת</span>, Ar. <span dir=\"rtl\">קין אחת …</span>, R. S. <span dir=\"rtl\">קלוסקן</span>) one loaf &amp;c. <span class=\"citation\">Y. Ab. Zar. I, 40ᵃ</span> bot. <span dir=\"rtl\">קלוסקין אחת</span>; <span class=\"citation\">Erub. 64ᵇ</span> <a href=\"#\" data-headword=\"גְּלוּסְקִין\">גלוסקין</a> pl.—<span class=\"citation\">Pes. 6ᵇ</span> he may find <span dir=\"rtl\">ג׳ יפה ודעתו עליה</span> Rashi (ed. <span dir=\"rtl\">ודעתיה עילויה</span>, Ms. M. <span dir=\"rtl\">יפיפיה</span>) a fine <i>gl.</i> which he may have the intention of eating (in place of burning). <span class=\"citation\">Lam. R. to I, 16</span> <a href=\"#\" data-headword=\"גְּלוּסְקָאן\">גלוסקאן</a>; a. e.—Pl. <span dir=\"rtl\">גְּלוּסְקָאוֹת</span>, <a href=\"#\" data-headword=\"גְּלוּסְקִין\">גְּלוּסְקִין</a>, <a href=\"#\" data-headword=\"קלירוס\">קְלוּ׳</a>. <span class=\"citation\">Sabb. 30ᵇ</span>. <span class=\"citation\">Gen. R. s. 88</span>, beg. <span class=\"citation\">Lam. R. to II, 12</span> <span dir=\"rtl\">גלו׳</span> (Ar. ed. Koh. <span dir=\"rtl\">קלסקין</span>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>a superior sort of olives already pressed when appearing in the market</i> (θλασταί, σταφυλίδες, v. Athenæus l. c. II, 56; cmp. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a>). <span class=\"citation\">Ab. Zar. II, 7</span> זיתי קלוסקא המגולגלין Y. ed. II, 10 (Mish. <span dir=\"rtl\">זתים גלוסקאות</span>, Bab. ed. 39ᵇ <span dir=\"rtl\">זיתי ג׳</span>, Mish. Nap. <span dir=\"rtl\">קלוסטא</span>, Ar. ed. Koh. s. v. <span dir=\"rtl\">גלגל</span>: <span dir=\"rtl\">קלוסטא</span>, <span dir=\"rtl\">קלוסטרא</span>). Bab. ib. 40ᵇ (ed. Pes. a. oth. <span dir=\"rtl\">קלוסקא</span>, Alf. early ed. <span dir=\"rtl\">גלוסטא</span>, v. Rabb. D. S. a. l. note 4). Y. ib. II, 42ᵃ bot. <span dir=\"rtl\">הן זיתי ק׳ וכ׳</span> <i>zethé k’luska</i> is the same as <i>rolled olives</i>. [<span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">גלוסקאות</span>, v. <a href=\"#\" data-headword=\"גְּלוֹסְקְמָא\">גְּלוֹסְקְמָא</a>.]</div>","alt":["קְלוּסְקָא","קין"]},"7764":{"h":"גְּלוּסְקָאן","r":"C00908","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּסְקָא\">preced.</a></div>","alt":[]},"7765":{"h":"גלוסקוים","r":"C00909","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּסְקִין\">next art.</a></div>","alt":["גְּלוּסְקוֹם"]},"7766":{"h":"גְּלוּסְקִין","r":"C00910","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּסְקָא\">גְּלוּסְקָא</a></div>","alt":[]},"7767":{"h":"גְּלוֹסְקְמָא","r":"C00911","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (γλωσσόκομον, v. LXX, <span class=\"citation\">II Chr. XXIV, 8</span>; as to <a href=\"#\" data-headword=\"ד\">ד</a> for <a href=\"#\" data-headword=\"ג׳\">ג׳</a>, v. Liddell &amp; Scott s. lit. Δ) <i>case, chest, coffin</i>. Y. Sot. VII, 22ᵈ <span dir=\"rtl\">כמין גלוסקום</span> a kind of casing; <span class=\"citation\">Y. Shek. VI, 49ᵈ</span> bot. <a href=\"#\" data-headword=\"גלוסקוים\">גלוסקוים</a> (corr. acc.).—<span class=\"citation\">Gitt. III, 3</span> if he found the document <span dir=\"rtl\">בג׳ …</span> Ar. (ed. <span dir=\"rtl\">בד׳</span>) in a case; expl. ib. 28ᵃ <span dir=\"rtl\">טליקא דסבי</span> a box for elders (for keeping documents &amp;c.); <span class=\"citation\">B. Mets. I, 8</span> Y. ed. <a href=\"#\" data-headword=\"ג׳\">ג׳</a> (<span class=\"citation\">B. Mets. 20ᵃ</span>; <span class=\"citation\">20ᵇ</span> a. Mish. <a href=\"#\" data-headword=\"ד׳\">ד׳</a>). <span class=\"citation\">Meïl. VI, 1</span> <a href=\"#\" data-headword=\"ג׳\">ג׳</a> (Bab. ed. 21ᵃ <a href=\"#\" data-headword=\"ד׳\">ד׳</a>). <span class=\"citation\">M. Kat. 24ᵇ</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"ד׳\">ד׳</a>) <span dir=\"rtl\">ג׳ הניטלת באגפיים</span></span> a coffin carried by its handles.—Pl. <span dir=\"rtl\">גְּלוֹסְקְמִין</span>, <span dir=\"rtl\">גְּלוֹסְקְמָאוֹת</span>, <span dir=\"rtl\">דְּ׳</span>. <span class=\"citation\">Meg. 26ᵇ</span> <span dir=\"rtl\">דְּלוֹסְקְמֵי ספרים</span> (Alf. Ms. <span dir=\"rtl\">קְמָאוֹת …</span>, ed. <span dir=\"rtl\">סקאות …</span>) cases for books &amp;c.—<span class=\"citation\">Ex. R. s. 30</span>, end <span dir=\"rtl\">פותח הגלוסקאות</span> (corr. acc.) he opens the cases (containing his goods).</div>","alt":["גְּלוֹסְקוֹם","דְּלוּסְקְמָא"]},"7768":{"h":"גְּלוֹף","r":"C00912","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלַף I\">גְּלַף</a></div>","alt":[]},"7769":{"h":"גְּלוּפְסִין","r":"C00913","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a></div>","alt":[]},"7770":{"h":"גְּלוּפְקְרָא","r":"C00914","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּפְקְרֵי\">next w.</a></div>","alt":[]},"7771":{"h":"גְּלוּפְקְרֵי","r":"C00915","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (cubicularia, sub. gausapina &amp;c.) <i>woolly bed-covers, blankets</i>. <span class=\"citation\">Targ. Y. I Deut. XXIV, 13</span> (h. text <a href=\"#\" data-headword=\"שַׂלְמָה\">שַׂלְמָה</a>).—<span class=\"citation\">Sabb. 51ᵃ</span>; <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">IV), 20</span>, opp. <a href=\"#\" data-headword=\"סָדִין\">סדין</a> linen sheets. <span class=\"citation\">Gitt. 70ᵇ</span> <span dir=\"rtl\">ג׳ וסדיני</span> (Var. <a href=\"#\" data-headword=\"*גּוּשְׁפְּקֵי\">גושפקי</a>) shall we ascertain his sanity of mind, according to the season, by asking him whether he desires heavy or light covers? <span class=\"citation\">Ib. 35ᵃ</span> גלופקרין אחד Ar. (ed. <a href=\"#\" data-headword=\"גְּלוּפְקְרָא\">גלופקרא</a>) one set of bed-clothes.—<span class=\"citation\">Kel. XXIX, 2</span> <span dir=\"rtl\">קלובקרין אחד</span> (Bart. <a href=\"#\" data-headword=\"גְּלוּפְקְרֵי\">גלופקרין</a>, Bab. ed. <span dir=\"rtl\">אחת</span>). <span class=\"citation\">Tosef. Sabb. VI</span> (<span class=\"citation\">VII), 4</span>; <span class=\"citation\">Yalk. Lev. 587</span>.</div>","alt":["גְּלוּפְקְרִין","קְלוּבְקְרִין"]},"7772":{"h":"גלורין","r":"C00916","html":"<div class=\"sense\">, <span class=\"citation\">Num. R. s. 11</span>, read <span dir=\"rtl\">גַּלְיָרִין</span>, v. <a href=\"#\" data-headword=\"גּוּלְיָיר\">גּוּלְיָיר</a></div>","alt":[]},"7773":{"h":"גְּלוֹשׁ","r":"C00917","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גלש</span>) <i>bald-headed</i>. <span class=\"citation\">Targ. O. Lev. XIII, 41</span>.</div>","alt":[]},"7774":{"h":"גְּלוֹשׁוּתָא","r":"C00918","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּלוֹשׁ\">preced.</a>) <i>bald forehead</i>. <span class=\"citation\">Targ. O. Lev. XIII, 42</span> sq. (some ed. <span dir=\"rtl\">גְּלוֹשְׁתָּא</span>).</div>","alt":[]},"7775":{"h":"גָּלוּת","r":"C00919","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>exile;</i> also (sub. <a href=\"#\" data-headword=\"בני\">בני</a>) <i>the exiled community, diaspora.</i> <span class=\"citation\">Ab. I, 11</span> <span dir=\"rtl\">שמא תחובו חובת ג׳</span> ye may be condemned to exile. <span class=\"citation\">Ber. 56ᵃ</span>, a. e. <span dir=\"rtl\">ג׳ מכפרת עון</span> exile (leaving home) is an expiation. <span dir=\"rtl\">ג׳ בבל</span> Babylonian captivity; <span dir=\"rtl\">ג׳ יון</span> Greek (Syrian) dominion; <span dir=\"rtl\">ג׳ אדום</span> Roman dominion. <span class=\"citation\">Ex. R. s. 15</span>.—Esp. <i>banishment to the city of refuge</i> (<span class=\"citation\">Num. XXXV, 11</span> sq.). <span class=\"citation\">Macc. II, 6</span>; a. fr.—Pl. <span dir=\"rtl\">גָּלִיּוֹת</span>. <span class=\"citation\">Arakh. 12ᵃ</span> <span dir=\"rtl\">שלש ג׳</span> three divisions of exiles; <span class=\"citation\">Num. R. s. 23</span>, end <span dir=\"rtl\">סנחריב הגלה … ג׳</span> Sennacherib carried them off in three divisions.—<span class=\"citation\">Pes. 88ᵃ</span> <span dir=\"rtl\">קבוץ ג׳</span> the reunion of the exiled. <span class=\"citation\">Men. 110ᵃ</span> <span dir=\"rtl\">ג׳ של שאר וכ׳</span> the exiled of other countries (besides Babylonia). <span class=\"citation\">Bets. 4ᵇ</span> <span dir=\"rtl\">שני ימים טובים של ג׳</span> the two Holy Days (in the place of the one Biblical) observed by those living abroad (whom the communications of the Palestinean authorities could not reach); a. fr.</div>","alt":[]},"7776":{"h":"גָּלוּתָא","r":"C00920","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Ex. XX, 14</span>. <span class=\"citation\">Targ. Am. I, 6</span>; a. e.—ריש ג׳ <i>Resh-Galutha</i>, chief of the Babylonian Jews. <span class=\"citation\">Succ. 31ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">גַּלְוָותָא</span>. <span class=\"citation\">Targ. Ps. LXIX, 1</span> <span dir=\"rtl\">גַּלְוַות</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"גָּלוּת\">גָּלוּת</a> sing.). <span class=\"citation\">Targ. Y. Ex. XL, 10</span>. <span class=\"citation\">Targ. O. Deut. XXX, 4</span> <span dir=\"rtl\">יהוין גַּלְוָ׳</span> ed. Berl. (ed. <span dir=\"rtl\">יהי גָלוּ׳</span>, corr. acc.) thy exiles; a. e.—<span class=\"citation\">Snh. 11ᵇ</span> <span dir=\"rtl\">בני ג׳ דבבל וכ׳</span> the diasporas of Babylonia and all other diasporas (v. Rabb. D. S. a. l. note). <span class=\"citation\">Ḥull. 60ᵇ</span> that the Egyptians might not call his brothers <a href=\"#\" data-headword=\"ג׳\">ג׳</a> <i>exiles</i></div>","alt":["גָּלוּ"]},"7777":{"h":"גָּלַח","r":"C00921","html":"<div class=\"sense\"> , <i>Pi.</i> <a href=\"#\" data-headword=\"גִּילוּחַ\">גִּלֵּחַ</a>, <a href=\"#\" data-headword=\"גִּילוּחַ\">גִּילֵּחַ</a> <i>to cut the hair, shave</i>. <span class=\"citation\">Naz. VI, 3</span>. <span class=\"citation\">Ib. IV, 6</span> <span dir=\"rtl\">ג׳ או גִילְּחוּהוּ וכ׳</span> if he himself or his friends cut his hair. <span class=\"citation\">M. Kat. III, 1</span> <span dir=\"rtl\">ואלו מְגַלְּחִין וכ׳</span> the following are permitted to cut their hair during the festive week. <span class=\"citation\">Ib. 14ᵃ</span> <span dir=\"rtl\">מותר לְגַלֵּחַ</span>; a. fr.—Part. pass. <span dir=\"rtl\">מְגוּלָּח</span>, f. <span dir=\"rtl\">מְגוּלַּחַת</span>. <span class=\"citation\">Naz. IV, 5</span> <span dir=\"rtl\">אשה מְגֻלַּ׳</span> a woman with her hair cut; Y. ib. IV, end, 53ᶜ</div>","alt":[]},"7778":{"h":"גְּלַח","r":"C00922","html":"<div class=\"sense\"> ch. Pa. <a href=\"#\" data-headword=\"גָּלַח\">גַּלַּח</a> same. <span class=\"citation\">Targ. O. Lev. XIII, 33</span>; a. fr.—<span class=\"citation\">M. Kat. 17ᵇ</span> <span dir=\"rtl\">איבעי ליה לגַלּוּחֵי וכ׳</span></div><div class=\"sense\"><b>Ithpa. אִתְגַּלַּח  אִיגַּלַּח</b> <div class=\"sense\"><i>to have one’s hair cut</i>. <span class=\"citation\">Targ. Jud. XVI, 17</span>; <span class=\"citation\">22</span>.—<span class=\"citation\">Sabb. 110ᵇ</span> <span dir=\"rtl\">לִיגַּלַּח וכ׳</span> let him have the middle part of his head shaved.</div></div>","alt":[]},"7779":{"h":"גַּלְחִי","r":"C00923","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Galḥi</i>, a legendary place in the district of Sodom. <span class=\"citation\">Nidd. 69ᵃ</span> <span dir=\"rtl\">האי דינא … דייני בג׳</span> such justice which is injustice is dealt out in G.</div>","alt":[]},"7780":{"h":"גלטורי","r":"C00924","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בגלטורי\">בגלטורי</a></div>","alt":[]},"7781":{"h":"גלטינון","r":"C00925","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּלְאַקְסִינוֹן\">גַּלְאַקְסִינוֹן</a></div>","alt":[]},"7782":{"h":"גלי","r":"C00926","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to be uncovered</i>. <span class=\"citation\">Tosef. Mikv. III, 1</span> a pit <span dir=\"rtl\">שגָּלַת</span> ed. Zuck. which was left open.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"גָּלוּי\">גָּלוּי</a> <i>open, revealed</i>. <span class=\"citation\">Sabb. 55ᵃ</span> <span dir=\"rtl\">ג׳ וידוע וכ׳</span> it is open and known to me. <span class=\"citation\">Ber. 60ᵇ</span>; a. fr. V. <a href=\"#\" data-headword=\"גָּלוּי\">גָּלוּי</a>.</div><div class=\"sense\"><b>—2)</b>  (of a place) <i>to become bare of inhabitants</i> (v. <span class=\"citation\">Jud. XVIII, 30</span>; <span class=\"citation\">Jer. I, 3</span>); (of the inhabitants) <i>to leave home, go into exile</i>. Y. Taan. I, 64ᵃ top <span dir=\"rtl\">בכ&quot;מ שגָּלוּ … גָּלַת וכ׳</span> whithersoever Israel went as exiles, the Divine Majesty went with them (ref. to <a href=\"#\" data-headword=\"גלי\">נגלה</a>, <span class=\"citation\">I Sam. II, 27</span>); <span class=\"citation\">Meg. 29ᵃ</span>; a. e.—Pesik. Haḥod. p. 48ᵃ <span dir=\"rtl\">אם ג׳ אחד מכם … כאילו גְּלִיתֶם כולכם</span> if one of you is banished (by the Roman Government) to &amp;c.: … as though ye all had been banished; <span class=\"citation\">Pesik. R. s. 15</span>; <span class=\"citation\">Cant. R. to II, 8</span>. <span class=\"citation\">Arakh. 12ᵃ</span>; <span class=\"citation\">Meg. 11ᵇ</span> <span dir=\"rtl\">גָּלוּ בשבע</span> they were transported to Babylonia in the seventh year (after the subjection of Jojakim). <span class=\"citation\">Macc. II, 1</span> <span dir=\"rtl\">אלו הן הַגּוֹלִין</span> the following (involuntary homicides) have to leave for the city of refuge. Ib. <span dir=\"rtl\">אינו גוֹלֶה</span> is not bound to flee to &amp;c. Ib. 3 <span dir=\"rtl\">האב גולה ע&quot;י הבן</span> a father is banished for killing his son; a. fr.</div><div class=\"sense\"><b>Hif. הֶגְלָה</b> <div class=\"sense\"><i>to banish, carry into captivity</i>. <span class=\"citation\">Macc. 12ᵇ</span> <span dir=\"rtl\">היו … מַגְלִין וכ׳</span> the Israelites executed the law of banishment in the desert. <span class=\"citation\">Num. R. s. 23</span>, end. <span class=\"citation\">Ruth R. to I, 1</span> <span dir=\"rtl\">ומַגְלָם מארצם</span> and is the cause of their exile &amp;c.; a. fr.—<span class=\"citation\">Koh. R. to XII, 6</span> (play on <span dir=\"rtl\">גלת</span> ib.) ‘the golden bowl’ is the gullet, <span dir=\"rtl\">שהיא מַגְלָה את הזהב ומריצה וכ׳</span> (not <a href=\"#\" data-headword=\"שְׁהִיָּה\">שהיה</a>; <span class=\"citation\">Lev. R. s. 18</span> <span dir=\"rtl\">שמכלה</span>, corr. acc.) which banishes the gold and makes the silver run, i.e. which impoverishes the glutton.</div></div><div class=\"sense\"><b>Nif. נִגְלָה</b> <div class=\"sense\"><i>to be discovered, exposed to view; to reveal one’s self, appear</i>. Tanḥ. Sh’moth 19 נ׳ עליו בקולו וכ׳ He revealed Himself to Moses with the voice of Amram &amp;c.; <span class=\"citation\">Ex. R. s. 3</span>. <span class=\"citation\">Ex. R. s. 2</span>, end <span dir=\"rtl\">בכ&quot;מ שהשכינה נִגְלֵית</span> wherever the Divine Glory appears. <span class=\"citation\">Snh. II, 1</span>, v. <a href=\"#\" data-headword=\"כסי ²\"><span dir=\"rtl\">כָּסָה</span> II</a>; a. fr.</div></div><div class=\"sense\"><b>Pi. גִּלָּה  גִּילָּה</b> <div class=\"sense\"><i>to uncover, remove; to discover, reveal, publish</i>. <span class=\"citation\">Ex. R. s. 15</span>, beg. <span dir=\"rtl\">גִּלּוּ הצדיקים וכ׳</span> the righteous uncovered their heads. <span class=\"citation\">Sot. V, 2</span>; <span class=\"citation\">Gen. R. s. 21</span> מי יְגַלֶּה עפר וכ׳ Oh that one would remove the dust from over thy eyes, i.e. Oh, that thou wouldst resurrect!; Y. Ber. IX, 13ᵈ bot.—<span class=\"citation\">Sabb. 88ᵃ</span> <span dir=\"rtl\">מי גי׳ וכ׳</span> who revealed this secret to my children? <span class=\"citation\">Meg. 3ᵃ</span>; a. fr.—ג׳ משפחות <i>to expose to suspicion</i> the legitimacy of families. <span class=\"citation\">Tosef. Naz. I, 3</span>; <span class=\"citation\">Kidd. 71ᵃ</span>.—<span dir=\"rtl\">ג׳ פנים בתורה</span> (<span dir=\"rtl\">שלא כהלכה</span>) a) to interpret the Law in opposition to the adopted sense, <i>tomisinterpret, pervert.</i> <span class=\"citation\">Ab. III, 11</span>; a. e. b) <i>to put the Law to shame</i> by treating its teachers irreverently. <span class=\"citation\">Snh. 99ᵃ</span>; a. e.—<span dir=\"rtl\">ג׳ פנים</span> (in gen.) <i>to expose, put to shame</i>. <span class=\"citation\">Pirké d’R. El. ch. XLIV</span>, v. <a href=\"#\" data-headword=\"לָבַן II\"><span dir=\"rtl\">לָבַן</span> II</a>.—<i>Part. pass</i>. <span dir=\"rtl\">מְגוּלֶּה</span>, f. <span dir=\"rtl\">מְגוּלָּה</span> <i>uncovered.</i> <span class=\"citation\">Par. XI, 1</span>; <span class=\"citation\">Ḥull. 9ᵇ</span>; a. fr. Pl. <span dir=\"rtl\">מְגוּלִּין</span>. Ib.; a. fr.</div></div><div class=\"sense\"><b>Nithpa. נִתְגַּלֶּה  נִתְגַּל</b> <div class=\"sense\"><i>to be revealed; to be exposed</i>. <span class=\"citation\">Pirké d’R. El. ch. XXIII</span> <span dir=\"rtl\">ונתגל בתוך האהל</span> his nakedness was exposed &amp;c. <span class=\"citation\">Yoma 9ᵇ</span> <span dir=\"rtl\">נתג׳ עונם</span> their sins were public (they did not hide them); <span dir=\"rtl\">נתג׳ קיצם</span> the end of their captivity was revealed (through prophecy). <span class=\"citation\">Naz. 23ᵇ</span> <span dir=\"rtl\">נ׳ קלונו</span> his disgrace is published.—<span class=\"citation\">Pes. 119ᵃ</span>; a. fr.—Tanḥ. <span class=\"citation\">Mishp. 6</span>; <span class=\"citation\">Yalk. Prov. 956</span>, v. <a href=\"#\" data-headword=\"גָּלַע\">גָּלַע</a>.</div></div>","alt":["גָּלָה"]},"7783":{"h":"גְּלֵי","r":"C00927","html":"<div class=\"sense\"><b>1)</b> <i>to reveal, uncover</i>. <span class=\"citation\">Targ. Num. XXII, 31</span>. <span class=\"citation\">Targ. Am. III, 7</span>; a. fr.—Part. <a href=\"#\" data-headword=\"גָּאלֵי\">גָּאלֵי</a>. <span class=\"citation\">Targ. Prov. XX, 19</span>.</div><div class=\"sense\"><b>—2)</b> <i>to go into exile, go away, disappear</i>. <span class=\"citation\">Targ. Hos. X, 5</span>.—<span class=\"citation\">Ib. XI, 11</span> <span dir=\"rtl\">דִּיגְלוֹ</span> those who were exiled. <span class=\"citation\">Targ. Am. V, 5</span> <span dir=\"rtl\">מִיגְלָא יִגְלוּן</span> (some ed. <span dir=\"rtl\">ילפון</span>, corr. acc.); a. fr.—<span class=\"citation\">Ber. 56ᵃ</span> אִגְלֵי I will leave home; <span dir=\"rtl\">גלא לבי רומאי</span> he emigrated into Roman territory. <span class=\"citation\">Pes. 49ᵃ</span> לא גְלָאִי I should not have emigrated; <span dir=\"rtl\">לא גלאי כדגָלֵי אינשי</span> I did not emigrate (voluntarily) as others do. <span class=\"citation\">Koh. R. to IX, 10</span> <span dir=\"rtl\">את הוית גָּלֵי וכ׳</span>, v. <a href=\"#\" data-headword=\"אֲלַף II\"><span dir=\"rtl\">אֲלַף</span> II</a>.—Part. <a href=\"#\" data-headword=\"גָּאלֵי\">גָּלֵי</a>, pl. <a href=\"#\" data-headword=\"גַּלְיָא I\">גָּלַיָּא</a>, f. <span dir=\"rtl\">גָּלָן</span> <i>exiles</i>. <span class=\"citation\">Targ. Nah. II, 8</span> <span dir=\"rtl\">בגָלַיָּא</span> ed. among the exiles (on foot; ed. Lag. <span dir=\"rtl\">בגִילַּיָּא</span>, v. <a href=\"#\" data-headword=\"גִּילּוּיָיא\">גִּילּוּיָא</a>, h. text <span dir=\"rtl\">גֻּלְּתָה</span>). <span class=\"citation\">Targ. Am. VI, 7</span> <span dir=\"rtl\">גָּלָן</span> the exiled communities.—<span class=\"citation\">Targ. II Kings XXIII, 6</span> <span dir=\"rtl\">קברי ג׳</span> (some ed. <a href=\"#\" data-headword=\"גִּילּוּיָיא\">גַּלּ׳</a>) the graves of the homeless (h. text <span dir=\"rtl\">בני העם</span>).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"גֱּלֵי\">גֱּלֵי</a>, <a href=\"#\" data-headword=\"גֱּלֵי\">גֲּלִי</a>, <a href=\"#\" data-headword=\"ג׳\">גְּ׳</a>, <a href=\"#\" data-headword=\"גֱּלֵי\">גַּלְיָא</a> <i>known, revealed; uncovered.</i> <span class=\"citation\">Dan. II, 19</span>; <span class=\"citation\">30</span>. <span class=\"citation\">Targ. Job XXIII, 10</span>. <span class=\"citation\">Targ. I Sam. III, 1</span>; a. fr.—<span class=\"citation\">Targ. O. Ex. XIV, 8</span> <span dir=\"rtl\">בריש ג׳</span> openly (h. text <span dir=\"rtl\">ביד רמה</span>).</div><div class=\"sense\"><b>Pa. גַּלֵּי</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"גלי\">preced.</a> Pi.—<span class=\"citation\">Targ. Lev. XVIII, 6</span> sq.; a. fr. <span class=\"citation\">Gitt. 31ᵇ</span> <span dir=\"rtl\">ג׳ לדרעיה</span> he uncovered his arm. <span class=\"citation\">Ab. Zar. 28ᵃ</span>; <span class=\"citation\">Yoma 84ᵃ</span> <span dir=\"rtl\">דלא מְגַלִּית</span> that thou wilt not divulge it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מְגַלִּינָא</span> I shall divulge. <span class=\"citation\">Ḥull. 113ᵃ</span> <span dir=\"rtl\">תנא סיפא לגַלּוּיֵי רישא</span> the second clause is stated in order to throw light on the first. <span class=\"citation\">Gitt. 34ᵃ</span> <span dir=\"rtl\">גַּלּוּיֵי דעתא</span>, v. <a href=\"#\" data-headword=\"גִּילּוּיָיא\">גִּילּוּיָּא</a>. Y. Maasr. V, end, 52ᵃ <span dir=\"rtl\">מן דגַלִּית לך חספא אשכחת מרגניתא</span> (not <span dir=\"rtl\">דגליית</span>) after I removed the potsherd, thou foundest the pearl, i.e. but for my teaching, you would not have found the truth which you now claim as your own discovery; Y. Keth. IX, 33ᵇ bot. (corr. acc.); [in Babli <span dir=\"rtl\">דלאית</span>, v. <a href=\"#\" data-headword=\"דלי\">דלי</a>].</div></div><div class=\"sense\"><b>Af. אַגְלֵי</b> <div class=\"sense\"><i>to banish</i>. <span class=\"citation\">Targ. II Kings XV, 29</span>; a. fr.—<span class=\"citation\">Snh. 94ᵃ</span>. [הַגְלִי <span class=\"citation\">Ezra IV, 10</span>; a. e.]</div></div><div class=\"sense\"><b>Ithpe. אִיתְגְּלֵי  אִיגְּלֵי</b> <div class=\"sense\"><b>1)</b> <i>to be uncovered, revealed</i> &amp;c. <span class=\"citation\">Targ. Is. LXII, 1</span>. <span class=\"citation\">Ib. LI, 9</span> <a href=\"#\" data-headword=\"גְּלֵי\">אִיתְגְּלָא</a> reveal thyself (h. text <span dir=\"rtl\">עורי</span>). <span class=\"citation\">Targ. II Sam. VI, 20</span> <span dir=\"rtl\">דא׳</span> who exposed himself; a. fr.—<span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">אִיגְּלָאִי מלתא</span> the fact became known. <span class=\"citation\">R. Hash. 22ᵇ</span>, a. fr. <span dir=\"rtl\">כל מילתא דעבידא לאִיגְּלוּיֵי וכ׳</span> people are not presumed to tell a lie which is likely to be found out. <span class=\"citation\">Sot. 22ᵇ</span> <span dir=\"rtl\">מאי דמִגַּלְּיָא מגליא</span> what is visible is visible, i.e. man judges only by what he can ascertain, opp. <a href=\"#\" data-headword=\"מַטְמְרָא\">מטמרא</a>.—<span class=\"citation\">R. Hash. 21ᵇ</span> whence do we know that <i>alil</i> <span dir=\"rtl\">לישנא דמִיגְּלֵי הוא</span> has the meaning of being clearly visible? <span class=\"citation\">Ab. Zar. 30ᵃ</span> <span dir=\"rtl\">איגלי ליה חמרא</span> his wine was found uncovered. <span class=\"citation\">Bets. 3ᵃ</span> <span dir=\"rtl\">מִגְּלוּ וקיימי</span> remain visible; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be led into captivity</i>. <span class=\"citation\">Targ. Jer. XL, 1</span>.</div></div>","alt":["גְּלָא","גָּלָא"]},"7784":{"h":"גְּלַי","r":"C00928","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גלי\">גלי</a>, cmp. <a href=\"#\" data-headword=\"גִּילְהֵי\">גִּילְהֵי</a>) <i>flash</i>. <span dir=\"rtl\">בִּגְ׳</span> <i>as a flash, suddenly, rapidly</i>. <span class=\"citation\">Targ. Is. XLI, 2</span>; <span class=\"citation\">25</span>; <span class=\"citation\">Targ. Hos. XI, 11</span>.</div>","alt":["גְּלַאי"]},"7785":{"h":"*גַּלִּי","r":"C00929","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. γάλιον) <i>galium, bed-straw</i>, an odoriferous plant. <span class=\"citation\">Targ. Y. Num. XXI, 12</span> [read:] <span dir=\"rtl\">דמרבי חילפי וג׳</span>.</div>","alt":[]},"7786":{"h":"גֱּלֵי","r":"C00930","html":"<div class=\"sense\">, part. pass. of <a href=\"#\" data-headword=\"גְּלָא\">גְּלָא</a>.—Pl. fem. <a href=\"#\" data-headword=\"*גָּבְיָין\">גַּלְיָין</a>. <span class=\"citation\">Targ. Prov. XXXI, 27</span> (ed. Lag. <span dir=\"rtl\">גלין</span>).</div>","alt":["גֲּלִי","גְּלִי","גַּלְיָא"]},"7787":{"h":"גַּלְיָא I","r":"C00931","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (Gallia) </div><div class=\"sense\"><b>1)</b> <i>Gaul, country of the Gauls</i> in Europe. <span class=\"citation\">Yeb. 63ᵃ</span> ships going <span dir=\"rtl\">מג׳ לאספמיא</span> from Gaul to Spain.</div><div class=\"sense\"><b>—2)</b> <i>Gallia </i>or<i> Galatia</i> in Asia Minor. <span class=\"citation\">R. Hash. 26ᵃ</span>. <span class=\"citation\">Keth. 60ᵃ</span> Naḥum <span dir=\"rtl\">איש ג׳</span> the Galatian.</div>","alt":[]},"7788":{"h":"*גַּלְיָא II","r":"C00932","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גלי\">גלי</a>) <i>revelation</i>. <span dir=\"rtl\">בית ג׳</span> <i>a place or temple for oracles</i>. <span class=\"citation\">Ab. Zar. 46ᵃ</span> <span dir=\"rtl\">היו קורין אותה בית ג׳ קורין אותה בית כריא</span> when they (the idolators) call a place <i>Beth-Galia</i>, Israelites should call it <i>Beth-Kharia</i>, v. <a href=\"#\" data-headword=\"כַּרְיָא I\">כַּרְיָא</a>; <span class=\"citation\">Tem. 28ᵇ</span>.—<span class=\"citation\">Meg. 6ᵃ</span> (ref. to <span class=\"citation\">Zech. IX, 7</span>) <span dir=\"rtl\">זה בית ג׳ שלהן</span> that means their temple. V., however, <a href=\"#\" data-headword=\"גָּד ³\">גַּדָּא</a> a. <a href=\"#\" data-headword=\"גַּלָּא\">גַּלָּא</a>.</div>","alt":[]},"7789":{"h":"גַּלַּיָּא","r":"C00933","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּלָּא\">גַּלָּא</a> a. <a href=\"#\" data-headword=\"*גַּלְיָא II\">preced.</a></div>","alt":[]},"7790":{"h":"גָּלַיָּא","r":"C00934","html":"<div class=\"sense\"><i>exiles</i>, v. <a href=\"#\" data-headword=\"גְּלֵי\">גְּלֵי</a>.</div>","alt":[]},"7791":{"h":"גליאס","r":"C00935","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"*גַּלִּיגָאס\">גַּלִּיגָאס</a>, <span dir=\"rtl\">גַּלִּיגָאסִין</span>.</div>","alt":["גליאסין"]},"7792":{"h":"*גְּלִיבָא","r":"C00936","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גלב</span>) <i>shaved face</i>. <span class=\"citation\">Targ. Is. XV, 2</span> Kimḥi (ed. <span dir=\"rtl\">גילוח</span>).</div>","alt":[]},"7793":{"h":"*גְּלִיבְטוֹן","r":"C00937","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (γλυπτόν) <i>carved</i>. Y’lamd. to Deut. IV, 4 quot. in Ar., expl. <span dir=\"rtl\">פטורי ציצים</span> (<span class=\"citation\">I Kings VI, 18</span>).</div>","alt":[]},"7794":{"h":"*גַּלִּיגָאס","r":"C00938","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (caliga, adopted fr. acc. pl. caligas) <i>nail-studded shoe of the Roman soldier</i>.—Pl. <span dir=\"rtl\">גַּלִּיגָאסִין</span>. <span class=\"citation\">Lam. R. to II, 7</span> [read:] <span dir=\"rtl\">ועשו מסמרות של גליאסין שלהן רושם בארץ</span> and the nails of their shoes left marks in the Temple floor. [Vers. in Ar.: <span dir=\"rtl\">ועושין רושם במסמרות הגלגוסיים בקרקע ביהמ&quot;ק</span>.]</div>","alt":["גַּלִּיגָס"]},"7795":{"h":"גָּלִיד","r":"C00939","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גלד</span>) </div><div class=\"sense\"><b>1)</b> <i>ice-coating</i> on the water. on the water. Ohol. VIII, 5. <span class=\"citation\">Mikv. VII, 1</span>.</div><div class=\"sense\"><b>—2)</b>  v. <a href=\"#\" data-headword=\"גֶּלֶד\">גֶּלֶד</a></div>","alt":[]},"7796":{"h":"גְּלִיד","r":"C00940","html":"<div class=\"sense\">; <i>ice, hoar-frost</i> (h. <a href=\"#\" data-headword=\"כִּפּוּר\">כפור</a>, <a href=\"#\" data-headword=\"קרח\">קרח</a>). <span class=\"citation\">Targ. Ps. CXLVII, 16</span>. <span class=\"citation\">Targ. O. Gen. XXXI, 40</span> (Y. <a href=\"#\" data-headword=\"קְרוּשָׁא\">קרושא</a>).</div>","alt":["גְּלִידָא"]},"7797":{"h":"גִּלָּיוֹן","r":"C00941","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>blank parchment, margin of scrolls.</i> <span class=\"citation\">Yad. III, 4</span> <span dir=\"rtl\">ג׳ … שמלמעלן וכ׳</span> the blank portions of a sacred book, the upper, the lower margins and those at the beginning and the end; <span class=\"citation\">Sabb. 116ᵃ</span> Ms. M. (ed. pl.). <span class=\"citation\">Men. 30ᵃ</span>.—Pl. <span dir=\"rtl\">גִּלְיוֹנִין</span>, <a href=\"#\" data-headword=\"גִּלְגּוּל\">גִּילְ׳</a>. Sabb. l. c., v. supra. Ib. <span dir=\"rtl\">הג׳ של ס&quot;ת</span> (Ms. M. sing.) blank parchments of, or intended for, a sacred book.</div><div class=\"sense\"><b>—2)</b>  (a satirical adaptation of ἐυαγγέλιον, v. <a href=\"#\" data-headword=\"אָיַן\">אָיֶן</a>) <i>gospel</i>. <span class=\"citation\">Tosef. Sabb. XIII</span> (<span class=\"citation\">XIV), 5</span> <span dir=\"rtl\">הג׳ וספרי מינין</span>; Sabb. l. c. <span dir=\"rtl\">הג׳ וספרי הצדוקים</span> (Ms. M. <span dir=\"rtl\">הגליון … מינין</span>) the gospels and books of heretics; [disputants, Sabb. l. c., take our w. in the sense of <i>blanks</i>]. Ib. sq., v. <a href=\"#\" data-headword=\"אָוֶן\">אָוֶן</a>.</div><div class=\"sense\"><b>—3)</b>  (v. <span class=\"citation\">Is. III, 23</span>; cmp. <a href=\"#\" data-headword=\"גִּלְגְּלִין\">גִּלְגְּלִין</a>) <i>a girdle</i> of fine material. <span class=\"citation\">Gen. R. s. 19</span> (Ar. <span dir=\"rtl\">גליונים</span>; ed. Koh. <span dir=\"rtl\">גולין</span>, corr. acc.).</div>","alt":["גִּלְ׳","גִּיל׳"]},"7798":{"h":"גלייה","r":"C00942","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 20</span> <span dir=\"rtl\">יודן ג׳</span>, read <a href=\"#\" data-headword=\"גְּלִילָאָה\">גְּלִילָאָה</a>; cmp. Tanḥ. Aḥaré 3 <span dir=\"rtl\">יודן דמן גלילא</span>.</div>","alt":[]},"7799":{"h":"גַּלְיָיר","r":"C00943","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גּוּלְיָיר\">גּוּלְיָיר</a></div>","alt":[]},"7800":{"h":"גָּלִיל","r":"C00944","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (b. h.) [<i>District</i>,] esp. <i>Galilee</i> in Northern Palestine. <span class=\"citation\">Shebi. IX, 2</span> ג׳ העליון Upper Galilee, <span dir=\"rtl\">ג׳ התחתון</span> Lower Galilee. <span class=\"citation\">Sot. IX, 15</span> (<span class=\"citation\">49ᵇ</span>) <a href=\"#\" data-headword=\"גַּבְלָן\">הַגָּ׳</a>. <span class=\"citation\">Keth. 9ᵇ</span>; a. fr. [<span dir=\"rtl\">ג׳ בגוים</span>, <span class=\"citation\">Snh. 94ᵇ</span>, v. <a href=\"#\" data-headword=\"גְּלִילָה\">גְּלִילָה</a>.]</div>","alt":[]},"7801":{"h":"גָּלִילָא","r":"C00945","html":"<div class=\"sense\"><b>1)</b> <i>district, circuit</i>. <span class=\"citation\">Targ. Ezek. XLVII, 8</span>.—Pl. <a href=\"#\" data-headword=\"גְּלִילִי\">גְּלִילִין</a>, <a href=\"#\" data-headword=\"גְּלִילִי\">גְּלִילֵי</a>. <span class=\"citation\">Targ. Josh. XXII, 10</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>Galilee</i>. Ib. XX, 7; a. e.—<span class=\"citation\">Sabb. 47ᵃ</span>; <span class=\"citation\">78ᵃ</span> <span dir=\"rtl\">בג׳ שנו</span> it refers only to Galilee.—<span class=\"citation\">Tosef. Snh. II, 5</span>; <span class=\"citation\">Y. Maas. Sh. V, 56ᶜ</span> top, a. e. <span dir=\"rtl\">ג׳ עילאה</span> Upper Galilee, <span dir=\"rtl\">ג׳ תיתאה</span> (<a href=\"#\" data-headword=\"אַרְעִיתָא\">ארעיתא</a>) Lower G.; <span class=\"citation\">Snh. 11ᵇ</span> <a href=\"#\" data-headword=\"גְּלִילָאָה\">גלילאה</a> (corr. acc.).—<span class=\"citation\">Erub. 53ᵇ</span> <a href=\"#\" data-headword=\"גִּיּוֹרֵי\">בר ג׳</a> a Galilean.</div>","alt":[]},"7802":{"h":"גְּלִילָא","r":"C00946","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּלוֹלָא\">גָּלוֹלָא</a></div>","alt":["גְּלִילַיָּא"]},"7803":{"h":"גְּלִילָאָה","r":"C00947","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>Galilean</i>. <span class=\"citation\">Erub. 53ᵇ</span> <span dir=\"rtl\">ג׳ שוטה</span> (Ms. M. <span dir=\"rtl\">גלילא</span>) foolish Galilean, v. <a href=\"#\" data-headword=\"אִימַּר\">אִימַּר</a>.—<span class=\"citation\">Snh. 113ᵃ</span> <span dir=\"rtl\">ההוא ג׳</span> a certain Galilean; <span class=\"citation\">Sabb. 88ᵃ</span>. <span class=\"citation\">Ḥull. 27ᵇ</span>; a. e.—Pl. <a href=\"#\" data-headword=\"גְּלִילָא\">גְּלִילָאֵי</a>. <span class=\"citation\">Y. B. Bath. VI, 15ᶜ</span> top.</div>","alt":[]},"7804":{"h":"גְּלִילָה","r":"C00948","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">גלל</span>) <i>casting about, contempt</i>. <span class=\"citation\">Snh. 94ᵇ</span> (play on <span dir=\"rtl\">גליל הגוים</span>, <span class=\"citation\">Is. VIII, 23</span>) <span dir=\"rtl\">אני עוש׳ אותו ג׳ בגוים</span> Ms. M. (ed. <span dir=\"rtl\">אעשה לו גליל</span>) I will make him (Sennaherib) contemptible among the nations; Yalk.Kings 237.</div>","alt":[]},"7805":{"h":"גְּלִילִי","r":"C00949","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּלִיל\">גָּלִיל</a>) <i>Galilean.</i> <span class=\"citation\">Yad. IV, 8</span> צדוקי ג׳ Mish. ed. (Talm. ed. only <span dir=\"rtl\">צדוקי</span>) a Galilean Sadducee (heretic).—ר׳ יוסי הג׳ R. José the Galilean. <span class=\"citation\">Pes. 28ᵃ</span>; a. v. fr., v. <a href=\"#\" data-headword=\"יוֹסֵי\">יוֹסֵי</a>.—*Pl. <a href=\"#\" data-headword=\"גְּלִילִי\">גְּלִילִים</a>, <a href=\"#\" data-headword=\"גְּלִילִי\">גְּלִילִין</a>. <span class=\"citation\">Kel. II, 2</span> הפכים הג׳ Galilean flasks; <span class=\"citation\">Tosef. Kel. B. Kam. II, 2</span> <span dir=\"rtl\">הפכין והג׳</span> (read <span dir=\"rtl\">הפכין הג׳</span>); <span class=\"citation\">ib. 9</span>. [Cmp., however, <a href=\"#\" data-headword=\"גָּלָל\">גָּלָל</a>.]</div>","alt":[]},"7806":{"h":"גְּלִילְתָּא","r":"C00950","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גִּלָּה\">גִּלָּה</a>) <i>folding</i>. <span class=\"citation\">Sabb. 47ᵇ</span> מטה גליל׳ Ms. M. (ed. <span dir=\"rtl\">גללני׳</span>, Ar. <span dir=\"rtl\">גיליתא</span>) <i>folding couch, cot</i></div>","alt":["גְּלַלְנִיתָא"]},"7807":{"h":"גְּלִים","r":"C00951","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (גְלַם 1) <i>wrapper, cloak</i>. <span class=\"citation\">Targ. O. Gen. XXV, 25</span> ed. <span dir=\"rtl\">כִּגְלִים</span> (ed. Berl. <a href=\"#\" data-headword=\"*כָּכְלַן\">כָּכְלָן</a>, v. <a href=\"#\" data-headword=\"כִּילַן\">כִּילַן</a>, Var. <span dir=\"rtl\">כִּגְלָם</span>). Targ. II Esth. VIII, 15.—<span class=\"citation\">Sabb. 77ᵇ</span> it is called <i>g’lima</i>, <span dir=\"rtl\">שנעשה בו כגוֹלֶם</span> ed. (Ms. M. <span dir=\"rtl\">שנעשית כגו׳</span>) because one looks in it like a shapeless (armless) body (Ms. M. it is rolled up like a lump). <span class=\"citation\">Snh. 102ᵇ</span> <span dir=\"rtl\">שיפולי ג׳</span> trail of the cloak; a. fr.—Pl. <span dir=\"rtl\">גְּלִימֵי</span>. <span class=\"citation\">Ib. 110ᵃ</span></div>","alt":["גְּלִימָא I"]},"7808":{"h":"גְּלִימָא II","r":"C00952","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (גְּלַם 2) </div><div class=\"sense\"><b>1)</b> <i>height, hill</i>—Pl. <span dir=\"rtl\">גְּלִימָתָא</span>, <a href=\"#\" data-headword=\"גַּלְמָן\">גַּלְמָתָא</a>. <span class=\"citation\">Targ. Y. I Num. XXIII, 9</span>, <span class=\"citation\">Targ. Y. II, Num. XXIII, 9</span>; <span class=\"citation\">Targ. Y. II, Gen. XLIX, 26</span> <a href=\"#\" data-headword=\"גּוֹלְיְתָא\">גּוֹלַמְתָא</a> (read <a href=\"#\" data-headword=\"גּוֹלְמָא\">גּוֹלְמָ׳</a>). Targ. Y. II ib. 11 sq. <span dir=\"rtl\">גּוֹלְמָתֵיה</span> his hills. <span class=\"citation\">Targ. Ps. LXXII, 3</span> <a href=\"#\" data-headword=\"גַּלְמָא\">גַּלְמָ׳</a>.</div><div class=\"sense\"><b>—2)</b> <i>valley</i>. <span class=\"citation\">Targ. Job XXXIX, 21</span>. <span class=\"citation\">Targ. Josh. XVIII, 28</span> Var. (ed. Lag. I, p. VIII<sup>30</sup> <span dir=\"rtl\">גְּלִימַת</span>).—Pl. <span dir=\"rtl\">גְּלִימָתָא</span>, <a href=\"#\" data-headword=\"גַּלְמָן\">גַּלְמָתָא</a>. <span class=\"citation\">Targ. Job XXXIX, 10</span>. <span class=\"citation\">Targ. Y. Num. XXI, 19</span>.—<span dir=\"rtl\">גְּלִימִין</span>. Pesik. B’shall. p. 93ᵃ <span dir=\"rtl\">ומחית ליה ג׳</span> (Ar. <a href=\"#\" data-headword=\"גַּלְמָן\">גַּלְמָן</a>) and carried him down the valleys.</div>","alt":["גַּלְמָא"]},"7809":{"h":"גַּלֵּינֵי","r":"C00953","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (γαλήνη) <i>calm, stillness of wind and wave</i>. Y. Yeb. XV, 15ᵈ top <span dir=\"rtl\"><span dir=\"rtl\">אם</span> (<a href=\"#\" data-headword=\"הוי\">היה</a>) <span dir=\"rtl\">הים ג׳ וכ׳</span></span> if there was a calm sea, and you looked around and there was none &amp;c.; <span class=\"citation\">Y. Erub. IV, 21ᵈ</span> bot. <a href=\"#\" data-headword=\"גלנו\">גלנו</a> ed. Krot. (corr. acc.).</div>","alt":[]},"7810":{"h":"גְּלִיפָא","r":"C00954","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גְּלִיפָה\">next w.</a>) <i>shaping</i> (of writing), <i>impress, poetry</i>. <span class=\"citation\">Targ. Ps. XVI, 1</span> <span dir=\"rtl\">ג׳ תריצא</span> a well-arranged poetry (h. text <a href=\"#\" data-headword=\"מִכְתָּם\">מכתם</a>). <span class=\"citation\">Ib. CXIX, 130</span> <span dir=\"rtl\">גְּלִיף דבריך</span> the impress of thy words (h. text <a href=\"#\" data-headword=\"פָּתַח\">פֵּתַח</a>).</div>","alt":[]},"7811":{"h":"גְּלִיפָה","r":"C00955","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּלַף\">גָּלַף</a>) <i>shaping, formation</i> (of speech, cmp. <span dir=\"rtl\">גזם</span>, <a href=\"#\" data-headword=\"גּוּזְמָא\">גּוּזְמָא</a>). <span class=\"citation\">Pesik. R. s. 33</span> <span dir=\"rtl\">גְּלִיפַת שפתים</span> eloquence (ref. to <span class=\"citation\">Is. LVII, 19</span>).</div>","alt":[]},"7812":{"h":"גַּלִּיצוּר","r":"C00956","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Gallitsur</i>, name of an angel. <span class=\"citation\">Pesik. R. s. 20</span> (defined <span dir=\"rtl\">מְגַלֶּה טעמי צור</span> revealing the reasons of the Creator); Yalk. R’ubeni, Mishpatim end <span dir=\"rtl\">ג׳ המכונה רזיאל</span> G. surnamed Raziël.</div>","alt":[]},"7813":{"h":"גָּלְיַת","r":"C00957","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (b. h.) <i>Goliath</i>, the Philistine. <span class=\"citation\">Sot. VIII, 1</span> <span dir=\"rtl\">בנצחונו של ג׳</span> relying on the strength of G. <span class=\"citation\">Ib. 42ᵇ</span> <span dir=\"rtl\">ג̇ל̇י̇ת … בג̇יל̇וי̇ פנים וכ׳</span> he is named G., because he stood before the Lord with barefacedness (defiance). <span class=\"citation\">Lev. R. s. 5</span>; a. fr.</div>","alt":["גּוֹלְיַת"]},"7814":{"h":"גלכין","r":"C00958","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גַּלְבִּין\">גַּלְבִּין</a></div>","alt":[]},"7815":{"h":"גָּלַל","r":"C00959","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to roll, unfold, fold</i>. <span class=\"citation\">Meg. 32ᵃ</span> he opens (the scroll), sees the place (to read from), <span dir=\"rtl\">גּוֹלֵל ומברך</span> rolls it up again and says the benediction. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הגּוֹלֵל ס&quot;ת וכ׳</span> he who rolls the scrolls up (preparing the place to read from). <span class=\"citation\">B. Mets. II, 8</span> (<span class=\"citation\">29ᵇ</span>) <span dir=\"rtl\">גוֹלְלָן</span> he must roll the scrolls over (for the purpose of airing); a. fr.</div><div class=\"sense\"><b>—2)</b>  (v. <span class=\"citation\">Gen. XXIX, 3</span>) <i>to roll off</i> (one’s shoulders), <i>disregard</i>. <span class=\"citation\">Gen. R. s. 21</span> (play on <span dir=\"rtl\">גללו</span>, <span class=\"citation\">Job XX, 7</span>) <span dir=\"rtl\">על שג׳ מצוה וכ׳</span> because he disregarded a light command.</div><div class=\"sense\"><b>Nif. נִגְלַל</b> <div class=\"sense\"><i>to be rolled, folded</i>. <span class=\"citation\">Cant. R. to V, 14</span> <span dir=\"rtl\">והיו נִגְלָלִין</span> they could be folded up. <span class=\"citation\">Snh. 68ᵃ</span> my two arms which are like two scrolls of the Law <span dir=\"rtl\">שנגללין</span> rolled up (not unfolded, i.e. with me learning is buried which I was prevented from teaching).—Trnsf., with <span dir=\"rtl\">על</span>, <i>to be rolled on top of, to prevail</i>. <span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">יִגּוֹלּוּ רחמי על וכ׳</span> may my mercy prevail over my attributes (of justice &amp;c.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יגולו רחמיך</span>; v. <a href=\"#\" data-headword=\"גִּלְגֵּל\">גִּלְגֵּל</a>.</div></div><div class=\"sense\"><b>Hof. הוּגְלָל</b> <div class=\"sense\"><i>to be rolled up, folded</i>. <span class=\"citation\">Taan. 21ᵇ</span>; <span class=\"citation\">Men. 95ᵃ</span> <span dir=\"rtl\">הוּגְלְלוּ הפרוכות</span> when the curtains (of the Tabernacle) were folded up (for removing).</div></div>","alt":[]},"7816":{"h":"גְּלַל","r":"C00960","html":"<div class=\"sense\">, <i>to roll, unfold</i>.—Part. pass. <a href=\"#\" data-headword=\"גָּלִיל\">גְּלִיל</a> <i>unfolded, visible</i>. <span class=\"citation\">Targ. Cant. V, 14</span>.</div><div class=\"sense\"><b>Pa. גַּלֵּל</b> <div class=\"sense\"><i>to roll off</i>. <span class=\"citation\">Targ. Y. II, Gen. XXVIII, 10</span> (some ed. <span dir=\"rtl\">לִגְלָלָא</span> Pe.).</div></div><div class=\"sense\"><b>Ithpe. אִתְגְּלַל</b> <div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּלְגֵּל\">גַּלְגֵּל</a>, Ithpalp.</div></div>","alt":[]},"7817":{"h":"גָּלָל","r":"C00961","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"גְּלַל\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>rolling along with, appendage</i>. <span class=\"citation\">Men. 15ᵃ</span>; <span class=\"citation\">Pes. 13ᵇ</span> <span dir=\"rtl\">לחם ג׳ תודה</span> the bread is an appendage of the thank-offering; <span class=\"citation\">Men. 80ᵃ</span> <span dir=\"rtl\">לִגְלַל תודה</span>.—בִּגְלַל <i>in consequence of, on account of</i>, v. <a href=\"#\" data-headword=\"גְּלָל\">next w.</a></div><div class=\"sense\"><b>—2)</b> <i>something rolled, rounded, ball, ordure, excrement, dung</i>. <span class=\"citation\">B. Kam. III, 3</span> <span dir=\"rtl\">ההופך את הג׳</span> he who upturns (throws up) ordure into the street.—Pl. <span dir=\"rtl\">גְּלָלִים</span>, <span dir=\"rtl\">גְּלָלִין</span>. <span class=\"citation\">Sabb. 153ᵇ</span> <span dir=\"rtl\">להטיל ג׳</span> to cast excrements (of animals). <span class=\"citation\">Lev. R. s. 16</span>; <span class=\"citation\">Esth. R. to III, 1</span> <span dir=\"rtl\">מה הג׳ הללו וכ׳</span> as the dung is repulsive.</div><div class=\"sense\"><b>—3)</b>  (with <a href=\"#\" data-headword=\"כְּלֵי\">כְּלֵי</a>) <i>a material used for vessels</i>, supposed to be <i>baked ordure.</i> <span class=\"citation\">Kel. X, 1</span>. <span class=\"citation\">Par. V, 5</span>. <span class=\"citation\">Mikv. IV, 1</span>; <span class=\"citation\">Sabb. 16ᵇ</span>. <span class=\"citation\">Men. 69ᵃ</span>; <span class=\"citation\">69ᵇ</span>; a. fr. [Rashi to Sabb. l. c. expl. <a href=\"#\" data-headword=\"ג׳\">ג׳</a> = <span dir=\"rtl\">שייש</span>, <i>marble</i>, to Men. l. c. = <span dir=\"rtl\">צפיעי בקר</span>.]</div>","alt":["גְּלַל"]},"7818":{"h":"גְּלָל","r":"C00962","html":"<div class=\"sense\"><b>1)</b> <i>untrimmed stone, cobble</i> (v. <a href=\"#\" data-headword=\"גְּוִיל\">גְּוִיל</a>). [<span class=\"citation\">Ezra V, 8</span>.]—<span class=\"citation\">Ḥull. 63ᵃ</span> <span dir=\"rtl\">אתא ג׳</span> a stone fell (from on high); <span class=\"citation\">Yalk. Zech. 578</span> <a href=\"#\" data-headword=\"גְּלָאלָא\">גלאלא</a>. <span class=\"citation\">Gitt. 47ᵃ</span> Ar. (ed. <a href=\"#\" data-headword=\"גַּלְגַּלְתָּא\">גַּלְגַּלְתָּא</a>). <span class=\"citation\">Ab. Zar. 22ᵇ</span>, v. <a href=\"#\" data-headword=\"דַּגָּלָא\">דַּגָּלָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>lump</i>.—Pl. <span dir=\"rtl\">גְּלָלֵי</span>. <span class=\"citation\">Ḥull. 112ᵃ</span> bot. <span dir=\"rtl\">תרי ג׳ דמלחא</span> Rashi (ed. <span dir=\"rtl\">ג׳ מלחא</span>) two lumps of salt.</div><div class=\"sense\"><b>—3)</b> <i>ordure</i>, v. <a href=\"#\" data-headword=\"גַּלָּא\">גַּלָּא</a>.—<i>Pl.</i> as supra. <span class=\"citation\">B. Kam. 92ᵇ</span> (prov.) a dog in his hunger <span dir=\"rtl\">ג׳ מבלע</span> (Ms. H. sing.) will swallow excrements (Rashi: stones).</div><div class=\"sense\"><b>—4)</b> <i>wave</i>, v. <a href=\"#\" data-headword=\"גַּלָּא\">גַּלָּא</a>.</div><div class=\"sense\"><b>—5)</b> <i>consequence;</i> בג׳ <i>on account of, in order to</i>. <span class=\"citation\">Targ. Ps. XL, 12</span> (Ms. <span dir=\"rtl\">ג׳ היכנא</span>). <span class=\"citation\">Targ. II Chr. XXIV, 25</span>; a. e.</div>","alt":["גְּלָלָא"]},"7819":{"h":"גְּלַלְנִיתָא","r":"C00963","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּלָל\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>ball-shaped, lump</i>. <span dir=\"rtl\">מילח׳ ג׳</span> <i>salt in lumps, rock-salt</i>. <span class=\"citation\">Ḥull. 114ᵃ</span>; <span class=\"citation\">Kidd. 62ᵃ</span></div><div class=\"sense\"><b>—2)</b> <i>folding</i>, v. <a href=\"#\" data-headword=\"גְּלִילְתָּא\">גְּלִילְתָּא</a>.</div>","alt":[]},"7820":{"h":"גָּלַם","r":"C00964","html":"<div class=\"sense\"><b>1)</b> <i>to roll up, to unshape</i>. Denom. <a href=\"#\" data-headword=\"גּוֹלֶם\">גּוֹלֶם</a>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"גּוֹלֶם\">גּוֹלֶם</a>) <i>to calculate in a lump, fix an arbitrary price</i>, opp. <span dir=\"rtl\">דקדק</span> to calculate exactly. Sifra B’har, Par. 6, ch. IX; <span class=\"citation\">B. Kam. 113ᵇ</span> <span dir=\"rtl\">יכול יִגְלוֹם עליו</span> you might think, he (the redeemer of the Jewish slave in possession of a gentile) was permitted to force an arbitrary price upon him (the gentile); [Rashi: (גלם <i>to double</i>) he (the gentile owner) might be permitted to ask an exorbitant price].—Part. pass. <a href=\"#\" data-headword=\"גָּלוּם\">גָּלוּם</a>, f. <a href=\"#\" data-headword=\"גָּרוּם\">גְּלוּמָה</a> 1) <i>wrapt up</i>. <span class=\"citation\">Sot. 42ᵃ</span>, v. <a href=\"#\" data-headword=\"גַּלְמוּד\">גַּלְמוּד</a>.—2) <i>roughly shaped, unfinished. </i> Pl. <span dir=\"rtl\">גְּלוּמִים</span>, <span dir=\"rtl\">גְּלוּמוֹת</span>. <span class=\"citation\">Sifré Num. 158</span>, v. <a href=\"#\" data-headword=\"גּוֹלֶם\">גּוֹלֶם</a>. <span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">מצות גלומות</span> rough laws (containing no details, assigning no reasons; Var. lect. <span dir=\"rtl\">גולמות</span>, <span dir=\"rtl\">גּוֹלָמִיּוֹת</span>, fr. <a href=\"#\" data-headword=\"גּוֹלָמִי\">גּוֹלָמִי</a>).</div>","alt":[]},"7821":{"h":"גְּלַם","r":"C00965","html":"<div class=\"sense\"><b>1)</b> <i>to roll, wrap up</i>. Denom. <a href=\"#\" data-headword=\"גְּלִים\">גְּלִים</a>, <a href=\"#\" data-headword=\"גְּלִים\"><span dir=\"rtl\">גְּלִימָא</span> I</a>, <a href=\"#\" data-headword=\"גּוֹלְמָא\">גּוּלְמָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>to arch, cave</i>. Denom. <a href=\"#\" data-headword=\"גְּלִימָא II\"><span dir=\"rtl\">גְּלִימָא</span> II</a>.</div>","alt":[]},"7822":{"h":"גְּלָם","r":"C00966","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלִים\">גְּלִים</a></div>","alt":[]},"7823":{"h":"גֹּלֶם","r":"C00967","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גּוֹל\">גּוֹל׳</a></div>","alt":["גֻּלְמָא"]},"7824":{"h":"גַּלְמָא","r":"C00968","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלִימָא II\"><span dir=\"rtl\">גְּלִימָא</span> II</a></div>","alt":[]},"7825":{"h":"גַּלְמוּד","r":"C00969","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> format., v. Fürst H. Dict. s. v.) <i>like a shapeless, lifeless lump</i>, whence (cmp. <a href=\"#\" data-headword=\"דָּמַם\">דמם</a>) <i>lonely, melancholy</i>. <span class=\"citation\">Sot. 42ᵃ</span> in the sea-towns <span dir=\"rtl\">קורין לנידה ג׳</span> they call the menstruous woman <i>galmudah;</i> <span class=\"citation\">R. Hash. 26ᵃ</span>. <span class=\"citation\">Ib.</span> (phonetic etymol.) <span dir=\"rtl\"><span dir=\"rtl\">גמולה</span> (<a href=\"#\" data-headword=\"דָּא I\">דא</a>) <span dir=\"rtl\">מבעלה</span></span> she is weaned (separated) from her husband; [Ar. ed. Pes. a. Ven. <span dir=\"rtl\">גלומה</span>, which version, however, disagrees with the reference to <span class=\"citation\">Gen. XXI, 8</span> in Ar. s. v.]. <span class=\"citation\">Gen. R. s. 31</span>; s. 34 (ref. to <span class=\"citation\">Job XXX, 3</span>) when there is want in the world &amp;c. <span dir=\"rtl\">ג׳ הוי רואה … כאילו ג׳</span> be lonely; look upon thy wife, as if she were menstruous; <span class=\"citation\">Y. Taan. I, end, 64ᵈ</span> <span dir=\"rtl\">עשה אשתך ג׳</span> make thy wife lonely. [Cmp. <span class=\"citation\">Snh. 22ᵇ</span>, quot. s. v. <a href=\"#\" data-headword=\"גּוֹלֶם\">גּוֹלֶם</a>.]</div>","alt":["גַּלְמוּדָה"]},"7826":{"h":"גַּלְמוּדָא","r":"C00970","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גַּלְמוּד\">preced.</a>) (euphem.) <i>a menstruous woman</i>. <span class=\"citation\">Gen. R. s. 79</span>, end they heard a woman say to her friend <span dir=\"rtl\">ג׳ אנא</span> I am <i>galmuda</i> (for <span dir=\"rtl\">נדה</span>), from which they learned the meaning of <i>galmudah</i> in <span class=\"citation\">Is. XLIX, 21</span> (v. corr. vers. in ‘Rashi’ a. l.).</div>","alt":[]},"7827":{"h":"גַּלְמוּדָה","r":"C00971","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּלְמוּד\">גַּלְמוּד</a></div>","alt":[]},"7828":{"h":"גַּלְמָן","r":"C00972","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלִימָא II\"><span dir=\"rtl\">גְּלִימָא</span> II</a></div>","alt":["גַּלְמָתָא"]},"7829":{"h":"גלנו","r":"C00973","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּלֵּינֵי\">גַּלֵּינֵי</a></div>","alt":[]},"7830":{"h":"גָּלַע","r":"C00974","html":"<div class=\"sense\"><i>to scratch off, rub; lay open</i>.</div><div class=\"sense\"><b>Nif. נִגְלַע</b> <div class=\"sense\"><i>to be opened through rubbing or scratching, to bleed</i>. <span class=\"citation\">Nidd. VIII, 2</span> (<span class=\"citation\">58ᵇ</span>) <span dir=\"rtl\">והיא יכולה להִגָּלֵעַ וכ׳</span> (Bart. <span dir=\"rtl\">להתגלע</span>) and it (the wound) may have been bruised so as to bleed.</div></div><div class=\"sense\"><b>Pi. גִּלֵּע  גִּילֵּ׳</b> <div class=\"sense\"> (with <a href=\"#\" data-headword=\"ב\">ב</a> of person) <i>to detract from, lay bare the ignorance of, attack</i>. Y. Yeb. VIII, end, 9ᵈ <span dir=\"rtl\">משום שלא לגְרוֹעַ בו וכ׳</span> (did they send him off) in order not to see him exposed, or because he was not fit (to argue)? What is the difference? היה דרכו לגַלֵּע א&quot;ת משום שלא לגלע בו וכ׳ It was his (Rabbi’s) habit to begin with vehement argument; now, if you were to say, ‘in order not to see him exposed’, his exposure was in his own hand (he being the attacking part) &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מה היה לו לגַ׳ בו</span> what could he have attacked (on that subject of <i>androgynos</i>)?</div></div><div class=\"sense\"><b>Hithpa. הִתְגַּלֵּעַ</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִתְגַּלֵּעַ</span> </div><div class=\"sense\"><b>1)</b> <i>to be scratched open</i>, v. supra. </div><div class=\"sense\"><b>2)</b> <i>to be laid bare, be argued</i>. <span class=\"citation\">Snh. 6ᵇ</span>; Y. ib. I, 18ᵇ (ref. to <span class=\"citation\">Prov. XVII, 14</span>) <span dir=\"rtl\">(<span dir=\"rtl\">עד שלא נתג׳</span>) <span dir=\"rtl\">קודם שנתג׳ הריב נטוש</span></span> before the case of litigation has been laid open (fully argued), you (the judge) may compromise it &amp;c.; Tanḥ. <span class=\"citation\">Mishp. 6</span>; <span class=\"citation\">Yalk. Prov. 956</span> <a href=\"#\" data-headword=\"גלי\">נִתְגַּלֶּה</a>, <span dir=\"rtl\">יִתְגַּלֶּה</span>).</div></div>","alt":[]},"7831":{"h":"גִּלְעָד","r":"C00975","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּלַשׁ\">גָּלַשׁ</a></div>","alt":["גַּלְעֵד"]},"7832":{"h":"גַּלְעִין","r":"C00976","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּרְעִין\">גַּרְעִין</a>, <a href=\"#\" data-headword=\"גַּרְעִינָה\"><a href=\"#\" data-headword=\"גַּרְעִינָה\">גַּרְעִינָה</a>.</a></div>","alt":["גַּלְעִינָה"]},"7833":{"h":"גָּלַף","r":"C00977","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">גלב</span>) <i>to dig out, engrave; to shape, form</i>. <span class=\"citation\">Gen. R. s. 47</span>; s. 53; s. 63 <span dir=\"rtl\">ג׳ לה הקב&quot;ה וכ׳</span> the Lord shaped a womb for her.—Part. pass. <span dir=\"rtl\">גָּלוּף</span> <i>engraven</i>. Tanḥ. Balak 14.—<i>Pi.</i> <a href=\"#\" data-headword=\"גָּלַף\">גִּלֵּף</a> same. Pesik. Ăniya, p. 137ᵃ <span dir=\"rtl\">מְגַלְּפִין בו</span> shaping it; <span class=\"citation\">Pesik. R. s. 32</span> <span dir=\"rtl\">מפליגים</span> (corr. acc.).</div>","alt":[]},"7834":{"h":"גְּלַף I","r":"C00978","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Kings VII, 36</span>. <span class=\"citation\">Targ. Ex. XXVIII, 9</span>; a. e.—Part. pass. <span dir=\"rtl\">גְּלִיף</span>. <span class=\"citation\">Targ. Y. ib. 11</span>; a. e.—Pl. <a href=\"#\" data-headword=\"גְּלִיפָא\">גְּלִיפָן</a>, <a href=\"#\" data-headword=\"גְּלִיפָא\">גְּלִיפַן</a>. <span class=\"citation\">Targ. Ex. XXXIX, 6</span>; a. e.</div>","alt":[]},"7835":{"h":"גְּלַף II","r":"C00979","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּלַף I\">preced.</a>) <i>engraving, setting</i>. <span class=\"citation\">Targ. Ex. XXVIII, 11</span>. <span class=\"citation\">Targ. Hag. II, 23</span>; a. e.</div>","alt":["גְּלוֹף"]},"7836":{"h":"גְּלָפִיתָא","r":"C00980","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"אַגְלָפוּתָא\">אגְלָפוּתָא</a>. <span class=\"citation\">Targ. Y. II, Ex. XXXV, 33</span>.</div>","alt":[]},"7837":{"h":"גַּלְפָּטְרָה","r":"C00981","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>Cleopatra</i>, queen of Egypt. <span class=\"citation\">Tosef. Nidd. IV, 17</span> ed. Zuck., v. <a href=\"#\" data-headword=\"קְלִיאוֹפַטְרָא\">קְלִיאוֹפַּטְרָא</a>.</div>","alt":[]},"7838":{"h":"גלקטינון","r":"C00982","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּלְאַקְסִינוֹן\">גַּלְאַקְסִינוֹן</a></div>","alt":[]},"7839":{"h":"גְּלקְטִיקָא","r":"C00983","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\">גְּלוּגְדְּקָא</a></div>","alt":[]},"7840":{"h":"גָּלַשׁ","r":"C00984","html":"<div class=\"sense\"><b>1)</b> <i>to come in sight, to come forth</i>. <span class=\"citation\">Cant. R. to IV, 1</span> (ref. to <span dir=\"rtl\">שגלשו מהר וכ׳</span> ib.) <span dir=\"rtl\">הר שגלשתן מתוכה עשיתיו גלעד לאו&quot;ה</span> (not … <a href=\"#\" data-headword=\"תֵּי\">תי</a>) the mountain (of trouble) out of which ye came in sight again (ye escaped), I (the Lord) made it a hill of witness (a warning) to the nations; <span dir=\"rtl\">אי זה זה ים סוף</span> what is this? It is the Red Sea [which R. Joshua … translated into Chaldean: <span dir=\"rtl\">טורא דאתנהרתון מן גווה</span>]; ib. to IV, 4 הר שג׳ … הר סיני I made your escape memorable to the nations, it is Mount Sinai (by the giving of the Law); ib. repeatedly (referring to various escapes from dangers).</div><div class=\"sense\"><b>Hif. הִגְלִישׁ</b> <div class=\"sense\"><i>to bring to light, to publish</i>. Ib. to IV, 1 <span dir=\"rtl\">ומה הגלשה הִגְלַשְׁתִּי וכ׳</span> (Ar. ed. Koh. <a href=\"#\" data-headword=\"גְּלָשָׁה\">גלשה</a>) and what publication (institution or law) have I (the Lord) brought to light out of that event?</div></div><div class=\"sense\"><b>*. הוּגְלָשׁ</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"*גֶּלֶשׁ\">גֶּלֶשׁ</a> <i>baldness</i>) <i>to be made hot enough for scalding the hair or feathers of an animal’s skin</i>. Part. <span dir=\"rtl\">מוּגְלָשׁ</span>, pl. <span dir=\"rtl\">מוּגְלָשִׁין</span> <i>seething water</i>. <span class=\"citation\">Pes. 37ᵇ</span> (Rabad to <span class=\"citation\">Eduy. V, 2</span> quotes a version <span dir=\"rtl\">מַגְלוֹשִׁין</span> <i>scalding water</i>, Ar. <span dir=\"rtl\">מֵי גְלָשִׁים</span>, fr. <a href=\"#\" data-headword=\"*גֶּלֶשׁ\">גֶּלֶשׁ</a>; Y. Ḥall. I, 58ᵃ top <a href=\"#\" data-headword=\"חַמִּין\">חַמִּין</a>).</div></div>","alt":[]},"7841":{"h":"גְּלַשׁ","r":"C00985","html":"<div class=\"sense\">; <i>to shine, be bald;</i> v. <a href=\"#\" data-headword=\"גְּלוֹשׁ\">גְּלוֹשׁ</a>, <a href=\"#\" data-headword=\"גְּלוֹשׁוּתָא\">גְּלוֹשׁוּתָא</a> &amp;c.—Part. pass. <span dir=\"rtl\">גְּלִישׁ</span> = h. <span dir=\"rtl\">מוּגְלָשׁ</span> (v. <a href=\"#\" data-headword=\"גָּלַשׁ\">preced.</a>) <i>brought to scalding heat, boiling over</i>. <span class=\"citation\">Koh. R. to VIII, 9</span>, v. <a href=\"#\" data-headword=\"גִּיסָא III\"><span dir=\"rtl\">גִּיסָא</span> III</a>.</div>","alt":[]},"7842":{"h":"*גֶּלֶשׁ","r":"C00986","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּלַשׁ\">preced.</a>) <i>baldness.</i> Pl. <span dir=\"rtl\">גְּלָשִׁים</span>. <span dir=\"rtl\">מֵי גְ׳</span> <i>scalding water</i>, v. <a href=\"#\" data-headword=\"גָּלַשׁ\">גָּלַשׁ</a> Hof.</div>","alt":[]},"7843":{"h":"*גַּלְשָׁא","r":"C00987","html":"<div class=\"sense\"><i>bright</i> or <i>bald lines</i>. <span class=\"citation\">Cant. R. to IV, 1</span> (a gloss to <span dir=\"rtl\">גלש</span>) a woman whose hair is thick <span dir=\"rtl\">עבדא לה ג׳ ג׳</span> parts it so as to show white lines; <span dir=\"rtl\">הדא מוצינא כההוא לפי טבאות הוא עבד ג׳ ג׳</span> (prob. to be read … <span dir=\"rtl\">בוצינא כד הוא</span>) a young pumpkin, when it sprouts nicely, produces bright stripes.</div>","alt":["גַּלְשִׁין"]},"7844":{"h":"גְּלָשָׁה","r":"C00988","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַגְלָשָׁה\">הַגְלָשָׁה</a></div>","alt":[]},"7845":{"h":"גַּלְשׁוּשִׁיתָא","r":"C00989","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">גלש</span>) <i>public monument</i>. <span class=\"citation\">Targ. Cant. to IV, 1</span> (v. Cant. R. to ib. s. v. <a href=\"#\" data-headword=\"גָּלַשׁ\">גָּלַשׁ</a>). [Ar. reads <a href=\"#\" data-headword=\"גַּבְשׁוּשִׁיתָא\">גבשושיתא</a>, but the phonetic interpretation refers to <span dir=\"rtl\">שגלשו</span> of the Hebrew text.]</div>","alt":[]},"7846":{"h":"גִּלְשְׁלוּשְׁתָּא","r":"C00990","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"גְּלוֹשׁוּתָא\">גְּלוֹשׁוּתָא</a>. <span class=\"citation\">Targ. Y. Lev. XIII, 42</span> sq.</div>","alt":["גִּלְשְׁלָשׁוּתָא","גִּלְשׁוּלֶשְׁתָּא","גִּילְ׳"]},"7847":{"h":"גִּלְשַׁלְשַׁן","r":"C00991","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"גְּלוֹשׁ\">גְּלוֹשׁ</a>. <span class=\"citation\">Targ. Y. Lev. XIII, 41</span>.</div>","alt":[]},"7848":{"h":"גֹּלְתָא","r":"C00992","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גֹּולְתָא\">גּוֹלְתָא</a></div>","alt":[]},"7849":{"h":"גַּם I","r":"C00993","html":"<div class=\"sense\"> [<i>junction</i>,] </div><div class=\"sense\"><b>1)</b> <i>too, also</i>. <span class=\"citation\">Snh. 108ᵇ</span>; <span class=\"citation\">Taan. 21ᵃ</span> <span dir=\"rtl\">ג׳ זו לטובה</span> this, too, is for the best. <span dir=\"rtl\">איש גם זו</span>, v. <a href=\"#\" data-headword=\"גִּמְזוֹ\">גִּמְזוֹ</a>.</div><div class=\"sense\"><b>—2)</b> <i>the particle gam</i> in the Bible text. <span class=\"citation\">B. Kam. 94ᵃ</span> ג׳ לב&quot;ה קשיא <i>the gam</i> (<span class=\"citation\">Deut. XXIII, 19</span>) is unaccounted for according to Beth Hillel’s opinion; <span class=\"citation\">Tem. 30ᵇ</span>. <span class=\"citation\">Esth. R. to I, 9</span> (ref. to <a href=\"#\" data-headword=\"גַּם I\">גם</a> ib.) <span dir=\"rtl\">אין ג׳ אלא ריבוי</span> <i>gam</i> intimates an amplification, a. e.—Pl. <span dir=\"rtl\">גַּמִּים</span>, <span dir=\"rtl\">גַּמִּין</span> <span class=\"citation\">Gen. R. s. 1</span>; <span class=\"citation\">Y. Ber. IX, 14ᵇ</span> bot. <span dir=\"rtl\">אתין וג׳ ריבויין</span> the <i>eths</i> and the <i>gams</i> intimate an extended qualification (by implication), v. <a href=\"#\" data-headword=\"אֵת\">אֵת</a>.</div>","alt":[]},"7850":{"h":"גַּם II","r":"C00994","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גַּם I\">preced.</a>) <i>joint, angle</i>, esp. <i>two sides of a rectangle</i>. <span class=\"citation\">Erub. 55ᵃ</span> כמין גם Ar. (ed. <span dir=\"rtl\">גאם</span>) in the shape of a right angle. <span class=\"citation\">Zeb. 53ᵇ</span> <a href=\"#\" data-headword=\"גַּם II\">גמא</a> (<span class=\"citation\">Yalk. Lev. 441</span> <span dir=\"rtl\">גאם</span>). <span class=\"citation\">Pes. 8ᵇ</span> <span dir=\"rtl\">שורה אחת כמין ג׳</span> one row of wine vessels, in the shape of &amp;c., i.e. the front and the whole upper layer. Y. ib. I, 27ᵇ bot. <span dir=\"rtl\">קולפו כמין גם</span>.—<span class=\"citation\">Kel. XIV, 8</span> <span dir=\"rtl\">(<span dir=\"rtl\">מפתח</span>) <span dir=\"rtl\">של גם שנשבר מתוך גומו</span></span> a key whose bit is joined (opp. to <span dir=\"rtl\">של ארכובה</span> of one piece) broken at its junction. [<span class=\"citation\">Sabb. 105ᵃ</span> על הגם Ar., ed. <span dir=\"rtl\">על הגַּס</span>, q. v.]—Pl. <span dir=\"rtl\">גַּמִּים</span>, <span dir=\"rtl\">גַּמִּין</span>. Y. Pes. l. c. <span dir=\"rtl\">קולפו כמין שני ג׳</span> he takes off for examination two front and two upper layers, v. supra. Ib. if the vessels are arranged like steps <span dir=\"rtl\">קולפו ג׳ ג׳</span> he must examine by front and upper layers on each landing. <span class=\"citation\">B. Mets. 28ᵃ</span> <span dir=\"rtl\">מדת גַּמָּיו</span> the combined measure of both dimensions of a piece of goods, square measure, opp. <span dir=\"rtl\">מדת ארכו ומדת רחבו</span> the measure of each dimension specified.—<span class=\"citation\">Sabb. 103ᵇ</span> <span dir=\"rtl\">גַּמִּין</span>, v. <span dir=\"rtl\">גי&quot;מל</span>.—[Commentators explain our w. = <i>Greek Gamma</i>, Γ, whence the Var. <a href=\"#\" data-headword=\"גַּמָּא\">גַּמָּא</a>.]</div>","alt":["גַּאַם","(גמא)"]},"7851":{"h":"גַּמָּא","r":"C00995","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Γάμμα) </div><div class=\"sense\"><b>1)</b> <i>Gamma</i>, the third letter of the Greek alphabet. <span class=\"citation\">Shek. III, 2</span> אלפא ביתא ג׳ Ms. O. (ed. <a href=\"#\" data-headword=\"גמלא\">גמלא</a>).</div><div class=\"sense\"><b>—2)</b> <i>the shape of a Gamma</i>, Γ, v. <a href=\"#\" data-headword=\"גַּם II\">preced.</a></div>","alt":[]},"7852":{"h":"גָּמָא","r":"C00996","html":"<div class=\"sense\"> (b. h.), <a href=\"#\" data-headword=\"גָּמָה\">גָּמָה</a>, <a href=\"#\" data-headword=\"גָּמַע\">גָּמַע</a> <i>to take a draught, quaff; to sip, suck up</i>. Y. Maas. Sh. II, beg. 53ᵇ he melted fat <span dir=\"rtl\">וגְמָעוֹ</span> and sipped it; <span class=\"citation\">Y. Yoma VIII, 45ᵃ</span> top <span dir=\"rtl\">וגְמָייוֹ</span>. <span class=\"citation\">Sabb. XIV, 4</span> (<span class=\"citation\">111ᵃ</span>) <span dir=\"rtl\">לא יִגְמָא בהן וכ׳</span> Ar. (ed. <span dir=\"rtl\">יִגְמַע</span>, or <span dir=\"rtl\">יגַמּ׳</span> <i>Pi.</i>, v. infra) he must not quaff vinegar through his teeth. <span class=\"citation\">Y. Maasr. III, 50ᵈ</span> bot. <span dir=\"rtl\">כמה … לִגְמוֹת בכוס</span> how large a portion of the cup one must quaff at a time. Y. Shebi. II, end, 34ᵇ; Y. Ned. VII, beg. 40ᵇ the leaves of the colocasia must not be used (in case of a vow of abstinence from vegetables, or in the Sabbath year) <span dir=\"rtl\">לגמות וכ׳</span> to sip water out of them (v. Sm. Ant. s. v. Colocasia); a. fr.</div><div class=\"sense\"><b>Pi. גִּמֵּא  גִּמֵּעַ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"גַּמָּא\">same</a>. <span class=\"citation\">Sabb. 111ᵃ</span> <span dir=\"rtl\">מְגַמֵּעַ ופולט תנן</span> (Ms. M. <span dir=\"rtl\">לא יִגְמַע ויפלוט</span>) the Mishnah means, he must not quaff and spit out; <span class=\"citation\">Bets. 18ᵇ</span>; Y. Shebi. VIII, 38ᵃ top <span dir=\"rtl\">מְגַמֵּא</span>; a. fr.</div></div>","alt":[]},"7853":{"h":"גְּמָאִין","r":"C00997","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּמָא\">preced.</a>) <i>sweetmeats, delicacies</i>. <span class=\"citation\">Esth. R. to I, 9</span> (play on <a href=\"#\" data-headword=\"גַּם I\">גם</a> ib.) <span dir=\"rtl\">מיני ג׳</span> various delicacies.</div>","alt":[]},"7854":{"h":"גִּמְגֵּם","r":"C00998","html":"<div class=\"sense\"> (Pilp. of <span dir=\"rtl\">גמם</span>) [<i>to peel, scrape;</i> trnsf., cmp. <a href=\"#\" data-headword=\"חָסַם II\"><span dir=\"rtl\">חֲסַם</span> II</a>, <a href=\"#\" data-headword=\"חָכַךְ I\">חָכַךְ</a>] <i>to hesitate, stammer, to speak with an expression of uncertainty</i> or <i>of scruple</i>. <span class=\"citation\">Kidd. 30ᵃ</span> <span dir=\"rtl\">אל תְּגַמְגֵּם ותאמר לו</span> that thou need not hesitate in answering him; <span class=\"citation\">Sifré Deut. 34</span>. <span class=\"citation\">Ber. 22ᵃ</span> <span dir=\"rtl\">היה מְגַמְגֵּם למעלה וכ׳</span> (Ms. M. a. Rashi <span dir=\"rtl\">מג׳ וקורא</span>) was speaking hesitatingly over (as the Amora of) R. Judah &amp;c. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">מג׳ וקורא</span> he should read in a hesitating manner (rapidly murmuring); Y. ib. III, 6ᶜ bot. <span dir=\"rtl\">התחיל מג׳ בה</span> he commenced stammering over it (hesitating to pronounce the Divine Name). [<span class=\"citation\">Cant. R. to VII, 1</span> <span dir=\"rtl\">מתגמגם</span>, transpos. of <span dir=\"rtl\">מתמגמג</span>, v. <a href=\"#\" data-headword=\"מָגַג\">מָגַג</a>.]</div>","alt":[]},"7855":{"h":"גַּמְגֵּם","r":"C00999","html":"<div class=\"sense\"> <span class=\"citation\">Ḥag. 15ᵇ</span> <span dir=\"rtl\">מְגַמְגֵּם בלישניה</span> a stotterer (Ar. <span dir=\"rtl\">מלגס</span>). <span class=\"citation\">Meg. 31ᵇ</span> <span dir=\"rtl\">קא מג׳ וכ׳</span> (v. Rabb. D. S. a. l. Var. Lect.) read the curses (v. <a href=\"#\" data-headword=\"אֲרַר\">אֲרַר</a>) rapidly murmuring; <span class=\"citation\">Koh. R. to VIII, 3</span>.</div>","alt":[]},"7856":{"h":"גֹּמֶד","r":"C01000","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גּוֹמֶד\">גּוֹמֶד</a></div>","alt":[]},"7857":{"h":"גָּמַד","r":"C01001","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גְּמַד\">next w.</a>) <i>to contract</i>. <span dir=\"rtl\">אמה גְמוּדָה</span> a reduced cubit, v. <a href=\"#\" data-headword=\"גָּדַם\">גָּדם</a>.—<i>Pi.</i> <span dir=\"rtl\">גִּמֵּד</span>, v. <a href=\"#\" data-headword=\"גּוֹמֶד\">גּוֹמֶד</a>.</div>","alt":[]},"7858":{"h":"גְּמַד","r":"C01002","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">קמט</span>, <span dir=\"rtl\">קמץ</span>) <i>to contract, shrink, be tight</i>. <span class=\"citation\">Pes. 111ᵃ</span> <span dir=\"rtl\">גְּמוּד מסאניה</span> (Ms. M. <span dir=\"rtl\">גמד</span>) his shoes shrank (became too tight). <span class=\"citation\">Ḥull. 43ᵃ</span> <span dir=\"rtl\">גמדא ליה</span> (the gullet) contracts. <span class=\"citation\">Gitt. 57ᵃ</span> <a href=\"#\" data-headword=\"גַּמְדָּא I\">גמדא</a> the land shrinks, opp. <span dir=\"rtl\">רווחא</span>. <span class=\"citation\">Yoma 69ᵃ</span>; <span class=\"citation\">Bets. 15ᵃ</span> <span dir=\"rtl\">האי נמטא גמדא דנרש וכ׳</span> the shrunk (hard) mattress of Narash (which does not warm) is permitted (does not come under the law of <a href=\"#\" data-headword=\"כִּלְאַיִם\">כִּלְאַיִם</a>).—Part. pass. <a href=\"#\" data-headword=\"גְּמִיד\">גְּמִיד</a> <i>contracted, atrophied</i>. <span class=\"citation\">Targ. Jud. III, 15</span>; <span class=\"citation\">XX, 16</span> (h. text <a href=\"#\" data-headword=\"אִטֵּר\">אִטֵּר</a> q. v.).</div>","alt":[]},"7859":{"h":"גַּמְדָּא I","r":"C01003","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּמַד\">preced.</a></div>","alt":[]},"7860":{"h":"גַּמְדָּא II","r":"C01004","html":"<div class=\"sense\"><i>Gamda;</i></div><div class=\"sense\"><b>1)</b>  pr. n. m. <span class=\"citation\">B. Kam. 72ᵃ</span> Rab. G.—<span class=\"citation\">Pes. 64ᵃ</span>; <span class=\"citation\">73ᵇ</span>; <span class=\"citation\">Ḥull. 30ᵃ</span> R. Ḥiya bar G.</div><div class=\"sense\"><b>—2)</b>  G., name of a river or canal in Babylonia. <span class=\"citation\">Ab. Zar. 39ᵃ</span>; <span class=\"citation\">Succ. 18ᵃ</span> <span dir=\"rtl\">נהר ג׳</span>.</div>","alt":[]},"7861":{"h":"גָּמָה","r":"C01005","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּמָא\">גָּמָא</a></div>","alt":[]},"7862":{"h":"גמו","r":"C01006","html":"<div class=\"sense\">, <span class=\"citation\">Ḥull. 111ᵃ</span>, v. <a href=\"#\" data-headword=\"*גְּאַם\">גְּאַם</a></div>","alt":[]},"7863":{"h":"גָּמוּד","r":"C01007","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <span dir=\"rtl\">גְּמוּדָה</span> f. (<span dir=\"rtl\">גמד</span>) <i>contracted, reduced</i>. <span class=\"citation\">Y. Yoma IV, 41ᶜ</span> bot., v. <a href=\"#\" data-headword=\"גָּדַם\">גָּדַם</a> a. <a href=\"#\" data-headword=\"אַמָּה\">אַמָּה</a>.</div>","alt":[]},"7864":{"h":"גְּמוּל","r":"C01008","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>deed, reward, recompense</i>. <span class=\"citation\">Keth. 8ᵇ</span> <span dir=\"rtl\">בעל הג׳ … גְּמוּלְכֶם</span> may He who rewards, pay you for your good deed.—Pl. <span dir=\"rtl\">גְּמוּלִים</span>, <span dir=\"rtl\">גְּמוּלִין</span>. <span class=\"citation\">Gen. R. s. 13</span> <span dir=\"rtl\">ג׳ טובים וכ׳</span> goodness bestowed on the guilty. <span class=\"citation\">Tosef. Shebi. VII, 9</span> <span dir=\"rtl\">ואין משלמין מהן ג׳</span> and favors received must not be repaid with them (the fruits of the Sabbath year); ib. <span class=\"citation\">Peah IV, 16</span>.—<span dir=\"rtl\">גְּמוּלוֹת</span>. <span class=\"citation\">Deut. R. s. 1</span> <span dir=\"rtl\">ג׳ אני פורע</span> (some ed. <span dir=\"rtl\">גמי׳</span> incorr.) I repay according to deeds.</div>","alt":[]},"7865":{"h":"גְּמוּלָא","r":"C01009","html":"<p class=\"morphology\">f.</p><div class=\"sense\">—Pl. <a href=\"#\" data-headword=\"גְּמוּלָא\">גְּמוּלָן</a>. <span class=\"citation\">Targ. Ps. CXVI, 12</span>.</div>","alt":[]},"7866":{"h":"*גְּמוּמָסִית","r":"C01010","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">גמס</span>, <i>to couple;</i> cmp. <a href=\"#\" data-headword=\"גָּמַז\">גמז</a>) <i>coupling song</i>, a sarcastic adaptation of γάμος, to deride the <i>hymenean songs</i> in their licentious application to sodomy and to copulation of animals (cmp. <a href=\"#\" data-headword=\"*אִיפֹּותוֹרוֹס\">אִיפּוֹתּוֹרוֹס</a>).—Pl. <a href=\"#\" data-headword=\"*גְּמוּמָסִית\">גְּמוּמָסִיֹּות</a>, <span dir=\"rtl\">גּוּמָּסִיֹּות</span> (Ar. ed. Koh. <span dir=\"rtl\">גַּמְסָסִיֹּות</span>). <span class=\"citation\">Gen. R. s. 26</span> the generation of the flood were not doomed to destruction <span dir=\"rtl\">עד שכתבו ג׳ לזכר ולבהמה</span> until they composed hymenean songs for sodomy &amp;c.; Tanḥ., ed. Bub., <span class=\"citation\">B’resh. 22</span> <a href=\"#\" data-headword=\"גמיקיסום\">גמיקיסום</a>; <span class=\"citation\">33</span> <span dir=\"rtl\">קמיסמסין</span>, Var. <span dir=\"rtl\">קמיסקסין</span>, Y’lamd. quot. in Ar. <a href=\"#\" data-headword=\"גמיסיקין\">גמיסיקין</a>—(perversions arisen from confounding our w. with <a href=\"#\" data-headword=\"גַּמִּיקִין\">גַּמִּיקִין</a> q. v.); <span class=\"citation\">Yalk. Gen. 43</span> <span dir=\"rtl\">גממטיות</span> (corr. acc.).; <span class=\"citation\">Lev. R. s. 23</span> <span dir=\"rtl\">גומסיות לזכר ולנקבה</span> (corr. acc.).</div>","alt":["גּוּמָּסִית"]},"7867":{"h":"*גמורקין","r":"C01011","html":"<div class=\"sense\"> or <span dir=\"rtl\">נמ׳</span>, <span class=\"citation\">Koh. R. to III, 9</span>, a corruption of <span dir=\"rtl\">אִנְבּוּרְקְרִין</span> = <a href=\"#\" data-headword=\"אִנְבּוּרְקְרָאוֹת\">אִנְבּוּרְקְרָאוֹת</a>, v. <a href=\"#\" data-headword=\"אִמְבּוּרְקְלוֹן\">אִמְבּוּרְקְלוֹן</a></div>","alt":[]},"7868":{"h":"גָּמַז","r":"C01012","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"*גְּמוּמָסִית\">גמומסית</a>), <i>Pi.</i> גִּמֵּז <i>to couple</i>, esp. <i>to suspend branches of the wild fig on the cultivated</i> (the process called caprification, v. Sm. Ant. s. v. Caprificatio). <span class=\"citation\">Tosef. Shebi. I, 11</span> <span dir=\"rtl\">ומצדדין ומְגַמְּזִין</span> ed. (missing in ed. Zuck.).</div>","alt":[]},"7869":{"h":"*גַּמְזָא","r":"C01013","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Bar Gamza</i>. <span class=\"citation\">Lam. R. to I, 15</span> (Ar. s. v. <span dir=\"rtl\">סח</span> 3: <span dir=\"rtl\">בורגיא</span>).</div>","alt":["בַּר ג׳"]},"7870":{"h":"גִּמְזוֹ","r":"C01014","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Gimzo</i>, in Judea. <span class=\"citation\">Taan. 21ᵃ</span>, a. fr. <span dir=\"rtl\">נחום איש גם זו</span>; <span class=\"citation\">Tosef. Shebu. I, 7</span> <span dir=\"rtl\">מנחם וכ׳</span> (always in two words).</div>","alt":[]},"7871":{"h":"גַּמְזוּז","r":"C01015","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גָּמַז\">גמז</a>) <i>a fig or carob ripened through caprification</i>. <span class=\"citation\">Lam. R. to I, 5</span> (Ar. <span dir=\"rtl\">גמזין</span>).</div>","alt":[]},"7872":{"h":"גַּמְזוּזִינַיָּיה","r":"C01016","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גַּמְזוּז\">preced.</a>) <i>a dish of gamzuz</i> (prepared with wine), v. <a href=\"#\" data-headword=\"אוּרְזָנַיָּיא\">אוּרְזָנַיָּיא</a>. Y. Maas. Sh. II, beg. 53ᵇ; Y. Yoma VIII, 45ᵃ top <a href=\"#\" data-headword=\"גומנני\">גומנני</a>; Y. Shebu. III, 34ᵇ bot. <a href=\"#\" data-headword=\"גמרייה\">גמרייה</a> (corr. acc. or <span dir=\"rtl\">גַּמְזַיָּיה</span>).</div>","alt":[]},"7873":{"h":"גַּמָּזִית","r":"C01017","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּמַז\">גמז</a>) </div><div class=\"sense\"><b>1)</b> <i>branches used for caprification</i>. <span class=\"citation\">Pes. IV, 8</span> (<span class=\"citation\">55ᵇ</span>) <span dir=\"rtl\">ומתירין ג׳ של הקדש</span> (ed. Y. <span dir=\"rtl\">בג׳</span>, Var. <span dir=\"rtl\">מתזירין</span>) they considered as permitted the use of branches of (carob or sycamore) trees belonging to the Temple treasury; Tosef. ib. III, 19 (Var. <span dir=\"rtl\">גזוזיות</span>, <span dir=\"rtl\">גיזות</span>); <span class=\"citation\">Men. 71ᵃ</span> <span dir=\"rtl\">ג׳ … של חרוב וכ׳</span>; <span class=\"citation\">Pes. 56ᵃ</span>; Y. ib. IV, 31ᵇ; <span class=\"citation\">Y. Peah VII, end, 20ᶜ</span>. [R. Hai Gaon reads <span dir=\"rtl\">גַּוָּאזִיּוֹת</span> <i>twigs</i>, cmp. <span dir=\"rtl\">גזוזיות</span> Var. Tosef., v. supra.]</div><div class=\"sense\"><b>—2)</b> <i>fruits ripened through caprification</i>, v. <a href=\"#\" data-headword=\"גַּמְזוּז\">גַּמְזוּז</a>. <span class=\"citation\">Tosef. Ter. V, 7</span>.</div>","alt":["גַּמָּזִיֹּות"]},"7874":{"h":"גַּמְחוּן","r":"C01018","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גַּחֲמוּן\">גַּחֲמוּן</a></div>","alt":[]},"7875":{"h":"גְּמַטְרְיָא","r":"C01019","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גֻּמְלָא\">גִּימַ׳</a></div>","alt":[]},"7876":{"h":"גְּמִי I","r":"C01020","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"גְּמִי I\">גַּמֵּי</a>, <a href=\"#\" data-headword=\"גָּמַע\">גַּמַּע</a> ch. = h. to <i>swallow, quaff</i>. <span class=\"citation\">Targ. Job XXXIX, 30</span> <span dir=\"rtl\">גָּמְעָן</span> (Ms. <span dir=\"rtl\">גַּמְעַאן</span>).—<span class=\"citation\">Y. Ab. Zar. II, 41ᶜ</span> bot. (expl. <span dir=\"rtl\">שורפה</span>, Mish. <span class=\"citation\">Ab. Zar. II, 7</span>) <span dir=\"rtl\">גמי לה</span> (ed. <a href=\"#\" data-headword=\"גמילה\">גמילה</a>, corr. acc.) he quaffs it, sucks it out. <span class=\"citation\">Succ. 49ᵇ</span> <span dir=\"rtl\">לִיגְמַע גַּמּוּעֵי</span> let him quaff (take full draughts); <span class=\"citation\">ib.</span> <span dir=\"rtl\">אגמע גמועי</span> (read: <span dir=\"rtl\">מְגַמַּע</span> with Rashi, or <a href=\"#\" data-headword=\"גָּמַע\">גַּמַּע</a>, v. Rabb. D. S. a. l. note 300). <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">וליגמע</span>.</div>","alt":["גְּמַע"]},"7877":{"h":"גְּמִי II","r":"C01021","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <span dir=\"rtl\">גּוֹמֶא</span> <i>bulrushes, reed-grass</i> (used for ropes). <span class=\"citation\">Kil. VI, 9</span>. <span class=\"citation\">Sabb. VIII, 2</span>. <span class=\"citation\">Y. Erub. I, 18ᵈ</span> <span dir=\"rtl\">וגמי על גביהן</span> and a reed-rope over them; a. fr.—Chald. form <a href=\"#\" data-headword=\"גָּמְיָיא\">גָּמְיָיא</a>. Ib.</div>","alt":[]},"7878":{"h":"גְּמִיאָה","r":"C01022","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּמָא\">גָּמָא</a>, <a href=\"#\" data-headword=\"גָּמָה\">גָּמָה</a>, <a href=\"#\" data-headword=\"גָּמַע\">גָּמַע</a>) <i>quaffing, full draught</i>. <span class=\"citation\">Sabb. VIII, 1</span> (<span class=\"citation\">76ᵇ</span>) <span dir=\"rtl\">כדי גמיא׳</span> Ms. O. a. Ar. (ed. <span dir=\"rtl\">גמיע׳</span>) as much as is quaffed at a time. Ib. 77ᵃ (discussion about spelling with <a href=\"#\" data-headword=\"א\">א</a> or <a href=\"#\" data-headword=\"ע\">ע</a>); Tosef. ib. VIII (IX), 8 (with <a href=\"#\" data-headword=\"ע\">ע</a>); Y. ib. VIII, beg. 11ᵃ <span dir=\"rtl\">גמייה</span>. <span class=\"citation\">Gen. R. s. 60</span> <span dir=\"rtl\">גמיי׳ אחת</span> (some ed. <a href=\"#\" data-headword=\"גְּמִיָּה\">גְּמִיָּה</a>) only one quaff; Tanḥ. Pinḥ. 13 <span dir=\"rtl\">כדי גמיא׳</span>; <span class=\"citation\">Num. R. s. 21</span> <a href=\"#\" data-headword=\"גָּמְיָיא\">גמייא</a> (corr. acc.); <span class=\"citation\">Midr. Prov. ch. XIII</span> <a href=\"#\" data-headword=\"גְּמִיאָה\">גמיאה</a>.—Num. R. l. c. <span dir=\"rtl\">הוא עושה גמיע׳ אחת</span> the Leviathan swallows with one quaff; <span class=\"citation\">Pesik. R. s. 16</span> (with <a href=\"#\" data-headword=\"א\">א</a>); a. fr.</div>","alt":["גְּמִיָּיה","גְּמִיעָה"]},"7879":{"h":"גְּמִיד","r":"C01023","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּמַד\">גְּמַד</a></div>","alt":[]},"7880":{"h":"גָּמְיָיא","r":"C01024","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּמִי II\"><span dir=\"rtl\">גְּמִי</span> II</a>.—[<span class=\"citation\">Num. R. s. 21</span> <span dir=\"rtl\">כדי גמייא</span>, v. <a href=\"#\" data-headword=\"גְּמִיאָה\">גְּמִיאָה</a>.]</div>","alt":[]},"7881":{"h":"גְּמִיָּה","r":"C01025","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּמִיאָה\">גְּמִיאָה</a></div>","alt":["גְּמִיָּיה"]},"7882":{"h":"גָּמֵיל","r":"C01026","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּמַל\">גְּמַל</a></div>","alt":[]},"7883":{"h":"גמילה","r":"C01027","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ab. Zar. II, 41ᶜ</span> bot., v. <a href=\"#\" data-headword=\"גְּמִי I\"><span dir=\"rtl\">גְּמִי</span> I</a></div>","alt":[]},"7884":{"h":"גְּמִילָה","r":"C01028","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"גְּמִילָה\">גְּמִילַת</a>, v. <a href=\"#\" data-headword=\"גְּמִילוּת\">גְּמִילוּת</a></div>","alt":[]},"7885":{"h":"גְּמִילוּת","r":"C01029","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span dir=\"rtl\">(גמל</span>), <span dir=\"rtl\">ג׳ חֲסָדִים</span> (also <a href=\"#\" data-headword=\"גְּמִילָה\">גְּמִילַת</a>, v. <a href=\"#\" data-headword=\"גְּמִילָה\">גְּמִילָה</a>) <i>deeds of love, charity</i> (abbr. <span dir=\"rtl\">ג&quot;ח</span>). <span class=\"citation\">Peah I, 1</span>. <span class=\"citation\">Ber. 5ᵃ</span>. <span class=\"citation\">Sot. 14ᵃ</span> the Torah <span dir=\"rtl\">תחילתה ג&quot;ח וכ׳</span> begins with charity (clothing the naked, <span class=\"citation\">Gen. III, 21</span>) and ends with charity (burying the dead, <span class=\"citation\">Deut. XXXIV, 6</span>); a. v. fr.—[<span class=\"citation\">Deut. R. s. 1</span>, v. <a href=\"#\" data-headword=\"גְּמוּל\">גְּמוּל</a>.]</div>","alt":[]},"7886":{"h":"גמיסיקין","r":"C01030","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּמִּיקִין\">גַּמִּיקִין</a> a. <a href=\"#\" data-headword=\"*גְּמוּמָסִית\"><a href=\"#\" data-headword=\"*גְּמוּמָסִית\">גְּמוּמָסִית</a>.</a></div>","alt":["גמיסקוס","גמיסקין"]},"7887":{"h":"גְּמִיעָה","r":"C01031","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּמִיאָה\">גְּמִיאָה</a></div>","alt":[]},"7888":{"h":"גמיקון","r":"C01032","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּמִּיקִין\">next w.</a></div>","alt":[]},"7889":{"h":"גַּמִּיקִין","r":"C01033","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (γαμικά, τὰ) <i>marriage, nuptial feast</i> (the guests of which are the witnesses of the marriage; v. Sm. Ant. s. v. <i>Marriage</i>)<i>;wedding contract</i>. Pesik. Haḥod. p. 52ᵇ; <span class=\"citation\">Yalk. Ex. 190</span> a king married many wives <span dir=\"rtl\">ולא כתב להם לא ג׳ ולא איפטיא</span> but did not order in their behalf a record of the nuptial act or of the date of marriage <span dir=\"rtl\">וכיון שנשא … וכתב לה ג׳ וכ׳</span> but when he married a woman of noble descent, he had her marriage recorded as we read (<span class=\"citation\">Esth. II, 16</span>) &amp;c., v. <a href=\"#\" data-headword=\"אִיפַּטְיָא\">אִיפַּטְיָא</a>; <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">כתובת גהיקן</span> (read <a href=\"#\" data-headword=\"גֻּמְלָא\">גמ׳</a>). <span class=\"citation\">Ex. R. s. 32</span> <span dir=\"rtl\">שאין ביניהם גמיסקין</span> for there is between them no wedding feast to testify to their alliance. <span class=\"citation\">Ex. R. s. 47</span> <span dir=\"rtl\">כתב לה גמיסקוס משלו</span> he had a marriage contract written at his own expense; <span dir=\"rtl\">עֲשֵׂה לה ג׳ ולואי וכ׳</span> prepare thou the certificate, and would I could prevail upon myself to lend my signature to it! [Var. in ed. a. Ar. <span dir=\"rtl\">גמיקן</span>, <a href=\"#\" data-headword=\"גמיקון\">גמיקון</a>, <a href=\"#\" data-headword=\"גמיסיקין\">גמיסקין</a>, <a href=\"#\" data-headword=\"גמיסיקין\">גמיסקוס</a>, v. Ar. ed. Koh. s. v. <span dir=\"rtl\">גמס</span>, note.—The nouns γαμισκος, γαμισκα, as if from γαμίσκω, are not otherwise recorded in the Greek vocabulary, and seem to be cacophemistic perversions; cmp. <a href=\"#\" data-headword=\"*גְּמוּמָסִית\">גמומסית</a>.]</div>","alt":[]},"7890":{"h":"גמיקיסום","r":"C01034","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גְּמוּמָסִית\">גְּמוּמָסִית</a></div>","alt":[]},"7891":{"h":"גְּמִיר","r":"C01035","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Part. pass. of <a href=\"#\" data-headword=\"גָּמָר\">גְּמַר</a>) </div><div class=\"sense\"><b>1)</b>  (= h. <a href=\"#\" data-headword=\"כָּלִיל\">כָּלִיל</a>) <i>finished, perfect</i>. <span class=\"citation\">Targ. Ez. XVI, 14</span>.</div><div class=\"sense\"><b>—2)</b> <i>holocaust, entirely burnt</i>. <span class=\"citation\">Targ. Lev. VI, 16</span>; a. fr.</div><div class=\"sense\"><b>—3)</b>  (= h. <a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a>) <a href=\"#\" data-headword=\"גְּמִיר\">גְּמִירָא</a> f. (with or without <span dir=\"rtl\">כלייה</span>) <i>entire destruction, extermination</i>. <span class=\"citation\">Targ. Gen. XVIII, 21</span> (Targ. Y. II, v. <a href=\"#\" data-headword=\"כְּלָיָיה\">כְּלָיָיה</a>). <span class=\"citation\">Targ. Jer. V, 18</span>; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>concluded, decision</i>. <span class=\"citation\">Targ. I Sam. XX, 33</span>; a. e.—V. also <a href=\"#\" data-headword=\"גְּמַר II\"><span dir=\"rtl\">גְּמַר</span> II</a>, III.</div>","alt":["גְּמִירָא"]},"7892":{"h":"גמ\"ל","r":"C01036","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גימ\">גימ&quot;ל</a></div>","alt":[]},"7893":{"h":"גָּמַל","r":"C01037","html":"<div class=\"sense\"> (b. h.) [<i>to tie, couple, load</i>,] </div><div class=\"sense\"><b>1)</b> <i>to load</i> (<i>good or evil</i>) <i>on, to deal with, </i>esp<i>.</i> <i> to do good to</i>. <span class=\"citation\">Gen. R. s. 38</span> <span dir=\"rtl\">שהוא ג׳ עליך תחלה</span> for he was the first to do thee good; <span class=\"citation\">Yalk. Prov. 956</span>.—<span class=\"citation\">Sabb. 104ᵃ</span> <span dir=\"rtl\">גְּמוֹל דלים</span>, v. <a href=\"#\" data-headword=\"גימ\">גימ&quot;ל</a>.—ג׳ חסד <i>to be kind, charitable</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שכן דרכו של גּוֹמֵל חסדים וכ׳</span> (Ms. M. <span dir=\"rtl\">דרכן של גּוֹמְלֵי</span>) for such is the habit of the charitable to run after the poor. <span class=\"citation\">Yeb. 79ᵃ</span>; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>to make even, repay.</i> <span class=\"citation\">Dem. IV, 6</span> <span dir=\"rtl\">אע&quot;פ שהן כגוֹמְלִין זה את זה</span> although it has the appearance as if they were repaying each other (by mutual recommendations). <span class=\"citation\">Ab. Zar. 61ᵇ</span> <span dir=\"rtl\">חיישינן לגומלין</span> we reject witnesses suspected of favoring each other; <span class=\"citation\">Keth. 24ᵃ</span></div><div class=\"sense\"><b>—3)</b>  (cmp. <a href=\"#\" data-headword=\"גָּמַר I\">גָּמַר</a> a. <a href=\"#\" data-headword=\"חֲסַל\">חֲסַל</a>) [<i>to finish</i>,] <i>to wean</i>. <span class=\"citation\">B. Mets. 87ᵃ</span> on that day <span dir=\"rtl\">שג׳ אברהם וכ׳</span> when Abraham celebrated the weaning of Isaac &amp;c.; <span class=\"citation\">Yalk. Gen. 93</span>; <span class=\"citation\">Deut. R. s. 1</span> <span dir=\"rtl\">שמל</span> (corr. acc.). <span class=\"citation\">Pesik. R. s. 25</span> <span dir=\"rtl\">תינוק הגָּמוּל וכ׳</span> a Jewish infant just weaned; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to ripen, be fully developed.</i> <span class=\"citation\">Par. XI, 7</span> <i>yon’koth</i> are <span dir=\"rtl\">גבעולין שלא גָמְלוּ</span> capsules of hyssop which are not yet developed; (Tosef. ib. XI (X), 7 <span dir=\"rtl\">גָּמְרוּ</span>).</div><div class=\"sense\"><b>Nif. נִגְמַל</b> <div class=\"sense\"><i>to be weaned</i>. <span class=\"citation\">Gen. R. s. 53</span> <span dir=\"rtl\">נ׳ מחלבו</span> weaned from his mother’s milk; <span dir=\"rtl\">ג׳ מיה&quot;ר</span> weaned from the evil inclination (able to resist temptation); a. fr.</div></div><div class=\"sense\"><b>Pi. גִּמֵּל</b> <div class=\"sense\"><i>to take turns</i>.—Y. M. Kat. III, 82ᵇ bot. <span dir=\"rtl\">פרה מְגַמֶּלֶת</span> a cow engaged for working in a team in turns; v. <a href=\"#\" data-headword=\"גַּמְלָא I\"><span dir=\"rtl\">גַּמְלָא</span> I</a>, 2.</div></div>","alt":[]},"7894":{"h":"גְּמַל","r":"C01038","html":"<div class=\"sense\">, <i>to do one good </i>or<i> evil</i>. <span class=\"citation\">Targ. I Sam. XXIV, 18</span>; a. fr.—Y. Ḥag. II, 77ᵈ bot. the whole town stopped work <span dir=\"rtl\">מִיגְמוֹל ליה חסד</span> in order to show kindness to him (to give him an honorable funeral).—<span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> top <span dir=\"rtl\">גָּמֵיל חיסדא</span> the charitable.</div><div class=\"sense\"><b>Ithpe. אִתְגְּמַל</b> <div class=\"sense\"><i>to be laden with; to be bestowed</i>. Targ. II Esth. V, 2 (Targ. I <span dir=\"rtl\">אטעינת</span>, h. text <span dir=\"rtl\">וַתִּשָּׂא</span>).—Y. Ḥag. l. c. <span dir=\"rtl\">לא איתג׳ ליה חסד</span> nobody cared to attend his funeral, v. supra.</div></div>","alt":[]},"7895":{"h":"גָּמָל","r":"C01039","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>carrier of loads</i>,] <i>camel</i>. <span class=\"citation\">Bekh. 8ᵃ</span>. <span class=\"citation\">Ber. 56ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">גְּמַלִּים</span>. <span class=\"citation\">Keth. 67ᵃ</span> <span dir=\"rtl\">ג׳ של ערביא וכ׳</span> camels in Arabia can be levied for a wife’s portion <a href=\"#\" data-headword=\"כְּתוּבָּה\">(כְּתוּבָּה</a>); a. fr.</div>","alt":[]},"7896":{"h":"גַּמָּל","r":"C01040","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּמָל\">preced.</a>) <i>camel-driver</i>. <span class=\"citation\">Kidd. IV, 13</span> one must not rear his son to be <span dir=\"rtl\">חמר ג׳ וכ׳</span> an ass-driver, or a camel-driver &amp;c.; Y. ib. IV, end, 66ᶜ; a. e.—Pl. <a href=\"#\" data-headword=\"גִּמְלִין\">גַּמָּלִין</a>. Ib.—Y. M. Kat. III, 62ᵃ bot. <span dir=\"rtl\">גַּמָּלָיו</span> his drivers.—<a href=\"#\" data-headword=\"חַמָּר\">חַמָּר</a> (<a href=\"#\" data-headword=\"וְ\">וְ</a>)<a href=\"#\" data-headword=\"גַּמָּל\">גַמָּל</a> ass-driver and camel-driver in one person (the camel-driver walking by the head of his beast, the ass-driver behind), <i>one walking forward and backward</i>, i.e. one who, owing to the loss of the object with which he appointed the central point for the movements of the day (v. <a href=\"#\" data-headword=\"עֵירוּב\">עֵירוּב</a>), may walk only from his home to that spot and back. <span class=\"citation\">Erub. III, 4</span> (<span class=\"citation\">35ᵃ</span>); Tosef. ib. V (IV), 2; Y. ib. III, 21ᵇ top.</div>","alt":[]},"7897":{"h":"גֻּמְלָא","r":"C01041","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. Is. III, 11</span>. <span class=\"citation\">Targ. Ps. XCIV, 2</span>. <span class=\"citation\">Ib. CXXXVII, 8</span> גַּמְ׳ Ms.; a. e.—Pl. <span dir=\"rtl\">גַּמְלַיָּא</span>. <span class=\"citation\">Targ. Is. XXXV, 4</span>.—<span class=\"citation\">Lev. R. s. 4</span> <span dir=\"rtl\">גַּמְלַיי טבייה דגמלית עימיך</span> my benefits which I bestowed on thee.</div>","alt":["גִּימְ׳","גּוּמְ׳","(גַּמְ׳)"]},"7898":{"h":"גַּמְלָא I","r":"C01042","html":"<div class=\"sense\"> c., ch. </div><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"גָּמָל\">גָּמָל</a> <i>camel</i>. <span class=\"citation\">Targ. Lev. XI, 4</span>; a. e.—<span class=\"citation\">Snh. 106ᵃ</span> (prov.) <span dir=\"rtl\">ג׳ אזלא וכ׳</span> the camel went to ask for horns, and had her ears cut off.—<span class=\"citation\">Macc. 5ᵃ</span> <span dir=\"rtl\">ג׳ פרחא</span> a flying (swift) camel, <i>dromedary;</i> <span class=\"citation\">Yeb. 116ᵃ</span>.—<span class=\"citation\">Ib. 45ᵃ</span> (prov.) <span dir=\"rtl\">ג׳ במדי וכ׳</span> in Media a camel can dance on a <i>kab</i> (bushel), i.e. in Media everything is possible. <span class=\"citation\">Sot. 13ᵇ</span>; <span class=\"citation\">Keth. 67ᵃ</span>, a. e. (prov.) <span dir=\"rtl\">לפום ג׳ שיחנא</span> according to the camel is his load, i.e. the greater the man, the greater his responsibility.—Pl. <a href=\"#\" data-headword=\"גִּמְלִין\">גַּמְלִין</a>, <span dir=\"rtl\">גַּמְלַיָּא</span>, <span dir=\"rtl\">גַּמְלֵי</span>. <span class=\"citation\">Targ. Gen. XXIV, 10</span> sq.; a. fr.—<span class=\"citation\">Gen. R. s. 38</span>.—<span class=\"citation\">Y. Hor. III, 48ᵃ</span> bot. <span dir=\"rtl\">אבא יודן דגַמְלוֹי</span> Abba Yudan who is busy among his camels; <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">דגמלי</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>couple, teaming arrangement</i>. <span class=\"citation\">M. Kat. 11ᵇ</span> <span dir=\"rtl\">הוה להו ג׳ דתורא בהדי הדדי</span> (Asheri 33 … <span dir=\"rtl\">עבוד גִּימְלָא</span>) had an arrangement between them to team their oxen for mutual work. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פסקיה לגַמְלֵיה</span> he broke the arrangement (Ms. M.; as corrected, <span dir=\"rtl\">לגמלא ולא שדריה …</span>, v. Rabb. D. S. a. l. note); v. <a href=\"#\" data-headword=\"גָּמַל\">גָּמַל</a> Pi.</div><div class=\"sense\"><b>—3)</b> <i>a small bridge, crossboard</i> (cmp. <a href=\"#\" data-headword=\"גֶּשֶׁר\">גֶּשֶׁר</a>). <span class=\"citation\">M. Kat. 6ᵇ</span> <span dir=\"rtl\">והוא דליכא גשרא … ג׳</span> provided there is neither bridge nor crossboard. <span class=\"citation\">Snh. 67ᵇ</span>, v. <a href=\"#\" data-headword=\"אוּסְקָנִיתא\">אוּסְקָנִיתָא</a>. <span class=\"citation\">B. Bath. 21ᵃ</span> <a href=\"#\" data-headword=\"ג׳\">ג׳</a> contrad. fr. <a href=\"#\" data-headword=\"תִּיתוּרָא\">תיתורא</a>. <span class=\"citation\">Snh. 7ᵃ</span>, v. <a href=\"#\" data-headword=\"גּוּדָא\">גּוּדָא</a>.</div><div class=\"sense\"><b>—4)</b> <i>large-sized</i>, v. <a href=\"#\" data-headword=\"גַּמְלָנָא\">גַּמְלָנָא</a>.</div>","alt":[]},"7899":{"h":"גַּמְלָא II","r":"C01043","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Gamala</i>, in Galilee. <span class=\"citation\">Arakh. IX, 6</span>. <span class=\"citation\">Tosef. Macc. III</span> (<span class=\"citation\">II), 2</span>; Y. ib. II, 31ᵈ <a href=\"#\" data-headword=\"גַּמְלָה\">גַּמְלָה</a>.</div>","alt":[]},"7900":{"h":"גַּמְלָא III","r":"C01044","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Gamla</i> (abbrev. of Gamliel). <span class=\"citation\">Yoma 18ᵃ</span>; <span class=\"citation\">Yeb. VI, 4</span>; <span class=\"citation\">B. Bath. 21ᵃ</span> Joshua ben G., a highpriest.—<span class=\"citation\">Gitt. 30ᵇ</span> Abba Elazar b. Gamla; <span class=\"citation\">Bets. 13ᵇ</span> <a href=\"#\" data-headword=\"גִּימֵל\">גימל</a>; <span class=\"citation\">Bekh. 58ᵇ</span>, <span class=\"citation\">Men. 54ᵇ</span> <a href=\"#\" data-headword=\"גּוּמָּל\">גומל</a> (Ms. M. <span dir=\"rtl\">גמל</span>).—<span class=\"citation\">Snh. 111ᵃ</span> R. Ḥănina b. Gamla (v. Rabb. D. S. a. l. note), usu. b. Gamliel.</div>","alt":[]},"7901":{"h":"גמלא","r":"C01045","html":"<div class=\"sense\">, <span class=\"citation\">Shek. III, 2</span>, v. <a href=\"#\" data-headword=\"גַּמָּא\">גַּמָּא</a></div>","alt":[]},"7902":{"h":"גַּמְלָה","r":"C01046","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּמְלָא II\"><span dir=\"rtl\">גַּמְלָא</span> II</a></div>","alt":[]},"7903":{"h":"גַּמְלוֹן","r":"C01047","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (deriv. of <a href=\"#\" data-headword=\"גָּמָל\">גָּמָל</a>) <i>large-sized</i> (bean).—Pl. <span dir=\"rtl\">גַּמְלוֹנִים</span>, <span dir=\"rtl\">גַּמְלוֹנִין</span>. <span class=\"citation\">Shebi. II, 8</span>; <span class=\"citation\">Kil. III, 2</span>. <span dir=\"rtl\">גמלנים</span> ed., v. <a href=\"#\" data-headword=\"אָפוּן\">אָפוּן</a>.—<span class=\"citation\">Tosef. Kil. II, 8</span> <span dir=\"rtl\">פולין הג׳</span> (v. ed. Zuck. note). <span class=\"citation\">Tosef. T’bul Yom I, 1</span>.</div>","alt":[]},"7904":{"h":"גַּמְלִיאֵל","r":"C01048","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (b. h.) <i>Gamaliel, Gamliel;</i> </div><div class=\"sense\"><b>1)</b>  Tannaim, a) Rabban G. senior <span dir=\"rtl\">(הזקן</span>), grandson of Hillel. <span class=\"citation\">R. Hash. II, 5</span>. <span class=\"citation\">Gitt. IV, 2</span>; a. fr.—b) Rabban G. (of Jabneh), grandson of the former. <span class=\"citation\">Ber. I, 1</span>. <span class=\"citation\">Peah VI, 6</span>.—<span class=\"citation\">Ber. 27ᵇ</span> sq. <span class=\"citation\">Tosef. Nidd. IX, 17</span>; a. fr. (v. Frank. Darkhé Mish. p. 69).</div><div class=\"sense\"><b>—2)</b>  Amoraim, a) R. G. B’ribbi (Bar Rabbi) I, son of R. Judah han-Nasi I. <span class=\"citation\"><span class=\"citation\">Y. Ḥall. IV, 60ᵃ</span></span> top <span dir=\"rtl\">ר׳ ג׳ ב&quot;ר</span>. <span class=\"citation\">Keth. 103ᵇ</span>. <span class=\"citation\">Ib. 10ᵇ</span>. <span class=\"citation\">Men. 84ᵇ</span>; a. e. [<span class=\"citation\">Ab. II, 2</span>.]—b) R. G. B’ribbi II, son of R. Judah han-Nasi II. <span class=\"citation\">Y. Ab. Zar. I, 39ᵇ</span>.—c) (also <span dir=\"rtl\">גַּמְלִיֵּיל</span>) G. Zuga <span class=\"citation\"><span class=\"citation\">Y. Ḥall. IV, 60ᵃ</span></span> top; a. fr.; a. others (v. Frank. M’bo p. 72ᵃ sq.).</div>","alt":[]},"7905":{"h":"גִּמְלִין","r":"C01049","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"גימ\">גימ&quot;ל</a>.</div>","alt":[]},"7906":{"h":"גַּמְלָן","r":"C01050","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּמְלוֹן\">גַּמְלוֹן</a></div>","alt":[]},"7907":{"h":"גַּמְלָנָא","r":"C01051","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>large-sized</i>. <span class=\"citation\">Sabb. 66ᵇ</span> שומשמנא ג׳ Ar. (ed. <a href=\"#\" data-headword=\"גמלא\">גמלא</a>) a large ant.—<span class=\"citation\">Ab. Zar. 28ᵇ</span>, v. <a href=\"#\" data-headword=\"חִיפּוּשִׂיתָא\">חִיפּוּשִׁיתָא</a>.</div>","alt":["גַּמְלָנִיתָא"]},"7908":{"h":"גַּמֶּלֶת","r":"C01052","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גַּמָּל\">גַּמָּל</a>) <i>a caravan of camel-drivers</i>. <span class=\"citation\">Snh. X, 5</span> (<span class=\"citation\">111ᵇ</span>); <span class=\"citation\">Snh. 112ᵃ</span>; <span class=\"citation\">B. Bath. 8ᵃ</span></div>","alt":[]},"7909":{"h":"גְּמַלְתָּא","r":"C01053","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גַּמְלָא I\">גַּמְלָא</a>) <i>stock of camels</i>. <span class=\"citation\">Gen. R. s. 75</span> (ref. to generic sing. <span dir=\"rtl\">שור חמור</span>, <span class=\"citation\">Gen. XXXII, 6</span>) it is a popular expression <span dir=\"rtl\">חמורתא ג׳</span> (as we say in Chald.) the stock of asses, of camels.</div>","alt":[]},"7910":{"h":"גָּמַם","r":"C01054","html":"<div class=\"sense\"><b>1)</b> <i>to join, connect</i>. Denom. <a href=\"#\" data-headword=\"גַּם I\"><span dir=\"rtl\">גַּם</span> I</a>, II.</div><div class=\"sense\"><b>—2)</b> <i>to make even, level, smoothen, peel, raze.</i> <span class=\"citation\">Shebi. IV, 5</span> גּוֹמֵם מן הארץ Ms. M. (ed. <a href=\"#\" data-headword=\"מֵעַל\">מֵעַל</a>, Y. <span dir=\"rtl\">מֵעִם</span>) he razes (the tree) even with the ground; <span class=\"citation\">B. Bath. 80ᵇ</span> <span dir=\"rtl\">ג׳ מעם</span>. <span class=\"citation\">Tosef. Maas. Sh. V, 18</span> <span dir=\"rtl\">גּוֹמְמִין אותו</span> you may raze it (the vineyard with the fourth year’s fruits). <span class=\"citation\">Ter. IX, 7</span> <span dir=\"rtl\">עד שיָגוֹם את האוכל</span> (Y. ib. end, 46ᵈ <span dir=\"rtl\">האוכלין</span>) until he has entirely cut off what is eatable. Y. l. c. <span dir=\"rtl\">כיני מתניתן עד שיָ׳ בעלים</span> the Mishnah means, until he has razed the plant while it was yet bearing leaves. Y. Kil. V, 30ᵇ bot.; <span class=\"citation\">Y. Shebi. I, end, 33ᶜ</span> <span dir=\"rtl\">הגּוֹמֵם את כרמו וכ׳</span> he who razes his vineyard lower than a hand-breadth (above the surface); <span dir=\"rtl\">עד שיגום מעם הארץ</span> until he razes it even with the ground.—<span class=\"citation\">Ḥull. 92ᵇ</span> <span dir=\"rtl\">גּוֹמְמוֹ עם וכ׳</span> he peels the fat off even with &amp;c., opp. to <a href=\"#\" data-headword=\"חָטַט\">חָטַט</a>. <span class=\"citation\">Tosef. Kel. B. Mets. VII, 3</span> <span dir=\"rtl\">עד שֶׁיִפַּח ויָגֹם</span> (R. S. to <span class=\"citation\">Kel. XVII, 12</span> שיִנָּפַח ויִגֹּם Nif.) until one has blown it up and scraped it (polished the leather surface).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"גָּלוּם\">גָּמוּם</a> <i>levelled, smoothened</i>. <span class=\"citation\">Ḥull. 59ᵃ</span> <span dir=\"rtl\">פיה ג׳</span> her mouth is smooth i.e. toothless (Rashi: <i>cut off</i>); v. infra. <span class=\"citation\">Tosef. Bekh. IV, 16</span> <span dir=\"rtl\">איזהו גמום וכ׳</span> (ed. Zuck. <span dir=\"rtl\">נמום</span>, corr. acc.) what animal is called <i>gamum?</i> That which lacks horns, i.e. whose horns are not projecting, v. <a href=\"#\" data-headword=\"גְּמַם\">next w.</a> <span class=\"citation\">Ib. 15</span> <span dir=\"rtl\">הגומים</span> (ed. Zuck. <span dir=\"rtl\">הנימום</span>) read: <span dir=\"rtl\">הַגָּמוּם</span>.</div><div class=\"sense\"><b>Nif. נִגְמַם</b> <div class=\"sense\"><i>to be levelled, smoothened, razed.</i> <span class=\"citation\">Shebi. I, 8</span> <span dir=\"rtl\">אילן שנ׳</span> (Ms. M. <span dir=\"rtl\">שנפגם</span>) a tree which has been cut off (near the ground). <span class=\"citation\">Bekh. VI, 4</span> (<span class=\"citation\">39ᵃ</span>) the incisors <span dir=\"rtl\">שנפגמו ושנִגְמְמוּ</span> which are broken off or levelled (with the gum; cmp. <span class=\"citation\">Ḥull. 59ᵃ</span> quoted above). <span class=\"citation\">Ḥull. 70ᵃ</span> <span dir=\"rtl\">נגממו כותלי וכ׳</span> if the sides of the womb are peeled (diminished in size). Tosef. Kel. B. Mets. l. c. <span dir=\"rtl\">נגממו</span> after the leather bottles have grown too thin for holding liquids. <span class=\"citation\">Kel. XVII, 4</span> <span dir=\"rtl\">נגממו</span> if they are worn off (the sides of a vessel having become too thin), opp. <span dir=\"rtl\">נפרצו</span> broken into (Maim.: the sides have been cut off, so that nothing but the bottom remained); <span class=\"citation\">Tosef. Kel. B. Mets. VI, 9</span> <span dir=\"rtl\">נפגמו</span> ed. Zuck. (R. S. to Kel. l. c. <span dir=\"rtl\">נגממו</span>).—Trnsf. <i>to be degraded, disgraced</i>. <span class=\"citation\">Esth. R. to I, 9</span> (play on <i>gam</i> ib.) Vashti’s time has come <span dir=\"rtl\">לִיגָּמֵם</span> to be disgraced (explained <span dir=\"rtl\">ליבצר</span>).</div></div><div class=\"sense\"><b>Pi. גִּמֵּם</b> <div class=\"sense\"> as Kel. <span class=\"citation\">Gen. R. s. 38</span> when a vineyard yields no fruits, <span dir=\"rtl\">מְגַמְּמִין אותו</span> the owner cuts it down.</div></div>","alt":[]},"7911":{"h":"גְּמַם","r":"C01055","html":"<div class=\"sense\"> <span class=\"citation\">Y. Kil. II, 27ᵈ</span> <span dir=\"rtl\">גָּם כרמייא</span> razed his vineyards. <span class=\"citation\">Ḥull. 50ᵃ</span> <span dir=\"rtl\">גּוֹם שדי</span> peel it off and throw it away. <span class=\"citation\">Ib. 92ᵇ</span> <span dir=\"rtl\">גָּאִים ליה</span> ed. (Ar. <a href=\"#\" data-headword=\"גֵּיִים\">גיים</a>) peeled it off (on the surface, opp. <span dir=\"rtl\">מרטט</span>). Ib. 96ᵃ</div><div class=\"sense\"><b>Ithpe. אִיגּוֹם</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"גָּמַם\">preced.</a> Nif. Ib. 44ᵃ <span dir=\"rtl\">אִיגּוֹם אִיגּוּמֵי וכ׳</span> the chin was razed, detached without laceration from the neck, opp. <span dir=\"rtl\">איעקור</span> forcibly torn off. <span class=\"citation\">Bekh. 44ᵃ</span> <span dir=\"rtl\">אִיגּוּם איגומי</span> the horns are levelled (not projecting), opp. <span dir=\"rtl\">איעקור</span> uprooted.</div></div>","alt":["(גּוּם)"]},"7912":{"h":"גְּמָמִיּוֹת","r":"C01056","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גּוֹמָמִית\">גּוֹמָמִית</a></div>","alt":[]},"7913":{"h":"גַּמְסָסִית","r":"C01057","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גְּמוּמָסִית\">גְּמוּמָסִית</a></div>","alt":[]},"7914":{"h":"גמניא","r":"C01058","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּרְמַנְיָא\">גִּרְמַנְיָא</a></div>","alt":[]},"7915":{"h":"גָּמַע","r":"C01059","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּמָא\">גָּמָא</a> a. <a href=\"#\" data-headword=\"גְּמִי I\"><span dir=\"rtl\">גְּמִי</span> I</a></div>","alt":["גְּמַע"]},"7916":{"h":"גְּמַץ","r":"C01060","html":"<div class=\"sense\"> (v. <span dir=\"rtl\">גמם</span>) <i>to finish a pit</i>. <span class=\"citation\">Targ. Ps. VII, 16</span>.—Denom. <a href=\"#\" data-headword=\"גּוּמָּצָא\">גּוּמָּצָא</a>.</div>","alt":[]},"7917":{"h":"גָּמַר I","r":"C01061","html":"<div class=\"sense\">, <i>Pi.</i> <a href=\"#\" data-headword=\"גָּמַר II\">גִּמֵּר</a> (denom. of <a href=\"#\" data-headword=\"מוּגְמָר\">מוּגְמָר</a>, v. <a href=\"#\" data-headword=\"גּוּמְרָא\">גּוּמְרָא</a>) <i>to perfume (clothes) with burned spices</i>. <span class=\"citation\">Bets. 22ᵇ</span> <span dir=\"rtl\">לְגַמֵּר</span> for the purpose of perfuming clothes. <span class=\"citation\">Ber. 53ᵃ</span></div><div class=\"sense\"><b>Hithpa. הִתְגַּמֵּר</b> <div class=\"sense\"><i>to be perfumed, soaked with perfume</i>. <span class=\"citation\">Sabb. 18ᵃ</span> you may put <i>mugmar</i> under the clothes on the eve of Sabbath, <span dir=\"rtl\">ומִתְגַּמְּרִין והולכין וכ׳</span> and the process of soaking is continued during the entire Sabbath day. Bets. l. c. <span dir=\"rtl\">הבית מִתְגַּמֵּר מאליו</span> the room is perfumed of itself.</div></div>","alt":[]},"7918":{"h":"גְּמַר I","r":"C01062","html":"<div class=\"sense\"><i>Ithpe.</i> <a href=\"#\" data-headword=\"גְּמַר II\">אִתְגְּמַר</a> as <a href=\"#\" data-headword=\"גָּמַר I\">preced.</a> <i>Hithpa.</i> <span class=\"citation\">Targ. Cant. III, 6</span>. <span class=\"citation\">Targ. Ps. XLV, 9</span>.</div>","alt":[]},"7919":{"h":"גָּמַר II","r":"C01063","html":"<div class=\"sense\"> cmp. v. <span dir=\"rtl\">גמם</span>) </div><div class=\"sense\"><b>1)</b> <i>to polish, touch up, finish</i>. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> bot. <span dir=\"rtl\">ג׳ מלאכתו</span> when he gives to his work the finishing touch; a. fr.</div><div class=\"sense\"><b>—2)</b>  (in gen.) <i>to complete, end</i>. <span class=\"citation\">Pes. X, 7</span> <span dir=\"rtl\">גּוֹמֵר עליו את ההלל</span> he reads over it (the fourth cup) the Hallel to the end, v. <a href=\"#\" data-headword=\"הַלֵּל\">הַלֵּל</a>.—<span class=\"citation\">Tosef. Succ. III, 2</span> <span dir=\"rtl\">גּוֹמְרִין בהן וכ׳</span> on those occasions the <i>entire</i> Hallel is read; <span class=\"citation\">Ber. 14ᵃ</span>; <span class=\"citation\">Arakh. 10ᵃ</span>; <span class=\"citation\">Taan. 28ᵇ</span>. <span class=\"citation\">Ber. 13ᵇ</span> <span dir=\"rtl\">חוזר וגוֹמְרָהּ</span> (after the disciples left) did he take it up again and read the whole of the Sh’ma?—<span class=\"citation\">Y. Yeb. II, beg. 3ᶜ</span> <span dir=\"rtl\">הביאה גוֹמֶרֶת בה</span> coition consummates the levir’s marriage (Bab. <span class=\"citation\">ib. 18ᵃ</span> <span dir=\"rtl\">קונה קניין גמור</span>), v. <a href=\"#\" data-headword=\"מַאֲמָר\">מַאֲמַר</a>.—<span class=\"citation\">Y. Ber. VI, 10ᵈ</span> top <span dir=\"rtl\">ג׳ מלאכול</span> after he has finished eating; a. fr.—Euphem. <i>to gratify the sexual appetite</i>. <span class=\"citation\">Kerith. II, 4</span>. <span class=\"citation\">Pes. 87ᵃ</span> (play on <i>Gomer</i>, <span class=\"citation\">Hos. I</span>, </div><div class=\"sense\"><b>3)</b>  <span dir=\"rtl\">שהכל גּוֹמְרִים בה</span> all people could gratify their lust on her.—<span dir=\"rtl\">וְגוֹמֵר</span> (abbr. <span dir=\"rtl\">וגו׳</span>, <span dir=\"rtl\">וג׳</span>) <i>and one finishes</i> (the sentence quoted) = <i>and so forth</i>, &amp;c., a clerical term used in Bible citations to save the writing out of the entire quotation. <span class=\"citation\">Ḥull. 98ᵃ</span>. <span class=\"citation\">Gen. R. s. 51</span>, beg.; a. fr.—*<i>Part. pass</i>. <a href=\"#\" data-headword=\"גָּרוּר\">גָּמוּר</a>, f. <a href=\"#\" data-headword=\"גְּבוּרָה\">גְּמוּרָה</a> <i>finished, complete, real, valid</i>. <span class=\"citation\">Kidd. 40ᵇ</span>, a. fr. <span dir=\"rtl\">צדיק ג׳</span> a perfectly righteous man (without faults); <span dir=\"rtl\">רשע ג׳</span> a wicked man throughout (without any good quality). <span class=\"citation\">Yeb. 18ᵇ</span>, a. fr. <span dir=\"rtl\">קניין ג׳</span> real (legal) possession.—Pl. <span dir=\"rtl\">גְּמוּרִים</span>, <span dir=\"rtl\">גְּמוּרוֹת</span>. <span class=\"citation\">Ḥull. 89ᵃ</span>; a. fr.—<span class=\"citation\">Bets. 2ᵇ</span>, a. e. <span dir=\"rtl\">בצים ג׳</span> perfectly developed eggs (with shells), v. infra.—3) <i>to destroy</i>. <span class=\"citation\">Pes. 87ᵇ</span> (play on <i>Gomer</i>, v. supra) <span dir=\"rtl\">בזזו וגָמְרוּ</span> (Ms. M. <span dir=\"rtl\">גמרו וגמרו</span>) they plundered and destroyed (they destroyed thoroughly).</div><div class=\"sense\"><b>—4)</b> <i>to conclude, determine, decide.</i> <span class=\"citation\">Kel. XVI, 1</span>. <span class=\"citation\">Ber. 17ᵃ</span> <span dir=\"rtl\">גְּמוֹר בכל לבבך וכ׳</span> be determined with all thy heart &amp;c. <span class=\"citation\">Shebu. 26ᵇ</span> <span dir=\"rtl\">ג׳ בלבו</span> he resolved (vowed) in his heart, opp. <span dir=\"rtl\">הוציא בשפתיו</span>; <span class=\"citation\">Ḥag. 10ᵃ</span>.—<span class=\"citation\">Erub. 13ᵇ</span>, a. fr. <span dir=\"rtl\">נמנו וגמרו</span> they were counted (their votes were taken) and they decided.—<span class=\"citation\">Snh. III, 7</span> (<span class=\"citation\">42ᵃ</span>) <span dir=\"rtl\">גמרו את הדבר</span> when they had closed the case (being ready for publishing the sentence); a. fr.</div><div class=\"sense\"><b>—5)</b> <i>to draw a conclusion by analogy</i>. <span class=\"citation\">Sabb. 96ᵇ</span> <span dir=\"rtl\">ג׳ העברה העברה מיוה&quot;כ</span> one forms an analogy between the expressions <i>heĕbir</i> &amp;c.; a. fr.</div><div class=\"sense\"><b>—6)</b> <i>to be fully developed</i>. <span class=\"citation\">Tosef. Par. XI, 7</span>, v. <a href=\"#\" data-headword=\"גָּמַל\">גָּמַל</a>.—<span dir=\"rtl\">בצים גמורות</span>, v. supra.</div><div class=\"sense\"><b>Pi. גִּמֵּר</b> <div class=\"sense\"><b>1)</b> <i>to destroy</i>. <span class=\"citation\">Pes. 87ᵇ</span> <span dir=\"rtl\">בקשו לגַמֵּר וכ׳</span> they intented to destroy the possessions of Israel in her (Gomer’s) days, v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to develop, mature, ripen</i>. Y. Shebi. V, beg. 35ᵈ <span dir=\"rtl\">אין פירותיה׳ מְגַמְּרִין וכ׳</span> their fruits ripen only every three years.</div></div><div class=\"sense\"><b>Nif. נִגְמַר</b> <div class=\"sense\"><i>to be finished, completed</i>. <span class=\"citation\">Snh. VI, 1</span> <span dir=\"rtl\">נ׳ הדין</span> when proceedings are finished (sentence pronounced). <span class=\"citation\">Gen. R. s. 12</span> <span dir=\"rtl\">נִגְמְרָה מלאכתן</span> they were finished; a. fr.</div></div>","alt":[]},"7920":{"h":"גְּמַר II","r":"C01064","html":"<div class=\"sense\"><b>1)</b> <i>to finish</i>. <span class=\"citation\">Targ. Ps. LVII, 3</span> <span dir=\"rtl\">דְּיִגְמַר</span> (ed. Lag. <span dir=\"rtl\">די גמר</span>, corr. acc.); a. fr.—<span class=\"citation\">Pes. 55ᵃ</span> <span dir=\"rtl\">גַּמְרִינָן</span> we dare finish a work commenced. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מִיגְמַר אין אתחולי לא</span> to finish is permitted, but not to begin; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to consume, destroy</i>. <span class=\"citation\">Targ. Job I, 16</span>. <span class=\"citation\">Ib. XXII, 20</span>; a. fr. (also <i>Pa.</i>).</div><div class=\"sense\"><b>—3)</b> <i>to end, cease</i>. <span class=\"citation\">Targ. Ps. XII, 2</span> <span dir=\"rtl\">גְּמִירוּ</span> they are gone. <span class=\"citation\">Targ. Prov. V, 11</span>. <span class=\"citation\">Ib. XXII, 8</span>; a. e.</div><div class=\"sense\"><b>—4)</b> <i>to conclude, derive</i>. <span class=\"citation\">Ḥull. 98ᵇ</span> <span dir=\"rtl\">ולִיגְמַר מיניה</span> now let one draw a conclusion from this (by analogy)! <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מחידוש לא גַבְרִינָן</span> from an exception we draw no conclusions; a. fr.</div><div class=\"sense\"><b>—5)</b> <i>to be perfect, ready to answer, to know well</i>. [<span class=\"citation\">Targ. Y. Deut. VI, 7</span> <span dir=\"rtl\">ותִגְמְרִינוּן וכ׳</span>, read <span dir=\"rtl\">ותַגְ׳</span>, v. infra.]—<i>Part.</i> <a href=\"#\" data-headword=\"גְּמִיר\">גָּמֵיר</a>. <span class=\"citation\">Sabb. 63ᵃ</span> <span dir=\"rtl\">והוה גְמִירְנָא וכ׳</span> and I knew well the whole Talmud (v. Rabh. D. S. a. l.). <span class=\"citation\">Taan. 7ᵃ</span> bot. <span dir=\"rtl\">דגְמִירֵי</span> who are learned; <span class=\"citation\">ib. 7ᵇ</span> top <span dir=\"rtl\">טפי הוו ג׳</span> they would be more learned; a. fr.—Whence: <i>to learn by heart</i>, esp. <i>to learn traditional law</i> (cmp. <a href=\"#\" data-headword=\"גְּרַס II\"><span dir=\"rtl\">גְּרַס</span> II</a>). <span class=\"citation\">Targ. Job XXII, 22</span> (h. text <a href=\"#\" data-headword=\"קָח\">קח</a>, cmp. <a href=\"#\" data-headword=\"לֶקַח\">לֶקַח</a>).—Sabb. l. c. <span dir=\"rtl\">לִיגְמַר איניש והדר ליסבר</span> one must first learn traditions, and then he may reason; <span class=\"citation\">Ab. Zar. 19ᵃ</span>, v. <a href=\"#\" data-headword=\"גְּרַס II\"><span dir=\"rtl\">גְּרַס</span> II</a>.—<span class=\"citation\">Ber. 43ᵃ</span> <span dir=\"rtl\">וברכת … גַּמְרִינָן</span> and we are not sufficiently familiar with the laws concerning grace at meals. <span class=\"citation\">Yoma 29ᵃ</span> <span dir=\"rtl\">מִיגְמַר בעתיקא וכ׳</span> to remember well something old (to refresh the memory) is more difficult than to commit to memory a fresh thing. Sabb. l. c. <span dir=\"rtl\">למיגמר מיניה</span> from whom to receive traditions. <span class=\"citation\">Sot. 36ᵇ</span> <span dir=\"rtl\">לא הוה קגמר</span> he could not remember; a. fr.—<span class=\"citation\">Sabb. 96ᵇ</span> <span dir=\"rtl\">גמרא גְמִירֵי לה</span> they (the scholars) know it by tradition; <span class=\"citation\">ib. 97ᵃ</span> <span dir=\"rtl\">הילכתא ג׳ לה</span>.—<span dir=\"rtl\">גְּמִירֵי</span> they have a tradition, <i>it is a well-known maxim</i>. <span class=\"citation\">Snh. 37ᵇ</span> bot. <span class=\"citation\">Sot. 34ᵃ</span>. <span class=\"citation\">Gitt. 47ᵃ</span>; a. fr.</div><div class=\"sense\"><b>Pa. גַּמֵּר</b> <div class=\"sense\"><i>to finish; to consume</i>. <span class=\"citation\">Targ. Job XXI, 13</span> ed. (Ms. <span dir=\"rtl\">גַּמְרִין</span> Part. Pe.). <span class=\"citation\">Ib. XIII, 28</span>; a. fr.</div></div><div class=\"sense\"><b>Af. אַגְמֵיר</b> <div class=\"sense\"><i>to teach verbally</i>. <span class=\"citation\">Targ. Y. Deut. VI, 7</span> [read:] <span dir=\"rtl\">ותַגְמְרִינוּן</span> and thou shalt teach them (v. <span class=\"citation\">Ber. 13ᵇ</span>).—<span class=\"citation\">Sot. 36ᵇ</span> <span dir=\"rtl\">אַגְמְרֵיה ולא גמר</span> he taught him (the Hebrew language), but he (Pharaoh) could not remember it. <span class=\"citation\">Ḥull. 45ᵇ</span> אַגְמְרָךְ גמרא I will teach thee a tradition. <span class=\"citation\">B. Kam. 17ᵃ</span> <span dir=\"rtl\">לאַגְמוּרֵי</span> as to teaching. <span class=\"citation\">Ber. 13ᵇ</span>, v. <a href=\"#\" data-headword=\"גְּרַס II\"><span dir=\"rtl\">גְּרַס</span> II</a>.</div></div><div class=\"sense\"><b>Ithpe. אִתְגְּמַר  אִגְּמַר</b> <div class=\"sense\"><i>to be finished; to be destroyed</i>. <span class=\"citation\">Targ. Job XXIII, 17</span>. <span class=\"citation\">Targ. Ps. CIX, 23</span>.—<span class=\"citation\">Targ. Y. Num. XVIII, 14</span> <span dir=\"rtl\">דמִגְּמַר</span> (h. text <a href=\"#\" data-headword=\"חֵרֶם\">חֵרֶם</a>). <span class=\"citation\">Targ. Y. Ex. XXII, 19</span> <span dir=\"rtl\">יִתְגַּמְרוּן</span> (h. text <span dir=\"rtl\">יָחֳרָם</span>).</div></div>","alt":[]},"7921":{"h":"גָּמָר","r":"C01065","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּמַר II\">preced.</a>) <i>finishing, last touch; consummation</i>. <span class=\"citation\">Sabb. 103ᵃ</span>, a. fr. <span dir=\"rtl\">ג׳ מלאכה</span> the finishing work.—<span class=\"citation\">Snh. 6ᵇ</span>; a. fr. <span dir=\"rtl\">ג׳ דין</span> close of legal proceedings.</div>","alt":["גְּמַר"]},"7922":{"h":"גְּמַר III","r":"C01066","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"גָּמָר\">same</a>, <i>finish, perfection, beauty</i>. <span class=\"citation\">Snh. 8ᵇ</span>, a. e. <span dir=\"rtl\">ג׳ דינא</span>, v. <a href=\"#\" data-headword=\"גָּמָר\">preced.</a> <span class=\"citation\">Targ. Ez. XXVII, 24</span> <span dir=\"rtl\">ג׳ מיני וכ׳</span> the perfection of all valuable things (h. text <span dir=\"rtl\">מכללים</span>). <span class=\"citation\">Ib. XXIII, 6</span> ed. Lag. (ed. <a href=\"#\" data-headword=\"גְּמִיר\">גמיר</a>, h. text <a href=\"#\" data-headword=\"תְּכֵלֶת\">תכלת</a>). <span class=\"citation\">Ib. 12</span> (h. text <span dir=\"rtl\">מכלול</span>).</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"גּוּמְרָא\">גּוּמְרָא</a>) <i>carbuncle</i>, a precious stone. <span class=\"citation\">Targ. Is. LIV, 12</span> (h. text <a href=\"#\" data-headword=\"קְדַח\">אקדח</a>).</div>","alt":[]},"7923":{"h":"גְּמָרָא","r":"C01067","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גְּמַר II\"><span dir=\"rtl\">גְּמַר</span> II</a>, 5) <i>memorizing of verbal teachings, tradition</i>. <span class=\"citation\">Ab. Zar. 19ᵃ</span> bot. <span dir=\"rtl\">הנ&quot;מ סברא אבל ג׳ מחד רבא וכ׳</span> (v. Rabb. D. S. a. l. note) this refers to reasoning (dialectics), but as to traditional laws (rules &amp;c.), it is better to study only with one teacher, in order not to be confused by varying wording; <span class=\"citation\">Yalk. Ps. 614</span>.—<span class=\"citation\">Gitt. 6ᵇ</span> <span dir=\"rtl\">הא ג׳ היא וג׳ לא שמיע ליה</span> this is merely a tradition (not to be arrived at by way of reasoning) and one may not have heard that tradition (and yet be an able man). <span class=\"citation\">B. Mets. 33ᵃ</span>; <span class=\"citation\">33ᵇ</span> <a href=\"#\" data-headword=\"ג׳\">ג׳</a> verbal study (opp. to <a href=\"#\" data-headword=\"מִשְׁנֶה I\">משנה</a> which had been put to writing). Arakḥ. 29ᵃ <span dir=\"rtl\">רב גַּמְרֵיה גמיר</span> (not <span dir=\"rtl\">גמור</span>) Rab had his own tradition about it (had it from his teacher that the Mishnah was corrupt). <span class=\"citation\">Erub. 60ᵃ</span> <span dir=\"rtl\">ג׳ גמור זמורתא תהא</span> if it is a tradition, learn it by heart, let it be like a song (the wording of which you dare not change); <span class=\"citation\">Sabb. 106ᵇ</span>; <span class=\"citation\">Ab. Zar. 32ᵇ</span>; <span class=\"citation\">Bets. 24ᵃ</span> (variously interpreted in comment.).—<span class=\"citation\">Yoma 14ᵇ</span>, a. fr. <span dir=\"rtl\">משמיה דג׳</span> as a tradition (without knowing the reasoning process, cmp. <span class=\"citation\">ib. 33ᵃ</span> bot. <span dir=\"rtl\">ג׳ גמירנא וכ׳</span>); a. fr.—<i>G’mara</i>, that part of the Talmud containing those discussions, decisions &amp;c. which, after the reduction to writing of the Mishnah, were the materials of verbal studies until they, too, were put to writing.—Abbrev. <a href=\"#\" data-headword=\"גֻּמְלָא\">גמ׳</a>, a clerical mark in the Talmud Babli editions, to indicate where the Mishnah ends, and the G’mara begins.</div>","alt":[]},"7924":{"h":"גַּמְּרִי","r":"C01068","html":"<div class=\"sense\"> (infin. Pa. of <span dir=\"rtl\">גמר</span>) <span dir=\"rtl\">לְגַ׳</span> <i>entirely</i>. *<span class=\"citation\">Targ. Job XXX, 24</span> Ms. (ed. <span dir=\"rtl\">לגרמיה</span>).—<span class=\"citation\">Pes. 55ᵇ</span>. <span class=\"citation\">B. Kam. 35ᵇ</span>; a. fr.</div>","alt":[]},"7925":{"h":"גמרייה","r":"C01069","html":"<div class=\"sense\">, <span class=\"citation\">Y. Shebu. III, 34ᵇ</span> bot., v. <a href=\"#\" data-headword=\"גַּמְזוּזִינַיָּיה\">גַּמְזוּזִינַיָּיה</a></div>","alt":[]},"7926":{"h":"גַּמְרָנָא","r":"C01070","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Denom. of <a href=\"#\" data-headword=\"גְּמָרָא\">גְּמָרָא</a>) <i>a teacher of traditions</i>. <span class=\"citation\">Pes. 105ᵇ</span></div>","alt":[]},"7927":{"h":"גְּמַשׁ","r":"C01071","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">כמש</span>) <i>to contract, bend</i>. <span class=\"citation\">Yoma 67ᵃ</span> Ms. M. 2 (v. Rabb. D. S. a. l. note 20) <span dir=\"rtl\">זימנין דגְמִישׁ רישיה ולא חזי ליה</span> sometimes the animal’s head (in falling) is bent, and he (the man) cannot see the chord.</div><div class=\"sense\"><b>Pa. גַּמֵּישׁ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"גַּמְרָנָא\">same</a>. Ib. ed. <span dir=\"rtl\">זימנין דג׳ ליה לרישיה ולאו אדעתיה</span> the animal may bend its head, and the man may not think of looking after the chord.</div></div>","alt":[]},"7928":{"h":"גַּן","r":"C01072","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a fenced-in place, garden</i>.—גַּן עֵדֶן <i>paradise, place of future reward</i>, opp. <a href=\"#\" data-headword=\"גֵּיהִינָּם\">גֵּיהִינָּם</a>. <span class=\"citation\">Pes. 54ᵃ</span>; <span class=\"citation\">Ned. 39ᵇ</span>; a. fr.—<span class=\"citation\">Gen. R. s. 15</span> beg. <span dir=\"rtl\">גן גדול מעדן</span> the garden was larger than Eden (Eden was a portion of the garden, ref. to <span class=\"citation\">Ez. XXXI, 9</span>). <span class=\"citation\">Taan. 10ᵃ</span> <span dir=\"rtl\">וגן אחד וכ׳</span> and the garden was one sixtieth portion of Eden.—Gen. R. l. c. <span dir=\"rtl\">כפיגי שהיא נתונה בגי׳</span> like a spring in a garden. <span class=\"citation\">Kil. II, 2</span> <span dir=\"rtl\">זרעוני גנה</span> garden plants. <span class=\"citation\">Ex. R. s. 31</span> <span dir=\"rtl\">גלגל שבגי׳</span> the wheel works of the well in the garden; a. fr.—Trnsf. (cmp. hortulus a. κῆπος) <i>woman</i>. <span class=\"citation\">Pirké d’R. El. ch. XXI</span> אין גן אלא האשה וכ׳ <i>gan</i> (<span class=\"citation\">Gen. III, 3</span>) means woman who is compared to a garden (ref. to <span class=\"citation\">Cant. IV, 12</span>), <span dir=\"rtl\">מה הגנה זו וכ׳</span> as a garden &amp;c. <span class=\"citation\">Cant. R. to IV, 12</span> <span dir=\"rtl\">גַּנָּתִי נעולה והיא מתגניא</span> my consort (Israel) is closed (chaste), and yet defamed.—Pl. <a href=\"#\" data-headword=\"גְּנוּת\">גַּנּוֹת</a>. <span class=\"citation\">Lev. R. s. 3</span>, beg. better off is he who owns <span dir=\"rtl\">גינה</span> one garden and &amp;c. <span dir=\"rtl\">ממי שנוטל ג׳ של וכ׳</span> than he who takes other people’s gardens on half-shares; a. fr.—<span class=\"citation\">Gen. R. s. 85</span> <span dir=\"rtl\">חורש בגנות</span> (euphem. for sexual intercourse).</div>","alt":["גַּנָּה","גִּינָּה"]},"7929":{"h":"גַּנָּא","r":"C01073","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XXXVIII, 18</span> גַּן עדן Ms. (ed. <span dir=\"rtl\">גינתא דע׳</span>); a. fr.; v. <a href=\"#\" data-headword=\"גִּינְּתָא\">גִּינְּתָא</a>.—Pl. <a href=\"#\" data-headword=\"גִּינִּין\">גִּינִּין</a>, <a href=\"#\" data-headword=\"גִּינַּיי\">גִּינַּיָיא</a>, <a href=\"#\" data-headword=\"גִּינְּתָא\">גַּנַּ׳</a>. <span class=\"citation\">Targ. II Kings IX, 27</span>.—<span class=\"citation\">Lev. R. s. 3</span>, v. <a href=\"#\" data-headword=\"אֲגַר II\"><span dir=\"rtl\">אֲגַר</span> II</a>.—ג׳ דאשקלון <i>the gardens</i> (or <i>the forts?</i>) <i>of Ascalon</i>, name of a Palestinean border place (v. Hildesh. Beitr. p. 72). <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">מן מה דתני גנויה וכ׳</span> (corr. <span dir=\"rtl\">גנייה</span>) from the expression ‘the gardens of A.’, we derive that A. itself is considered as foreign land; <span class=\"citation\">Tosef. Shebi. IV, 11</span> <span dir=\"rtl\">גיניא דא׳</span>; <span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">גבנייא דא׳</span> (prob. <span dir=\"rtl\">גִּנָּנַ׳</span>); <span class=\"citation\">Yalk. ib. 874</span> <a href=\"#\" data-headword=\"גִּינָּנַיָּא\">גִּינָּנַיָּא</a>.</div>","alt":["גִּינָּא"]},"7930":{"h":"גְּנָא","r":"C01074","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּנַח I\"><span dir=\"rtl\">גְּנַח</span> I</a> a. <a href=\"#\" data-headword=\"גני\"><a href=\"#\" data-headword=\"גני\">גני</a>.</a></div>","alt":[]},"7931":{"h":"גִּנָּאָה","r":"C01075","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּינָּאָה\">גִּינָּאָה</a></div>","alt":[]},"7932":{"h":"גְּנַאי","r":"C01076","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גני\">גני</a>) <i>disgrace, shame, blame; obscenity</i>. <span class=\"citation\">Ab. Zar. 46ᵃ</span> a byname <span dir=\"rtl\">לג׳</span> of reproach, (cacophemistic, opp. <span dir=\"rtl\">לשבח</span>). <span class=\"citation\">Kidd. 33ᵇ</span>; <span class=\"citation\">Y. Shek. V, 49ᵃ</span> bot. <span dir=\"rtl\">חד אמר לג׳</span> one says ‘they looked after Moses’ (<span class=\"citation\">Ex. XXXIII, 8</span>) with the purpose of fault-finding; Tanḥ. Ki Thissa 27. <span class=\"citation\">Meg. 25ᵇ</span> <span dir=\"rtl\">כל המקראות … לג׳ וכ׳</span> words in the Torah which, as they are written (v. <a href=\"#\" data-headword=\"כְּתִיב\">כתיב</a>), have become obscene, are in reading changed &amp;c. (<a href=\"#\" data-headword=\"שֵׁגָל\">שגל</a> changed into <span dir=\"rtl\">שכב</span> &amp;c.). <span class=\"citation\">Ber. 33ᵇ</span> <span dir=\"rtl\">ג׳ הוא לו</span> it would be offering an insult to him; a. fr.</div>","alt":[]},"7933":{"h":"גְּנַאי ²","r":"C01077","html":"<div class=\"sense\"> Targ. II Esth. I, 2. <span class=\"citation\">Targ. Y. Lev. XX, 17</span>; a. e.</div>","alt":["גְּנַיי"]},"7934":{"h":"גָּנַב","r":"C01078","html":"<div class=\"sense\"> (b. h.) [<i>to put behind, aside</i>,] <i>to steal</i>. <span class=\"citation\">Y. Snh. VIII, 26ᵇ</span> top <span dir=\"rtl\">לא תִגְנוֹב את … גוֹנֵב</span> do not carry off steathily thine own property from the thief, lest thou appear to be stealing.—<span class=\"citation\">Snh. 86ᵃ</span> <span dir=\"rtl\">גונב נפש</span> one who kidnaps a person. <span class=\"citation\">B. Kam. VII, 2</span> <span dir=\"rtl\">ג׳ על פי שנים</span> if he is convicted of stealing through two witnesses; a. fr.—<span dir=\"rtl\">ג׳ דעת</span> to <i>deceive, to create a false impression</i>. <span class=\"citation\">Ḥull. 94ᵃ</span> <span dir=\"rtl\">אסור לִגְנוֹב דעת וכ׳</span> it is forbidden to create &amp;c. (e.g. to make believe as if you opened a fresh barrel of wine as a special attention to your guest, while you would have had to do it at any rate). <span class=\"citation\">Shebu. 39ᵃ</span>; a. fr.—ג׳ עין <i>to deceive by a false impression on the eye, to delude</i>. <span class=\"citation\">B. Mets. IV, 12</span>.—Part. pass. <span dir=\"rtl\">גָּנוּב</span>, f. <a href=\"#\" data-headword=\"גְּנוּבָא\">גְּנוּבָה</a>. <span class=\"citation\">Ab. Zar. 44ᵇ</span>; <span class=\"citation\">Meïl. 7ᵇ</span> <span dir=\"rtl\">תשובה ג׳</span> a fallacious reply; v. <a href=\"#\" data-headword=\"גְּנוּבְתָּא II\"><span dir=\"rtl\">גְּנוּבְתָּא</span> II</a>.</div><div class=\"sense\"><b>Pi. גִּנֵּב</b> <div class=\"sense\"><i>to keep behind</i>. <span class=\"citation\">Ex. R. s. 5</span> <span dir=\"rtl\">היו מְגַנְּבִין את עצמן וכ׳</span> they kept themselves at a distance from Moses and then withdrew.</div></div><div class=\"sense\"><b>Nif. נִגְנַב</b> <div class=\"sense\"><b>1)</b> <i>to be stolen, kidnapped</i>. <span class=\"citation\">B. Mets. III, 1</span>. <span class=\"citation\">Gen. R. s. 84</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be deceived</i> (sub. <a href=\"#\" data-headword=\"דַּעַת\">דעת</a>). <span class=\"citation\">Tosef. B. Kam. VII, 8</span> sq.; Mekh. Mishp. N’zikin, s. 13.</div></div><div class=\"sense\"><b>Hithpa. הִתְגַּנֵּב</b> <div class=\"sense\"><i>to sneak in</i>. <span class=\"citation\">Pesik. R. s. 21</span>, <span dir=\"rtl\">היו מִתְגַּנְּבִים וכ׳</span> they used to have stealthy intercourse &amp;c. Mekh. l. c. <span dir=\"rtl\">המִתְגַּנֵּב אחר וכ׳</span> who steals himself (into the college room) behind a neighbor.</div></div>","alt":[]},"7935":{"h":"גְּנַב","r":"C01079","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. XXXI, 30</span>. <span class=\"citation\">Ib. 20</span>. <span class=\"citation\">Targ. O. Deut. XXIV, 7</span> <a href=\"#\" data-headword=\"גְּנַב\">גָּנֵיב</a> (Y. <a href=\"#\" data-headword=\"גְּנַב\">גְּנִיב</a>, corr. acc.); a. fr.—Part. pass. <a href=\"#\" data-headword=\"גְּנַב\">גְּנִיב</a>. <span class=\"citation\">Targ. O. Gen. XL, 15</span> <span dir=\"rtl\">גְּנֵיבְנָא</span> ed. Berl. I have been stolen.—Ruth R. introd. 3 (a trial before a Roman court) <span dir=\"rtl\">גְּנַבְתּוּן לא גְנַבְנוּן</span> “Ye have stolen”.—‘We have not’ …; <span dir=\"rtl\">לא גָנַבְתְּ מאן ג׳ עמך</span> “thou hast not stolen? Who has been stealing with thee?”; <span class=\"citation\">Gen. R. s. 37</span>; s. 63. <span class=\"citation\">B. Kam. 65ᵇ</span> <span dir=\"rtl\">תורא גַנְבִי מינך</span> was it an ox I stole from thee?—<span class=\"citation\">Ib. 67ᵇ</span> <span dir=\"rtl\">עד דגְנֵיב תרי</span> (he is not bound to pay) unless he stole two animals; a. fr.</div><div class=\"sense\"><b>Pa. גַּנֵּיב</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"גָּנַב\">same</a>. <span class=\"citation\">Targ. Jer. XXIII, 30</span>.—2) <a href=\"#\" data-headword=\"גָּנַב\">same</a>.</div><div class=\"sense\"><i>to go round about</i>. <span class=\"citation\">Keth. 19ᵃ</span> גַנּוֹבָא גַּנּוּבֵי למה לך וכ׳ O thou cunning man, what is the use of thy going round about?; <span class=\"citation\">Yeb. 91ᵃ</span>; <span class=\"citation\">B. Bath. 133ᵃ</span> גַּנָּבָא גנובי Ms. R. (ed. <span dir=\"rtl\">גנבא גנבי</span>, corr. acc.).—Part. pass. <span dir=\"rtl\">מְגַנַּב</span> <i>crooked</i>. <span class=\"citation\">Targ. Jud. V, 6</span> <span dir=\"rtl\">אורחן מְגַנְּבָן</span> (h. text <span dir=\"rtl\">עקלקל׳</span>).</div></div><div class=\"sense\"><b>Ithpa. אִיתְגַּנַּב</b> </div><div class=\"sense\"><b>Ithpe. אִיתְגְּנַב  אִיגְּנַב</b> <div class=\"sense\"><b>1)</b> <i>to be stolen</i>. <span class=\"citation\">Targ. Ex. XXII, 11</span>. <span class=\"citation\">Targ. Y. Gen. XL, 15</span>; a. e.—<span class=\"citation\">B. Mets. 34ᵃ</span> top <span dir=\"rtl\">מי יימר דמִיגַּנְּבָא</span> who can say that it will be stolen? <span class=\"citation\">Ib. 24ᵃ</span> <span dir=\"rtl\">אִגְּנִיב כסא וכ׳</span> a silver goblet was stolen from the inn; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to sneak away</i>. <span class=\"citation\">Targ. II Sam. XIX, 4</span>.</div></div>","alt":["גְּנֵיב"]},"7936":{"h":"גַּנָּב","r":"C01080","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>thief</i>. <span class=\"citation\">Y. Snh. VIII, 26ᵇ</span> top <span dir=\"rtl\">גָּנַב בפני עדים גַּ׳ וכ׳</span> if one carries an object off in the sight of witnesses, he is a thief (amenable to the law <span class=\"citation\">Ex. XXI, 37</span>), if in the owner’s presence, he is a robber. <span class=\"citation\">B. Kam. 57ᵃ</span> since he keeps himself hidden <span dir=\"rtl\">ג׳ הוא</span> he is a thief (not a robber). Ib., a. fr. <span dir=\"rtl\">טוען טענת ג׳</span> he pleads that a thief had stolen the object in his charge. <span class=\"citation\">Snh. 26ᵇ</span> <span dir=\"rtl\">ג׳ ניסן וכ׳</span> a thief (a laborer or tenant who takes fruits) in Nisan or in Tishri is not a thief (to be considered unfit to testify in court); a. fr.—Pl. <a href=\"#\" data-headword=\"גַּנָּבִית\">גַּנָּבִים</a>, <a href=\"#\" data-headword=\"גַּנָּבִית\">גַּנָּבִין</a>. <span class=\"citation\">Tosef. B. Kam. VII, 8</span>; Mekh. Mishp., N’zikin, s. 13; a. fr.</div>","alt":[]},"7937":{"h":"גַּנָּב ²","r":"C01081","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"גַּנָּב\">same</a>. <span class=\"citation\">Targ. Ex. XXII, 1</span>; a. e.—<span class=\"citation\">Ber. 5ᵇ</span> (prov.) <span dir=\"rtl\">בתר ג׳ גנוב וכ׳</span> steal after the thief (take thine own stealthily from him), and thou hast a taste (of theft), v. <a href=\"#\" data-headword=\"גָּנַב\">גָּנַב</a>. <span class=\"citation\">Snh. 22ᵃ</span> (prov.) <span dir=\"rtl\">חסריה לג׳ נפשיה וכ׳</span> when strength fails the thief, he pretends to be honest.—Pl. <a href=\"#\" data-headword=\"גַּנָּבִית\">גַּנָּבִין</a>, <span dir=\"rtl\">גַּנָּבַיָּא</span>, <span dir=\"rtl\">גַּנְּבֵי</span>. <span class=\"citation\">Targ. Y. Ex. XX, 13</span>; a. fr.—<span class=\"citation\">Ab. Zar. 70ᵃ</span>. <span class=\"citation\">Snh. 109ᵃ</span>, v. <a href=\"#\" data-headword=\"אַתְּ\">אַתְּ</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>cunning</i>. <span class=\"citation\">B. Bath. 133ᵃ</span>, v. <a href=\"#\" data-headword=\"גְּנַב\">גְּנַב</a> <i>Pa.</i></div>","alt":["גַּנָּבָא"]},"7938":{"h":"גָּנֵב","r":"C01082","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"גְּנֵיבָה\">גְּנֵיבָה</a> q. v.</div>","alt":[]},"7939":{"h":"גַּנָּבָא","r":"C01083","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּנָּב\">גַּנָּב</a> ch.</div>","alt":[]},"7940":{"h":"גְּנֵבָה","r":"C01084","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּנִיבָא\">גְּנִיבָה</a></div>","alt":[]},"7941":{"h":"גַּנָּבִית","r":"C01085","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"גַּנָּב\">גַּנָּב</a>) <i>inclined to steal.</i> Pl. <span dir=\"rtl\">גַּנָּבִיֹּות</span>. <span class=\"citation\">Gen. R. s. 45</span>, v. <a href=\"#\" data-headword=\"גּוֹנֶבֶת\">גֹּונֶבֶת</a>.</div>","alt":[]},"7942":{"h":"גִּנְבָּרָא","r":"C01086","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"גִּיבַּר\">גִּיבַּר</a>) <i>strong man, giant</i>.—Pl. <span dir=\"rtl\">גִּנְבָּרַיָּא</span>, <a href=\"#\" data-headword=\"גִּנְבָּרָא\">גִּנְבָּרֵי</a>. <span class=\"citation\">Targ. Prov. IX, 18</span> <span dir=\"rtl\">גנברי</span> ed. Lag. (ed. Vien. <span dir=\"rtl\">גוברי</span>, some ed. <a href=\"#\" data-headword=\"גנסרי\">גנסרי</a>, corr. acc.). <span class=\"citation\">Targ. Y. Gen. XIV, 1</span> <a href=\"#\" data-headword=\"גיובריא\">גיובריא</a> (read <span dir=\"rtl\">גִּינְבָּ׳</span>). <span class=\"citation\">Targ. Y. Deut. II, 10</span> sq. [<span class=\"citation\">Ib. 11</span> <span dir=\"rtl\">מישר גיונברי</span>, corr. acc.]</div>","alt":["גִּינְבָּרָא"]},"7943":{"h":"גִּנְבְּרָא","r":"C01087","html":"<div class=\"sense\"><i>ginger</i>, v. <a href=\"#\" data-headword=\"גִּנְגִּילוֹן\">גִּינְ׳</a>.</div>","alt":[]},"7944":{"h":"גַּנַּבְתָּא","r":"C01088","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">גנב</span>) <i>thief</i>. <span class=\"citation\">Gen. R. s. 92</span> <span dir=\"rtl\">גנבא בר ג׳</span> thief (Benjamin), son of a thief (Rachel); Tanḥ. Mikk. 10 (ref. to <span class=\"citation\">Gen. XXXI, 19</span>).</div>","alt":[]},"7945":{"h":"גִּנְגִּידִין","r":"C01089","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (γιγγίδιον) <i>gingidium</i>, a kind of chervil (bitter herb; v. Sm. Ant. s. v.). <span class=\"citation\">Y. Pes. II, 29ᶜ</span> top (expl. <a href=\"#\" data-headword=\"תַּמְכָה\">תמכה</a>).</div>","alt":[]},"7946":{"h":"גִּנְגִּילוֹן","r":"C01090","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cingulum) <i>girdle</i>, v. <a href=\"#\" data-headword=\"גִּלְגְּלִין\">גִּלְגְּלִין</a>.</div>","alt":["גִּנְגְּלוֹן","גִּינְ׳"]},"7947":{"h":"גנגלים","r":"C01091","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּלְגְּלִין\">גִּלְגְּלִין</a></div>","alt":[]},"7948":{"h":"גַּנְדַּר I","r":"C01092","html":"<div class=\"sense\"> (גדר <i>to be rounded</i>, v. <a href=\"#\" data-headword=\"גַּד II\"><span dir=\"rtl\">גַּד</span> II</a>; cmp. <span dir=\"rtl\">כדר</span>; v. Nöld. Neusyrische Gramm. p. 39) <i>to roll</i>. <span class=\"citation\">Targ. O. Gen. XXIX, 3</span>; <span class=\"citation\">8</span>; <span class=\"citation\">10</span> (ed. Berl. <a href=\"#\" data-headword=\"נְדַר I\">נדר</a>, v. Berl. Targ. O. II, p. 10; Targ. Y. ib. 13 <a href=\"#\" data-headword=\"נְדַר I\">נדר</a>, some ed. <a href=\"#\" data-headword=\"גֶּדֶר I\">גדר</a>). <span class=\"citation\">Targ. I Kings XIV, 10</span> <span dir=\"rtl\">כמא דמְגַנְדְּרִין בגולילא</span> (Var. <span dir=\"rtl\">דמנדרין</span>) as they roll with a (threshing) roller (h. text … <span dir=\"rtl\">יבער הגלל</span>).—<span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">ונִיגַנְדְּרֵיה וכ׳</span> (Rashi <span dir=\"rtl\">ולג׳</span>) and let him roll it sixty times. <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">רניגנדר</span> (some ed. <span dir=\"rtl\">וניגדר</span>).</div><div class=\"sense\"><b>Ithpa. אִיגַּנְדַּר</b> <div class=\"sense\"><i>to be rolled; to roll one’s self</i>. <span class=\"citation\">B. Kam. 35ᵃ</span> למקלייה ואִיגַּנְדּוּרֵי בקיטמא Ms. M. (ed. <span dir=\"rtl\">ואיגנדר</span>, v. Rabb. D. S. a. l. note) to burn the stack in order to roll himself in the ashes. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">קמִגַּנְדַּר בקיטמיה</span> Ms. M. he did roll himself in its ashes. <span class=\"citation\">Gitt. 77ᵇ</span> איג׳ גיטא Ar. (ed. <a href=\"#\" data-headword=\"אֲזַל I\">אזל</a>, Rashi to <span class=\"citation\">Sabb. 80ᵃ</span> quotes <span dir=\"rtl\">איג׳</span>) the letter of divorce (thrown over to the woman) rolled and fell &amp;c. <span class=\"citation\">Yeb. 17ᵃ</span> (prov.) <span dir=\"rtl\">קבא רבא … מִיגַּנְּדַּר וכ׳</span> the large and the small measure (both instruments of fraud) roll together and arrive at hell, and from hell &amp;c., i.e. all the low elements meet in those Babylonian places.</div></div>","alt":[]},"7949":{"h":"גַּנְדַּר II","r":"C01093","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"גֶּדֶר I\">גדר</a>, cmp. <a href=\"#\" data-headword=\"גָּדַר\">גָּדַר</a> <i>Hithpa.</i>), <i>Ithpa.</i> אִיגַּנְדַּר <i>to lord it</i>. <span class=\"citation\">Taan. 23ᵇ</span> <span dir=\"rtl\">מִגַּנְדְּרָא עלי</span> she lords it over me (being proud of her beauty; (Ms. M. <span dir=\"rtl\">אתא ומרדא ליה</span>).</div>","alt":[]},"7950":{"h":"גַּנְדְּרוֹפֹּוס","r":"C01094","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (corrupt. of κυνάνθροπος or of λυκάνθρωπος, sub. νόσος; for rejection of <a href=\"#\" data-headword=\"ל\">ל</a>, v. <a href=\"#\" data-headword=\"בּוּרְנִי I\">בּוּרְנִי</a>) <i>lycanthropy</i>, a form of melancholy, the patient so afflicted believing himself to be a wolf (or a dog) and spending his nights among tombstones; also (ὁ λυκάνθρωπος) <i>the person so afflicted</i>. Ḥag 3ᵇ <span dir=\"rtl\">אימר גנדריפס אחדיה</span> ed. (Ms. M. <span dir=\"rtl\">גדדפוס</span>, Var. <span dir=\"rtl\">גנדרופס</span>, <span dir=\"rtl\">גנס׳</span>, <span dir=\"rtl\">גרדפוס</span>, v. Rabb. D. S. a. l. note) say, lycanthropy has seized him.—<span class=\"citation\">Y. Gitt. VII, beg. 48ᶜ</span> <span dir=\"rtl\">היוצא בלילה קניטרופיס</span>; Y. Ter. I, 40ᵇ <a href=\"#\" data-headword=\"קנוטרוכוס\">קנוטרוכוס</a> (corr. acc.) he who goes out at nights is merely a lycanthrope (but not insane).</div>","alt":["קַנְטְרוֹפֹּוס"]},"7951":{"h":"גנדריפס","r":"C01095","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּנְדְּרוֹפֹּוס\">preced.</a></div>","alt":[]},"7952":{"h":"גְּנַהּ","r":"C01096","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּנַח I\"><span dir=\"rtl\">גְּנַח</span> I</a></div>","alt":[]},"7953":{"h":"גַּנָּה","r":"C01097","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּן\">גַּן</a></div>","alt":["גִּנָּה"]},"7954":{"h":"גָּנָה","r":"C01098","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גני\">גני</a></div>","alt":[]},"7955":{"h":"גַּנּוֹבָא","r":"C01099","html":"<div class=\"sense\"> (= <span dir=\"rtl\">גַּנָּבָא</span>) <i>cunning</i>. <span class=\"citation\">Keth. 19ᵃ</span>, v. <a href=\"#\" data-headword=\"גְּנַב\">גְּנַב</a> <i>Pa.</i></div>","alt":[]},"7956":{"h":"גְּנוּבָא","r":"C01100","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גנב</span>) <i>stolen, secret.</i> Pl. <span dir=\"rtl\">גְּנוּבַיָּא</span>. <span class=\"citation\">Targ. Prov. IX, 17</span> (Ms. <span dir=\"rtl\">גְּנִיבֵי</span>).</div>","alt":[]},"7957":{"h":"גְּנוּבְתָּא I","r":"C01101","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גנב</span>) <i>tail</i>. <span class=\"citation\">Targ. Job XL, 17</span> Ms. (ed. <span dir=\"rtl\">דונביה</span>). <span class=\"citation\">Targ. Y. Deut. XIV, 9</span> <span dir=\"rtl\">גֹּונְבֵיה</span>. <span class=\"citation\">Sabb. 77ᵇ</span>; <span class=\"citation\">M. Kat. 17ᵃ</span>; a. e.</div>","alt":["גֹּונְבָא"]},"7958":{"h":"גְּנוּבְתָּא II","r":"C01102","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">גנב</span>) </div><div class=\"sense\"><b>1)</b> <i>theft, stolen object</i>, v. <a href=\"#\" data-headword=\"גְּנֵיבוּתָא\">גְּנֵיבוּתָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>fallacy, fallacious reply</i> (v. <a href=\"#\" data-headword=\"גָּנַב\">גָּנַב</a>). <span class=\"citation\">Ab. Zar. 44ᵇ</span> <span dir=\"rtl\">מאי גְּנוּבְתֵּיה</span> wherein lies the fallacy of his answer? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">גְּנוּבְתָּהּ מהכא</span> its fallacy comes in from here (consists in this).</div>","alt":[]},"7959":{"h":"*גְּנוֹגְנִית","r":"C01103","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">גנן</span>, cmp. <a href=\"#\" data-headword=\"גִּנּוּן\">גִּנּוּן</a>) a sort of <i>parasol made of osier</i> and used by field laborers. <span class=\"citation\">Kel. XVI, 7</span> גנוגנת העני Ar. (Mish. <a href=\"#\" data-headword=\"*גְּנוֹגְנִית\">גְּנוֹגְנוֹת</a> pl., Talm. ed. <a href=\"#\" data-headword=\"*גְּנוֹגְנִית\">גנוגנית</a>, Maim. comment. ed. Derenbourg <a href=\"#\" data-headword=\"גְּנוֹנֶת\">גְּנוֹנֶת</a>). [Ar. a. R. S.: <i>the poor man’s bag</i>.]</div>","alt":["גְּנוֹגֶנֶת"]},"7960":{"h":"*גִּנּוּי","r":"C01104","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גני\">גני</a>, cmp. <a href=\"#\" data-headword=\"גְּנַאי\">גְּנַאי</a>) <i>shame</i>. <span class=\"citation\">Y. Yoma VI, 43ᶜ</span> the order of confession is <span dir=\"rtl\">עוו פשעו חטאו</span> in order not to mention <span dir=\"rtl\">גִּנּוּיָין של ישראל</span> the shame of Israel (by bringing the name of Israel in direct connection with <span dir=\"rtl\">פשעו</span> as the harshest of the three expressions).</div>","alt":[]},"7961":{"h":"גנויה","r":"C01105","html":"<div class=\"sense\">, <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span>. v. <a href=\"#\" data-headword=\"גַּנָּא\">גַּנָּא</a></div>","alt":[]},"7962":{"h":"גִּנּוּן","r":"C01106","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גנן</span>) <i>baldachin</i> (the Greek θάλαμος), <i>bride-chamber, state room</i>. <span class=\"citation\">Cant. R. to I, 4</span> (play on <i>ganno</i>, <span class=\"citation\">ib. IV, 16</span>) <span dir=\"rtl\">לגִנּוּנוֹ</span> to his state room (the Tabernacle). Ib. to V, 1; <span class=\"citation\">Num. R. s. 13</span>. <span class=\"citation\">Pesik. R. s. 5</span>.—Num. R. l. c. <span dir=\"rtl\">מהו גַנִּי גִּנּוּנִי מה הכילה וכ׳</span> <i>ganni</i> (<span class=\"citation\">Cant. IV, 16</span>) means “my state room”; as the bridal curtain is embroidered in variegated colors, so was the Tabernacle &amp;c.; a. e.</div>","alt":["גִּינּוּן"]},"7963":{"h":"גִּנּוּן ²","r":"C01107","html":"<div class=\"sense\"><b>1)</b> <i>cover, shade, baldachin;</i> esp. <i>bridal chamber, state-room</i>. <span class=\"citation\">Targ. Y. Gen. XIV, 13</span> <span dir=\"rtl\">גננא</span> cover. <span class=\"citation\">Targ. Is. IV, 5</span> <span dir=\"rtl\">בגנון</span> (read <span dir=\"rtl\">כג׳</span>, ed. Lag. <span dir=\"rtl\">כגנין</span>, h. text <span dir=\"rtl\">חפה</span>). <span class=\"citation\">Targ. Job XV, 32</span> Var. his enclosure (v. <a href=\"#\" data-headword=\"כִּילְתָא I\">כִּילְּתָא</a>) shall not be <a href=\"#\" data-headword=\"גִּנּוּן ²\">גנונא</a> ed. Lag. (ed. <span dir=\"rtl\">גננא</span>) a (wreathed) state-room (h. text <span dir=\"rtl\">רעננה</span>; cmp. <span class=\"citation\">Cant. I, 16</span>). <span class=\"citation\">Targ. Y. Ex. II, 1</span> <span dir=\"rtl\">גי׳ דהילולא</span>. <span class=\"citation\">Targ. Ps. XIX, 6</span>; a. e.—Y. Yeb. XIII, 13ᶜ bot. <span dir=\"rtl\">עבד לה גנון</span> if a bridal room is prepared for her. <span class=\"citation\">Y. Ber. II, 5ᵃ</span> they went <span dir=\"rtl\">מיעבד גְּנוּנֵיה דר׳ וכ׳</span> to prepare the bridal chamber of &amp;c.; Bab. <span class=\"citation\">Ber. 16ᵃ</span> <span dir=\"rtl\">קטרין ליה גננא</span> wreathed the bridal chamber of &amp;c. <span class=\"citation\">Ruth R. to I, 17</span> (sect. 3) [read:] <span dir=\"rtl\">דיהא גְנוּנָךְ חסר וכ׳</span> that thy state-room in the hereafter have one jewel less than &amp;c., i.e. that the jewel given thee in this world be deducted from thy future reward.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"גני\">גני</a>) <i>couch, breeding place</i>. <span class=\"citation\">Targ. Job XL, 22</span>. <span class=\"citation\">Ib. 31</span>.</div>","alt":["גְּנוּנָא","גִּינּוּ׳","גְּנָנָא"]},"7964":{"h":"גְּנוּנִים","r":"C01108","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּנִינִים\">גְּנִינִים</a></div>","alt":[]},"7965":{"h":"גְּנוּנִית","r":"C01109","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גִּנּוּן\">גִּנּוּן</a>) <i>couch</i>.—Pl. <span dir=\"rtl\">גְּנוּנִיּוֹת</span>. Y’lamd. to Deut. X, 12 quot. in Ar. (ref. to <span dir=\"rtl\">בַּגַּנִּים</span>, <span class=\"citation\">Cant. VIII, 13</span>) when the students at college sit <span dir=\"rtl\">ג׳ ג׳</span> arranged by couches (school forms).</div>","alt":[]},"7966":{"h":"גַּנּוּנִיתָא","r":"C01110","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גַּן\">גַּן</a>) (<i>hortulus</i>,) <i>garden at the house, pleasure-garden</i>. <span class=\"citation\">Targ. Y. Ex. II, 21</span>.—<span class=\"citation\">Ber. 43ᵇ</span>. Y. Kidd. IV, end, 66ᵈ <span dir=\"rtl\">ג׳ של ירק</span> vegetable garden; a. fr.—Pl. <span dir=\"rtl\">גְּנוּנְיָאתָא</span>, <a href=\"#\" data-headword=\"גְּנוּנִיתָא\">גְּנוּנְיָתָא</a>. <span class=\"citation\">B. Bath. 68ᵃ</span>; <span class=\"citation\">68ᵇ</span>.—Esp. (= <span dir=\"rtl\">גַּן עֵדֶן</span>) <i>paradise</i>. <span class=\"citation\">Targ. Y. Gen. XLVI, 17</span>; a. e.</div>","alt":["גִּינּוּ׳"]},"7967":{"h":"גְּנוּנִיתָא","r":"C01111","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>G’nunitha</i>, (<i>gardener</i>) legendary name of Esther’s attendant for the third day of the week (with ref. to <span class=\"citation\">Gen. I, 11</span>). <span class=\"citation\">Targ. Esth. II, 9</span>.</div>","alt":[]},"7968":{"h":"גְּנוֹנֶת","r":"C01112","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גְּנוֹגְנִית\">גְּנוֹגְנית</a></div>","alt":[]},"7969":{"h":"גְּנוּס","r":"C01113","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּינִיסְיָא\">גִּינִיסְיָא</a></div>","alt":["גְּנוּסִים","גְּנוּסִין"]},"7970":{"h":"גְּנוּסָא","r":"C01114","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּנִיסָא\">גְּנִיסָא</a></div>","alt":[]},"7971":{"h":"גְּנוּסְיָא","r":"C01115","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּינִיסְיָא\">גִּינִיסְיָא</a> a. <a href=\"#\" data-headword=\"גְּנִיסַיָּיא\"><a href=\"#\" data-headword=\"גְּנִיסַיָּיא\">גְּנִיסַיָּיא</a>.</a></div>","alt":[]},"7972":{"h":"גְּנוּסַיָּיא","r":"C01116","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּנִיסַיָּיא\">גְּנִיסיָּיא</a></div>","alt":[]},"7973":{"h":"גְּנוֹסַר","r":"C01117","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּינֵּיסַר\">גִּינֵּיסַר</a></div>","alt":[]},"7974":{"h":"גְּנוּת","r":"C01118","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גני\">גני</a>; v. <a href=\"#\" data-headword=\"*גִּנּוּי\">גִּנּוּי</a>) <i>blame, disgrace</i>. <span class=\"citation\">Pes. X, 4</span>. <span class=\"citation\">Arakh. 16ᵃ</span> <span dir=\"rtl\">בא לידי גְנוּתוֹ</span> may be induced to speak of his shortcomings; a. fr.</div>","alt":[]},"7975":{"h":"גּנוּתָא","r":"C01119","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. XXXIV, 14</span>. <span class=\"citation\">Targ. Koh. V, 5</span>.</div>","alt":[]},"7976":{"h":"גָּנַז","r":"C01120","html":"<div class=\"sense\"> [<i>to cut off, set aside</i>,] </div><div class=\"sense\"><b>1)</b> <i>to save, hoard up, reserve</i>. <span class=\"citation\">B. Bath. 11ᵃ</span>; <span class=\"citation\">Tosef. Peah IV, 18</span> <span dir=\"rtl\">אבותיך גָּנְזוּ וכ׳</span> thy ancestors saved (treasures) and increased the savings of their fathers. <span class=\"citation\">Ḥag. 12ᵃ</span> <span dir=\"rtl\">למי גְּנָזוֹ</span> for whom has He reserved it?; a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">גָּנוּז</span>, f. <span dir=\"rtl\">גְּנוּזָה</span> <i>reserved</i>. <span class=\"citation\">Pes. 119ᵃ</span>; <span class=\"citation\">Snh. 110ᵃ</span></div><div class=\"sense\"><b>—2)</b> <i>to remove from sight, hide</i> (in order to prevent desecration). <span class=\"citation\">Tosef. Sabb. XIII</span> (<span class=\"citation\">XIV), 5</span>; <span class=\"citation\">Sabb. 116ᵃ</span>. <span class=\"citation\">Meg. 26ᵇ</span> a book of the Law in a state of decay <span dir=\"rtl\">גּוֹנְזִין אותו וכ׳</span> is buried by the side of a scholar; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to declare a book apocryhal, to suppress, prohibit the reading of</i>. <span class=\"citation\">Pes. 56ᵃ</span> <span dir=\"rtl\">ג׳ ספר רפואות</span> suppressed the Book of Remedies. <span class=\"citation\">Sabb. 115ᵃ</span> <span dir=\"rtl\">אף הוא צוה עליו וגְנָזוֹ</span> he (R. Gamliel junior), too, gave orders about it and suppressed it; <span class=\"citation\">Tosef. ib. XIII</span> (<span class=\"citation\">XIV), 3</span>; a. fr.—<span class=\"citation\">Sabb. 30ᵇ</span> <span dir=\"rtl\">בקשו חכמים לִגְנוֹז וכ׳</span> the scholars wanted to suppress (declare uncanonical) the Book of Koheleth; a. fr.</div><div class=\"sense\"><b>Nif. נִגְנַז</b> <div class=\"sense\"><b>1)</b> <i>to disappear, be hidden</i>. <span class=\"citation\">Yoma 52ᵇ</span> <span dir=\"rtl\">משנ׳ הארון נִגְנְזָה וכ׳</span> when the Holy Ark was removed, there disappeared with it &amp;c.; <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">II), 7</span>. <span class=\"citation\">Tosef. Sot. II, 2</span> <span dir=\"rtl\">מגילתה נִגְנֶזֶת וכ׳</span> the scroll used for the suspected wife (<a href=\"#\" data-headword=\"סוֹטָה\">סוטה</a>) was hidden away under the door pivot of the Temple; a. fr.</div><div class=\"sense\"><b>—2)</b>  (of books) <i>to be prohibited, suppressed</i>. <span class=\"citation\">Sabb. 13ᵇ</span> <span dir=\"rtl\">אלמלא הוא נ׳ וכ׳</span> but for him, the Book of Ezekiel would have been suppressed; <span class=\"citation\">Ḥag. 13ᵃ</span>; <span class=\"citation\">Men. 45ᵃ</span>; a. e.</div></div>","alt":[]},"7977":{"h":"גְּנַז","r":"C01121","html":"<div class=\"sense\">, <i>to save</i>.—<span class=\"citation\">Targ. II Kings XX, 17</span>.—Part. pass. <a href=\"#\" data-headword=\"גְּנִיז\">גְּנִיז</a>, f. <a href=\"#\" data-headword=\"גְּנִיז\">גְנִיזָא</a> </div><div class=\"sense\"><b>1)</b> <i>hidden, stored up, reserved</i>. <span class=\"citation\">Targ. II Chr. XXXIV, 15</span>. <span class=\"citation\">Targ. I Sam. XXV, 29</span>.—Pl. <a href=\"#\" data-headword=\"גְּנִיסִין\">גְּנִיזִין</a>, <a href=\"#\" data-headword=\"גְּנִיז\">גְּנִיזָן</a>. <span class=\"citation\">Targ. O. Deut. XXXII, 34</span>. <span class=\"citation\">Targ. Hos. XIII, 12</span>.—<span class=\"citation\">Targ. Prov. XXX, 18</span>.</div><div class=\"sense\"><b>Ithpe. אִתְגְּנִיז</b> <div class=\"sense\"><i>to disappear</i>. <span class=\"citation\">Targ. Y. Num. XX, 2</span>; <span class=\"citation\">13</span>.</div></div>","alt":[]},"7978":{"h":"גֵּנֶז","r":"C01122","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"גְּנַז\">preced.</a>) <i>store, treasure</i>.—Pl. <span dir=\"rtl\">גְּנָזִים</span>, constr. <span dir=\"rtl\">גִּנְזֵי</span>. <span class=\"citation\">Ḥag. 12ᵇ</span>. <span class=\"citation\">Pes. 119ᵃ</span> בית גְּנָזָיו של וכ׳ Korah’s storehouse. <span class=\"citation\">Ib. 118ᵇ</span> bot. <span dir=\"rtl\">בית גִּנְזֵיהֶם</span> Ms. M. 2 (Ms. M. 1 <span dir=\"rtl\">גְּנָזָיו</span>; ed. <a href=\"#\" data-headword=\"גְּנִיזָה\">גניזה</a>, corr. acc.).</div>","alt":[]},"7979":{"h":"גִּנְזָא","r":"C01123","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"גֵּנֶז\">same</a>. <span class=\"citation\">Targ. I Sam. XXV, 29</span> <a href=\"#\" data-headword=\"גְּנַז\">גְּנַז</a>; <span class=\"citation\">Targ. Y. Deut. XXXI, 16</span> <a href=\"#\" data-headword=\"גְּנִיז\">גְּנִיז</a>.—Pl. <span dir=\"rtl\">גִּנְזִין</span>, <span dir=\"rtl\">גִּנְזֵי</span>, <span dir=\"rtl\">גְּנִיזַיָּא</span>. <span class=\"citation\">Targ. Ps. CIV, 13</span>. <span class=\"citation\">Targ. Hos. XIII, 15</span>. <span class=\"citation\">Targ. Y. Deut. XXXIII, 19</span> the hidden treasures.—<span class=\"citation\">Koh. R. to XI, 1</span> [read:] <span dir=\"rtl\">ועול לבי גנזי דידי וכ׳</span> and go into my treasury and take from there seven suits of clothes.</div><div class=\"sense\"><b>—2)</b> <i>garments kept in the royal treasury</i> (cmp. Koh. R. l. c., a. <a href=\"#\" data-headword=\"טַרְזַיָּא\">טַרְזַיָּא</a>). <span class=\"citation\">Targ. Esth. I, 3</span> <span dir=\"rtl\">גנזי מילתא</span> fine woolen garments. [<span class=\"citation\">Ab. Zar. 35ᵇ</span>, v. <a href=\"#\" data-headword=\"גַּוָּוזָא I\"><span dir=\"rtl\">גַּוָּוזָא</span> I</a>.]</div>","alt":["גְּנִיז","גְּנַז"]},"7980":{"h":"גנזבייה","r":"C01124","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גִּנְזַכָּיָיה\">גִּנְזַכָּיָיה</a></div>","alt":[]},"7981":{"h":"*גַּנְזַכָּה","r":"C01125","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> pl. <span dir=\"rtl\">גַּנְזַכִּים</span>; <span dir=\"rtl\">גנז</span>, with format. <a href=\"#\" data-headword=\"כ\">ך</a>, cmp. <span dir=\"rtl\">בזך</span>) <i>treasury, store</i>. <span class=\"citation\">Gen. R. s. 61</span> (homiletic interpret. of <a href=\"#\" data-headword=\"קְטוּרָה\">קטורה</a>, cmp. <a href=\"#\" data-headword=\"קוֹרְטוֹר\">קוֹרְטוֹר</a>) <span dir=\"rtl\">כזה שהוא חותם ג׳ ומוצאה וכ׳</span> (not <span dir=\"rtl\">ומוציאה</span>) like one who seals up a store and finds it sealed and knotted; <span class=\"citation\">Yalk. ib. 109</span> <span dir=\"rtl\">גניזבא</span> some ed. (corr. acc.); ib. Chron. 1074.</div>","alt":[]},"7982":{"h":"*גִּנְזַכָּיָיה","r":"C01126","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גִּנְזָק\">next w.</a>) <i>of Ginzak</i>. <span class=\"citation\">Y. Ber. II, 5ᵇ</span> top Benjamin of G. (<span class=\"citation\">Nidd. 65ᵃ</span> <span dir=\"rtl\">מנימין סקסנאה</span>).</div>","alt":[]},"7983":{"h":"גִּנְזָק","r":"C01127","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ginzak, Gazaka</i>, a city in the North of Media Atropatene (v. Neub. Géogr. p. 375). <span class=\"citation\">Kidd. 72ᵃ</span>; <span class=\"citation\">Yeb. 17ᵃ</span>, expl. <span dir=\"rtl\">נהר גוזן</span> (<span class=\"citation\">II Kings XVIII, 11</span>). <span class=\"citation\">Ab. Zar. 34ᵃ</span>; <span class=\"citation\">39ᵃ</span>; <span class=\"citation\">Gen. R. s. 33</span> (mentioned in connection with R. Akiba); <span class=\"citation\">Taan. 11ᵇ</span> (v. Rabb. D. S. a. l. note 7). <span class=\"citation\">Treat. S’maḥ. ch. XII</span>.</div>","alt":["גִּינְזָק"]},"7984":{"h":"גָּנַח","r":"C01128","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גּוּהָא\">גּוּהָא</a>) <i>to groan</i>, esp. </div><div class=\"sense\"><b>1)</b>  (with or without <span dir=\"rtl\">מלבו</span>) <i>to sigh heavily under an attack of angina pectoris</i>. <span class=\"citation\">Tem. 15ᵇ</span>; <span class=\"citation\">B. Kam. 80ᵃ</span>; <span class=\"citation\">Tosef. ib. VIII, 6</span>; <span class=\"citation\">Keth. 60ᵃ</span></div><div class=\"sense\"><b>—2)</b> <i>to cough and spit blood</i>. <span class=\"citation\">Gen. R. s. 32</span>, end <span dir=\"rtl\">ג׳ דם</span>; Tanḥ. Noah 9 <span dir=\"rtl\">ג׳ וכוהה דם</span>, v. <a href=\"#\" data-headword=\"כָּחַח\">כָּחַח</a>.</div>","alt":[]},"7985":{"h":"גְּנַח I","r":"C01129","html":"<div class=\"sense\">, <i>to groan, rumble</i> (of the underground thunder at earthquakes). <span class=\"citation\">Ber. 59ᵃ</span> <span dir=\"rtl\">ג׳ גוהא</span> (Ms. M. <a href=\"#\" data-headword=\"גְּנָא\">גְּנָא</a>, Ms. O. <a href=\"#\" data-headword=\"גְּנַהּ\">גְּנַהּ</a>), v. <a href=\"#\" data-headword=\"גּוּהָא\">גּוּהָא</a>.</div><div class=\"sense\"><b>Pa. גַּנַּח</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"גָּנַח\">same</a>, esp. <i>to utter disconnected sounds</i> (staccato), opp. to <span dir=\"rtl\">יליל</span> to utter a trembling plaintive sound (tremolo). <span class=\"citation\">R. Hash. 34ᵃ</span></div></div>","alt":[]},"7986":{"h":"*גְּנַה II","r":"C01130","html":"<div class=\"sense\"><i>to cut, pass swiftly</i>. <span class=\"citation\">Targ. Ps. VIII, 9</span> Ar. (ed. <span dir=\"rtl\">חליף</span>, h. text <span dir=\"rtl\">עובר</span>).</div><div class=\"sense\"><b>Pa. גַּנַּח</b> <div class=\"sense\"><i>to castrate</i>. <span class=\"citation\">B. Mets. 90ᵇ</span> top they take them stealthily <span dir=\"rtl\">ומְגַנְּחִין יתהון</span> (Ms. M. <span dir=\"rtl\">וגזזין</span>, v. <a href=\"#\" data-headword=\"גְּזַז\">גְּזַז</a>; v. Rabb. D. S. a. l. note). [<a href=\"#\" data-headword=\"גְּנַח I\">גנח</a> prob. misread for <span dir=\"rtl\">גוזז</span>, a. <span dir=\"rtl\">מגנחין</span> for <span dir=\"rtl\">מְגַוְּוזִין</span>, denom. of <a href=\"#\" data-headword=\"גַּוָּוזָא I\"><span dir=\"rtl\">גַּוָּוזָא</span> II</a>. Cmp. form of letters, <span class=\"citation\">Sabb. XII, 5</span>; <span class=\"citation\">103ᵇ</span>; <span class=\"citation\">104ᵇ</span>.]</div></div>","alt":[]},"7987":{"h":"גני","r":"C01131","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"גָּנַן\">גָּנַן</a>) <i>to cover, be covered</i>.</div><div class=\"sense\"><b>Pi. גִּינָּה  גִּנָּה</b> <div class=\"sense\"><i>to overshadow, to obscure, to put to shame; to censure</i>. <span class=\"citation\">Snh. 92ᵇ</span> <span dir=\"rtl\">היו מְגַנִּין את החמה וכ׳</span> obscured the sun with their beauty. <span class=\"citation\">Gitt. 58ᵃ</span> <span dir=\"rtl\">היו מג׳ את הפז וכ׳</span> they outshone the finest gold with their beauty. Snh. l. c. <span dir=\"rtl\">ביקש לְגַנּוֹת וכ׳</span> he would have attempted to excel all the praises &amp;c.—<span class=\"citation\">Sabb. 33ᵇ</span> <span dir=\"rtl\">שגי׳</span> who criticised (the Roman government); a. fr.—Part. pass. <span dir=\"rtl\">מְגוּנֶּה</span> <i>deserving to be covered up, reprehensible, indecent; ugly</i>. <span class=\"citation\">Pes. 3ᵃ</span> <span dir=\"rtl\">דבר מג׳</span> an ugly expression e.g. <a href=\"#\" data-headword=\"טָמֵא I\">טמא</a> in place of <span dir=\"rtl\">לא טהור</span>. <span class=\"citation\">Ber. 33ᵇ</span> <span dir=\"rtl\">הרי זה מג׳</span> he is to be reprehended; <span class=\"citation\">ib. 45ᵇ</span>, opp. <span dir=\"rtl\">משובח</span>; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְגַּנֶּה</b> <div class=\"sense\"><i>to make one’s self reprehensible, to become repulsive</i>. <span class=\"citation\">Ḥag. 15ᵇ</span> <span dir=\"rtl\">ומה למִתְגַּנִּין בה וכ׳</span> if such regard is paid to those who abuse the knowledge of the Law &amp;c., opp. <span dir=\"rtl\">משתבחין</span>. <span class=\"citation\">Kidd. 41ᵃ</span> he may see in her <span dir=\"rtl\">דבר מגינה ותִתְגַּנֶּה עליו</span> something objectionable, and she may become repulsive to him. <span class=\"citation\">Yoma 78ᵇ</span>, v. <a href=\"#\" data-headword=\"אֵיבָה\">אֵיבָה</a>. <span class=\"citation\">Keth. 65ᵇ</span>; a. fr.</div></div>","alt":["גָּנָה"]},"7988":{"h":"גְּנֵי","r":"C01132","html":"<div class=\"sense\">, <i>to be shaded, to lie down, sleep</i>. <span class=\"citation\">Targ. Job XL, 21</span>. <span class=\"citation\">Targ. Y. Deut. XXIV, 13</span>. Targ. II Esth. I, 4 <span dir=\"rtl\">מיגני</span> to recline for meals, <i>to dine;</i> a. fr.—<span class=\"citation\">Gitt. 68ᵃ</span> <span dir=\"rtl\">וגְנָא</span> and fell asleep. <span class=\"citation\">Sabb. 65ᵃ</span> did not allow his daughters <span dir=\"rtl\">גַּנְיָאן גבי הדדי</span> (Ms. M. <span dir=\"rtl\">דגַנְיָין</span>) to sleep together. <span class=\"citation\">Ib. 129ᵃ</span> <span dir=\"rtl\">ונִיגְנֵי וכ׳</span> let him lie in the sun. <span class=\"citation\">Yoma 78ᵇ</span> <span dir=\"rtl\">וליגני</span> and let him sleep (in his sandals). <span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">גְּנִי אפוריא</span> lie down on the bed. Y. Taan. I, end, 64ᵇ <span dir=\"rtl\">כותלא דגְנָאֵי ביה</span> a wall of a room in which people sleep; ib. IV, 64ᵈ bot. <span dir=\"rtl\">דגַנְיֵי</span>.—<span class=\"citation\">B. Bath. 58ᵃ</span> גָּנֵי Ar. (ed. <a href=\"#\" data-headword=\"גָּאנֵי\">גָּאנֵי</a>) is lying. [<span class=\"citation\">Ber. 59ᵃ</span> Ms. M., v. <a href=\"#\" data-headword=\"גְּנַח I\"><span dir=\"rtl\">גְּנַח</span> I</a>.]</div><div class=\"sense\"><b>Pa. גַּנֵּי</b> <div class=\"sense\"> (with <span dir=\"rtl\">על</span>) <i>to cover, protect</i>. <span class=\"citation\">Targ. Is. IV, 5</span>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 15</span>.</div></div><div class=\"sense\"><b>Af. אַגְנֵי</b> <div class=\"sense\"><i>to cause to lie down</i>. Targ. II Esth. I, 3 (2) <span dir=\"rtl\">וא׳ וכ׳</span> and made them lie down (for meals),—Snh. l. c. they had a bed <span dir=\"rtl\">דהוו מַגְנֵי עלה וכ׳</span> upon which they made strangers lie. <span class=\"citation\">Num. R. s. 18</span>; Tanḥ. Korah 10 <span dir=\"rtl\">ואַגְנִיתֵיה וכ׳</span> and made him lie down on his bed; Snh. l. c.—<span class=\"citation\">B. Mets. 84ᵇ</span> [read:] <span dir=\"rtl\">אַגְנַיִין בעיליתאי</span> hide me, I pray, in my room (v. Rashi a. Rabb. D. S. a. l. note 7). Ib. [read:] <span dir=\"rtl\">אגניתיה בעיליתיה</span> I kept his body in his room.</div></div><div class=\"sense\"><b>Ithpe. אִיתְגַּנֵּי  אִיגַּנֵּי</b> <div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גני\">preced.</a> Hithpa.) <i>to be disgraced, become repulsive</i>. <span class=\"citation\">Targ. II Chr. XV, 16</span>.—Y. Ab. Zar. III, 42ᶜ bot. [read:] <span dir=\"rtl\">דלא יהוון מִיתְגַּנִּין בי</span> that they may not be disgraced through me (be ashamed of me). <span class=\"citation\">Sabb. 140ᵇ</span> <span dir=\"rtl\">ואתי למִגַּנְיָא</span> and he may be disgraced. <span class=\"citation\">Ib. 65ᵃ</span> <span dir=\"rtl\">מידי דמִיגַּנְיָא ביה</span> something by which she is exposed. <span class=\"citation\">Keth. 65ᵇ</span> <span dir=\"rtl\">תִּתְגַּנִּי ותִתְגַּ׳</span> let her look repulsive (her husband being dead).</div></div>","alt":["גְּנָא"]},"7989":{"h":"גְּנֵיב־","r":"C01133","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּנֵב\">גָּנֵב</a></div>","alt":[]},"7990":{"h":"גְּנִיבָא","r":"C01134","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>G’niba</i>. <span class=\"citation\">Gitt. 31ᵇ</span>; <span class=\"citation\">62ᵃ</span>. Y. ib. VI, 48ᵃ bot. <span dir=\"rtl\">כהדא ג׳ אתאפק וכ׳</span> as in the case of one G’niba who was carried out to be put to death.</div>","alt":["גְּנִיבָה"]},"7991":{"h":"גְּנֵיבָה","r":"C01135","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>theft, the stolen object; deception</i>. <span class=\"citation\">B. Kam. X, 3</span> <span dir=\"rtl\">ויצא לו שם ג׳ בעיר</span> and the report of his being robbed had spread in town. <span class=\"citation\">Ib. 8</span> did not know <span dir=\"rtl\">בגְנֵיבָתוֹ</span> that it had been stolen. <span class=\"citation\">Y. Sot. III, end, 19ᵇ</span> <span dir=\"rtl\">ג׳ אחת</span> one theft; <span class=\"citation\">Kidd. 18ᵃ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">גְּנֵיבוֹ אלף</span> if what he has stolen is worth one thousand (Shekel &amp;c.); a. fr.—Pl. <a href=\"#\" data-headword=\"גְּנֵיבוּת\">גְּנֵיבוֹת</a>, <span dir=\"rtl\">גְּנֵבוֹת</span>. Ib.—Mekh. Mishp., N’zikin, s. 13 <span dir=\"rtl\">גנב שלש ג׳ וכ׳</span> he committed three frauds &amp;c., v. <a href=\"#\" data-headword=\"גָּנַב\">גָּנַב</a>. <span class=\"citation\">Num. R. s. 7</span>; a. fr.</div>","alt":["גְּנֵבָה"]},"7992":{"h":"גְּנֵיבוּת","r":"C01136","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"גְּנֵיבָה\">same</a>; <span dir=\"rtl\">ג׳ דעת</span> <i>deception</i>. <span class=\"citation\">Y. Snh. VI, 23ᵈ</span> bot., sq.</div>","alt":[]},"7993":{"h":"גְּנֵיבוּתָא","r":"C01137","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Ex. XXII, 2</span> sq. (O. <a href=\"#\" data-headword=\"גְּנוּבְתָּא I\">גְּנוּבְתָּא</a>); a. fr.—Pl. <a href=\"#\" data-headword=\"גְּנֵיבוּתָא\">גְּנֵיבָתָא</a>. <span class=\"citation\">Ab. Zar. 26ᵃ</span> <span dir=\"rtl\">עבוד ג׳</span> committed thefts.</div>","alt":["גְּנֵיבְתָּא","גְּנֵבְ׳"]},"7994":{"h":"גְּנִיגִי","r":"C01138","html":"<div class=\"sense\"><i>hunter</i>, v. <a href=\"#\" data-headword=\"קְנִיגִי\">קְנִיגִי</a>.</div>","alt":[]},"7995":{"h":"גְּנִיז","r":"C01139","html":"<div class=\"sense\"><b>1)</b>  Part. pass. of 1) Part. pass. of <a href=\"#\" data-headword=\"גְּנַז\">גְּנַז</a>.</div><div class=\"sense\"><b>—2)</b>  = <a href=\"#\" data-headword=\"גִּנְזָא\">גִּנְזָא</a>.</div>","alt":["גְּנִיזָא"]},"7996":{"h":"גְּנִיזָה","r":"C01140","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">גנז</span>) <i>removal of sacred objects</i>. <span class=\"citation\">Sabb. XVI, 1</span> <span dir=\"rtl\">טעונים ג׳</span> must be removed (in case of their being unfit for use). <span class=\"citation\">Meg. 26ᵇ</span> <span dir=\"rtl\">זו היא גְנִיזָתָן</span> this (their use for shrouds) is their removal.—[<span class=\"citation\">Pes. 118ᵇ</span> <span dir=\"rtl\">בית גניזה</span>, v. <a href=\"#\" data-headword=\"גֵּנֶז\">גֵּנֶז</a>).</div>","alt":[]},"7997":{"h":"גְּנַיי","r":"C01141","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּנַאי\">גְּנַאי</a></div>","alt":[]},"7998":{"h":"גניינן","r":"C01142","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּנִינִים\">גְּנִינִים</a></div>","alt":[]},"7999":{"h":"גנין","r":"C01143","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גִּנּוּן\">גִּנּוּן</a> ch.</div>","alt":[]}};
